const WEBUI_HELP_EXCERPTS = Dict{String,NamedTuple{(:title, :markdown, :truncated),Tuple{String,String,Bool}}}(
  "cgmes_export/#cgmes-export-webui" => (title = "Export from the Web UI", markdown = "The run option **Write MATPOWER export artifact** works the same way for\nevery case format: the network of the run is written as a new file\n`<case>_calc_<YYYYMMDD>.m` next to the other artifacts, with a header that\nnames the source case, the write time, the Sparlectra version and whether\nthe bus and branch columns carry the calculated state. The input file is\nnever written.", truncated = true),
  "cgmes_import/#cgmes-import-config" => (title = "Configuration (`cgmes_import`)", markdown = "The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with.", truncated = true),
  "cgmes_import/#cgmes_dynamics" => (title = "Dynamic data (DY profile)", markdown = "With `read_dynamics = true` the store reads the DY profile as well (profile\ntag `DY`; without the switch the file is skipped, and one import notice\nsays that a DY profile is present and not read) and the machines get their `DynamicData`\n(Dynamic Unit Data). No calculation reads it; the\nisland slack choice reads the unit type. In the Web UI the switch is\n**Read dynamic data (DY profile)** in the CGMES section of the Case page,\nsaved per case.", truncated = true),
  "configuration/#config-wrong-branch" => (title = "Wrong-branch detection semantics (rectangular PF)", markdown = "`power_flow.wrong_branch_detection` is a heuristic plausibility check of\nevery numerically converged AC result, with or without reactive limits; it\nproves nothing about the solution branch.", truncated = true),
  "configuration/#system_frequency" => (title = "System frequency", markdown = "The system frequency is a property of the network: every `Net` carries it\nas `net.nominal_frequency_hz`. `model.nominal_frequency_hz` (default 50.0,\n60 for a North American network, any positive value) sets it when the case\nstates none:", truncated = true),
  "contingency/#contingency_events" => (title = "Correlated events", markdown = "Some elements trip together: two circuits on the same towers, every\nbranch at a faulted busbar, a whole station. Such an event is one case\nwith several elements, solved in one run on the same path as N-1. Five\ngenerators build them from the topology; each returns a list of\n`ContingencyCase`s:", truncated = true),
  "contingency/#contingency_iteration_limits" => (title = "Iteration limits", markdown = "The base case of a batch is solved with `power_flow.max_iter`, every\noutage and scenario with `contingency.max_iter` (default `30`; keywords\n`maxIte` and `base_maxIte` of `runContingencies!` and `runScenarios!`;\nWeb UI: **Outage max iterations** in the N-1 contingency box of the\nSettings page). A lower outage limit keeps a large batch fast: an outage\nthat needs more steps ends as not converged instead of iterating on.", truncated = false),
  "contingency/#contingency_pairs" => (title = "N-2 pairs", markdown = "`generateBranchPairs` lists every unordered pair of closed branches\nas a case of kind `:pair`, named `P <a> + <b>`. The count grows with the\nsquare of the branch count: 74 branches give 2701 pairs, 217 give 23436.\nMore than `max_pairs` pairs (default 50000) throw before anything is\nsolved; the run never truncates silently. In the service,\n`contingency.pairs.enabled` adds the pairs to a branch N-1 of an SCF case;\na pair with the same member set as an event is listed once, as the event.", truncated = true),
  "contingency/#contingency_screening" => (title = "Screening", markdown = "With `screening_mode = :flag` (keyword on `runContingencies!` and\n`runScenarios!`, or `contingency.screening.mode` for the service and the\nWeb UI) every non-islanding single outage is first estimated with one\nWoodbury-corrected Newton step on the factorized base Jacobian; only\ncases whose estimate comes close to a limit get the full solve: a voltage\nwithin `screening.margin_pct` (default 10) percent of the band width, or\na branch whose estimated loading plus the change the outage causes on it\n(at least 1 point, at most the margin) reaches 100 percent, because the\nerror of the estimate grows with that change. Switch screening on only\nafter checking, on your own network, the screening share and that the\nflagged margins carry the violations (the reported `screened` count and\nreason breakdown).", truncated = true),
  "contingency/#contingency_warm_active_set" => (title = "Warm active set", markdown = "The base case of an N-1 batch is solved with Q limits, and on a large\nnetwork many machines end clamped. Without the warm start every outage\nstarts from the base voltages but with the file's bus types and clamps\nthe same machines again (a jump of the mismatch, about twice the Newton\nsteps). The warm active set (`contingency.warm_active_set`, default\n`true`; keyword `warm_active_set` on `runContingencies!` and\n`runScenarios!`; Web UI: the checkbox in the N-1 contingency box of the\nSettings page) starts every outage and scenario with the base case's\nclamped machines as PQ at their limit. The active set stays free: a\nmachine whose voltage recovers goes back to PV, new clamps follow the\nnormal rules.", truncated = true),
  "matpower/#matpower-options" => (title = "Option reference", markdown = "The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation.", truncated = true),
  "performance_profiling/#dishonest_newton" => (title = "Dishonest Newton", markdown = "`power_flow.jacobian_reuse: true` (keyword `jacobian_reuse = true`; Web UI:\nthe checkbox \"Dishonest Newton\" under Solver backend, below power mode)\nkeeps the Jacobian factorization for the next Newton step while the\nmismatch falls by at least `jacobian_reuse_min_reduction` (default 10) per\nstep, at most `jacobian_reuse_max_steps` (default 3) steps in a row. Off by\ndefault; it changes the iteration count, not the solution, and works with\nand without power mode. The rules are on the\nSolver Guide.", truncated = true),
  "performance_profiling/#perf-output" => (title = "Output configuration", markdown = "What a run writes besides its result: the console summary and its diagnostics, the log files, and the detailed CSV export with its writer settings.", truncated = true),
  "performance_profiling/#perf-runtime" => (title = "Runtime", markdown = "Process-level settings read once at startup: the thread report, the Julia and BLAS thread counts, and the parallel work split of the sweeps.", truncated = true),
  "performance_profiling/#power-mode" => (title = "Power mode for repeated solves", markdown = "Power mode is for the cases where one network is solved many times: a\nbenchmark on a persistent model, the scenario engine, N-1 contingency\nsweeps, Monte Carlo, outer control loops. It is off by default; a single\nrun gains nothing from it.", truncated = true),
  "performance_profiling/#power_mode_lu" => (title = "Power-mode LU: KLU or UMFPACK", markdown = "KLU's numeric refactorization is 6 to 20 times faster than UMFPACK's on\npower-flow Jacobians of 5k to 60k unknowns. On very large Jacobians it is\nthe other way round: KLU's partial pivoting takes thousands of\noff-diagonal pivots there, its factor grows well beyond the estimate of\nits analysis, and on the 82000-bus case_SyntheticUSA a power-mode run\nwith KLU took more than twice as long as one without power mode. Neither\nbackend is right for every network, so `auto` chooses per network:", truncated = true),
  "powerflow_configuration/#pf-apslf-start" => (title = "APSLF start values", markdown = "With `power_flow.apslf_start.enabled` the APSLF solver runs once before\nthe rectangular Newton-Raphson solve, at the insertion point of the\ncurrent-iteration pre-solve and with the same guard: the candidate is\nadopted only when it strictly improves the rectangular mismatch, otherwise\nthe original start values are restored. The generator always runs without\nNR polish (the Newton solve that follows does the polishing) and without Q\nlimits (`power_flow.qlimits.*` governs only the Newton solve); neither is\nconfigurable here. Requires AnalyticLoadFlow.jl; mutually exclusive with\n`power_flow.solver = apslf` and `start_mode.dc_seed_unconditional`.\nDiagnostic artifact: `apslf_start.log`.", truncated = false),
  "powerflow_configuration/#pf-current-iteration-start" => (title = "Current-iteration start options", markdown = "", truncated = true),
  "powerflow_configuration/#pf-distributed-slack" => (title = "Distributed active-power slack", markdown = "`power_flow.distributed_slack` spreads the active-power imbalance of an\nisland (load plus losses minus scheduled generation) over the participating\ngenerators instead of the reference bus. Theory, the augmented Newton\nsystem and the applicability rules: [Solver Guide](SPARLECTRADOCS/solver/).", truncated = true),
  "powerflow_configuration/#pf-external-grid" => (title = "External grid source", markdown = "`power_flow.external_grid` computes the marked slack bus as a non-ideal\nexternal-grid source: before the solve, `convertSlackToExternalGrid!` moves\nthe reference voltage to a hidden internal bus `<bus>__extgrid_int` behind\nthe feeder impedance `z = Un^2/Sk''` (split by the R/X ratio), and the\nformer slack bus becomes a solved bus whose voltage droops under load.\nTheory, the stiff limit and the short-circuit effect:\n[Slack Bus and External Grid Sources](SPARLECTRADOCS/slack_vs_source/).", truncated = true),
  "powerflow_configuration/#pf-merit" => (title = "Merit-function line search options", markdown = "`power_flow.merit` adds an Armijo sufficient-decrease test to the autodamp\nbacktracking loop of the rectangular solver; it replaces neither\nNewton-Raphson nor autodamp. Off by default, which leaves the max-mismatch\nautodamp unchanged. Requires `power_flow.autodamp = true` (validation error\notherwise). Theory: Merit-Function Line Search.", truncated = true),
  "powerflow_configuration/#pf-qlimits" => (title = "Q-limit options and guard", markdown = "How the reactive-power limits of PV machines are enforced: master switch,\nenforcement mode, when switching starts, hysteresis and release, the final\ncheck every mode ends with, and the guard for narrow ranges and remaining\nviolations. Algorithm: [Q-limits](SPARLECTRADOCS/powerlimits/) and\n[Q-limit Switching Strategy](SPARLECTRADOCS/q_limit_switching_strategy/). In the Web UI\nthese keys form the Q-limit block of the power-flow form\n([Form options](/help/reference#webui-form-options)).", truncated = true),
  "powerflow_configuration/#pf-solver-core" => (title = "Solver core options", markdown = "The options every AC run reads. The Web UI form carries the ones a run is\nusually tuned with; the rest is YAML only.", truncated = true),
  "powerflow_configuration/#pf-solver-selection" => (title = "Solver selection (rectangular vs. APSLF)", markdown = "`power_flow.solver` selects the executing solver; `power_flow.method` fixes\nthe AC formulation (`rectangular`). `apslf` routes the run through the\nexternal-solver bridge (`buildPfModel`, `solvePf(ApslfSolver(...))`,\n`applyPfSolution!`) to AnalyticLoadFlow.jl's analytic power-series solver,\na required dependency; see [External Solvers](SPARLECTRADOCS/external_solvers/).", truncated = true),
  "powerflow_configuration/#pf-start-mode" => (title = "Start mode options", markdown = "Where the Newton-Raphson iteration starts: the angle and voltage modes, the\nprofile a start is taken from, and the start projection with its DC, blend\nand ratio-profile candidates. A flat start (`power_flow.flatstart`) switches\nthe projection, the DC seed and the two modes off for the run; only the\nthree-winding star points start at a ratio. Mechanism: [Solver Guide](SPARLECTRADOCS/solver/); recipes per case:\nStart strategies.", truncated = true),
  "powerflow_configuration/#pf-trust-region" => (title = "Trust-region step control options", markdown = "`power_flow.trust_region` is a scaled-Newton trust region, an alternative\nto `power_flow.autodamp`: it caps the Newton step norm at an adaptive\nradius and accepts or rejects trials by merit decrease. Off by default;\nrequires `power_flow.autodamp = false` (both control the step length,\nenabling both is a configuration error). Theory and the dogleg mode:\nTrust-Region Step Control.", truncated = true),
  "powsybl_import/#powsybl-import-config" => (title = "Configuration (`powsybl_import`)", markdown = "The `powsybl_import` scope (canonical section `powsybl`, alias\n`powsybl_import`), see [Configuration](SPARLECTRADOCS/configuration/):", truncated = true),
  "scf/#scf-writing" => (title = "Writing a case file", markdown = "`exportSCF` writes a network as one JSON file that reads back machine-exact, with its source, the intended calculations and, on request, the solved start state; the Web UI offers the same export from the Case page.", truncated = true),
  "state_estimation/#se-bad-data" => (title = "Bad-data thresholds and robust modes", markdown = "Both limits work on the normalized residual \$r_{n,i} = r_i / \\sqrt{\\Omega_{ii}}\$,\ncomputed with the original sigmas; only the staged knees\n`robust_k1`/`robust_k2` stay on the raw ratio \$|r_i|/\\sigma_i\$. Down-weighting\nand elimination read the same quantity, so their limits are directly\ncomparable. Rule of thumb: suppression for online smoothing, elimination for\nidentification.", truncated = true),
  "state_estimation/#se-k-report" => (title = "Residual correlations (optional K-matrix report)", markdown = "With the correlation report on, each ranking row carries the maximum", truncated = true),
  "state_estimation/#se-max-eliminations" => (title = "Sequential elimination budget", markdown = "Upper bound for the sequential bad-data elimination: while the chi-square\nband test fails and a suspicious measurement (normalized residual at or\nabove 3) is localizable (`wii` > 0.3), the worst row is deactivated and the\nestimation reruns, up to this many times. `0` disables elimination\n(diagnostics only).", truncated = true),
  "state_estimation/#se-tap-exclude" => (title = "Tap estimation per transformer", markdown = "Every single transformer can be kept out of the tap estimation.\n`state_estimation.tap_estimation.exclude` lists transformers by name or\nCGMES mRID. Such a transformer keeps its transferred step, its rows say\n`status = not_estimated`, `reason = excluded`, and its step is not\ncalculated either. An entry that names no transformer of the net gives a\nwarning naming it (`runse!`, `runse_diagnostics`; the SE service writes\nit to run.log) and has no effect.", truncated = true),
  "state_estimation/#se-tap-fallback" => (title = "Tap estimation switch and fallback", markdown = "`state_estimation.tap_estimation.enabled` (default `true`, Web UI \"estimate\ntaps\") switches the tap estimation. Off, no changer becomes a state, even\none released with `setTapEstimation!`: every changer keeps its transferred\nstep (SSH profile or measurement file), and each row of `tapEstimates` and\n`se_tap_estimates.csv` says `status = not_estimated`, `reason = disabled`.\nThe rows carry `status` (`estimated`, `out_of_range` for an estimate too\nfar outside the band, `not_estimated`, `calculated` for a machine\ntransformer) and `reason` for every changer.", truncated = true),
  "state_estimation/#se_zero_injection" => (title = "Zero injections and coupler balances", markdown = "A passive bus (no load, generation or shunt) injects nothing, and so does the fused bus of a closed\ncoupler cluster whose members are all passive (with load or generation the fused bus carries the sum of\nthe member injection rows as a weighted `LINKAGG` row). A busbar joined to the network by closed\ncouplers only (no branch of its own, typed `Isolated` by the import) is a member of its cluster and\ngets its zero-injection rows like any passive bus; without them the cluster would have no balance.\nWith `state_estimation.zero_injection = on`\n(default, weighted) each balance is a pseudo-measurement with sigma\n`state_estimation.zero_injection_sigma_mva` in MVA (default 0.001 MVA, 1 kW). It counts in \$J\$ and in the ranking, is never\neliminated and leaves an injection of the order of the sigma. With `constraint` the balances are\nequality constraints \$c(x) = 0\$, solved in an extended system with Lagrange multipliers \$\\lambda\$\n(KKT). The balance then holds exactly, and the rows leave \$J\$ while the degrees of freedom stay \$m - n\$:", truncated = true),
  "state_estimation_configuration/#se-config" => (title = "State-Estimation Configuration", markdown = "The estimator reads every setting from the active configuration:\n`runse!(net)`, `runse_diagnostics`, `validate_measurements` and\n`validate_topology` take no settings.\n`with_state_estimation_config(max_iter = 12) do runse!(net) end` installs\nother values for one call and restores the previous configuration\nafterwards. The service and the Web UI install the effective configuration\nof the case (general file, case file, form values) the same way.", truncated = true),
  "state_estimation_configuration/#se-sigma-by-level" => (title = "Measurement sigma by voltage level", markdown = "`measurementStdDevs` gives one sigma per measurement type for the whole\nnetwork. Instrument transformers and metering differ between voltage\nlevels, so `state_estimation.sigma_by_voltage_level` sets the sigmas per\nlevel and measurement type in physical units. One row per level, keyed\nby the nominal voltage of the level in kV as in the network (bus `Vn`,\nmatched to 1e-6 kV). The columns of a row:", truncated = true),
  "state_estimation_extensions/#se-tap-estimation" => (title = "Transformer tap estimation", markdown = "A tap position that disagrees with the model (a stale SCADA position, a\nlocal operation) poisons the estimate around the transformer: the band test\nreports `:high` and the suspects cluster there although every telemetry row\nis healthy. Releasing the tap changers as estimation states resolves this.\nThe estimator solves with one continuous step per tap changer, rounds each\nto the nearest physical step, and solves once more with the steps fixed; the\nreported result is that of the fixed run.", truncated = true),
  "state_estimation_measurements/#se-case-file-measurements" => (title = "Case files carry their own measurements", markdown = "A [Sparlectra Case Format](SPARLECTRADOCS/scf/) case stores its measurement set inside\nthe file. An estimation on such a case needs no separate CSV; the run still\nwrites `measurements.csv` into its output directory for reproducibility.\nNaming a set explicitly takes precedence, and a set generated for the case\nreplaces the one the file carries (the newer data). Every other format\nrequires a measurement file.", truncated = true),
  "state_estimation_measurements/#se-generator-gross-error" => (title = "Bad data (k times sigma)", markdown = "Corrupts seed-randomly drawn telemetry rows by k times their sigma. `0` =\noff; `10` gives a clearly detectable bad measurement (a stuck transducer).\n**Bad data rows** says how many rows get the gross error; the seed decides\nwhich, protected `ZI` rows are never drawn, and the confirmation message\nnames every corrupted row. The diagnostics should rank exactly these rows\nfirst, the sequential elimination remove them, the robust option suppress\nthem without removal.", truncated = false),
  "state_estimation_measurements/#se-generator-noise" => (title = "Seeded noise", markdown = "Adds Gaussian noise at the per-quantity sigmas to every generated value.\nThe random generator is seeded, so regenerating with the same inputs\nreproduces the identical file.", truncated = true),
  "state_estimation_measurements/#se-generator-resolution" => (title = "Measurement resolution (U, P, Q, I, angle)", markdown = "Rounds each generated value after noise and bad data to the step an online\nsystem delivers. Default off (`0`, no rounding) for every quantity; steps in\nU kV, P MW, Q Mvar, I A and angles in degrees (form fields\n`gen_resolution_u_kv`, `gen_resolution_p_mw`, `gen_resolution_q_mvar`,\n`gen_resolution_i_a`, `gen_resolution_angle_deg`; library keyword\n`resolution` of `generateMeasurementsFromPF`). The written sigma stays the\nconfigured one: the rounding is part of the measurement error (standard\ndeviation step / sqrt(12)), so a step coarser than about sigma times\nsqrt(12) adds visible error. A rounded set names the steps in a\n`# resolution:` comment line; zero-injection and passive balance rows are\nnot rounded.", truncated = false),
  "state_estimation_measurements/#se-generator-sigmas" => (title = "Measurement sigmas (U, I, P, Q)", markdown = "Measurement accuracy per quantity in percent of the measured value (like a\ntransducer accuracy class), written into the sigma column of every\ngenerated row and used for the noise, when enabled:", truncated = true),
  "state_estimation_measurements/#se-generator-tap-error" => (title = "Tap deviation", markdown = "Generates the measurements from a network state whose transformers run the\ngiven number of mechanical tap steps off the model position (0 = off;\nwhole steps only); the model file stays untouched. **Transformers (max)**\nbounds how many transformers deviate; the seed picks them from the\nin-service, non-machine transformers with a tap changer the estimation\ncan release, and the message names the affected branches. The generator\ndoes not read `state_estimation.tap_estimation.exclude`. When the set puts\na deviation on a transformer the run keeps out, run.log names it. The\ndeviation moves one changer per transformer, the first ratio changer,\nelse the first phase changer. A machine transformer is used only when the\ncase has nothing else. The tap estimation keeps machine transformers out\nby default (`state_estimation.tap_estimation.include_machine_transformers = false`)\nand calculates their step after the estimate, so a deviation there stays\nin the estimate as a model error (`J` far above `dof`). run.log warns in\nthat case and names the key.", truncated = true),
  "state_estimation_measurements/#se-generator-v2" => (title = "Measurement generator v2", markdown = "Truth state, flow placement, passive-node handling and a target number of\ncritical measurements are configurable in the Web UI form.", truncated = true),
  "state_estimation_measurements/#se-measurement-files" => (title = "Measurement files and the SE chain", markdown = "The measurement table (first line `# sparlectra-measurement-table v1`, one\nrow per measured value, keyed by element name or CGMES mRID, values in MW,\nMVAr, A, kV and degrees) is the measurement format of Sparlectra. The Web\nUI generator and \"add noise\" write it, and the sets shipped with the demo\ncases are tables. `readMeasurementTable!(net; file)` reads one set into\n`net.measurements`; `writeMeasurementTable(file, rows)` writes rows, for\nexample from `generateMeasurementTableFromPF`. The measurement CSV v1 is\nno longer read (see Removed: measurement CSV v1).", truncated = true),
  "webui_reference/#webui-configuration" => (title = "Configuration", markdown = "**Check configuration** and **Refresh configuration** bring a local file up\nto a template that gained options. Check is a dry run against\n`src/config/configuration.yaml.example` (missing keys, deprecated\naliases, duplicate YAML keys, a preview of the refreshed YAML), nothing\nwritten. Refresh keeps existing values, adds missing keys with template\ndefaults and may normalize deprecated aliases; it never runs at startup,\nwrites a timestamped backup first, refuses on duplicate keys, and offers\nuploaded or pasted YAML as a download instead of rewriting it.\n\nThe **Configuration Editor** opens the active YAML in a textarea, validates\nit with the same parser and duplicate-key checks, writes only after\nvalidation with a timestamped backup, and warns when a case configuration\nfile still overrides the global YAML. After a save the server reloads the\nfile. The search box above the text finds plain text (**Next** / **Previous**,\nEnter / Shift+Enter) or jumps to a dotted key such as\n`power_flow.qlimits.guard.enabled`.\n\nForm values override the YAML configuration; the order is described in\n[Configuration](SPARLECTRADOCS/configuration/). Each run writes `effective_config.yaml`.\n**Ignore Web UI settings and use configuration defaults** runs with the YAML\nvalues only. `model.auto_profile: apply` may still adjust MATPOWER import\nconventions after form and API values are assembled;\n`effective_config.yaml` records that.\n\n**Help** in the header opens the help ([Web UI](/help)) inside the Web\nUI, as shipped with the running version; **Project Docs** opens the\npublished documentation (`webui.docs_base_url`). The help pages behind\nthe **?** icons carry a section of the help or of this reference in full,\nor the lead paragraph of a library section with the link to it.\n\n### [Search the help](@id webui_help_search)\n\nThe search field stands at the top of the help, of this reference and in\nthe header of every page and looks through the help, the reference and\nthe help pages of the controls. Every word entered must occur (a part of\na word is enough, case does not matter); hits appear while you type, hits\nin a heading first, each with a marked line of text. `/` focuses the\nfield, Enter opens the first hit, Esc closes the list. Without a hit the\npage links to the published documentation. The index ships with the\napplication; with scripts switched off the field is a plain form.", truncated = false),
  "webui_reference/#webui-flat-start" => (title = "Flat start", markdown = "`power_flow.flatstart` starts the Newton-Raphson solve at 1.0 pu and the\nslack angle on every bus and ignores the imported start voltages (MATPOWER\n`VM`/`VA`, CGMES `SvVoltage`, SCF `start_state`). Off, the imported values\nseed the solve; a delivery is built around its own operating point, so\nthat is the default.\n\nWhile the flat start is on, the run switches the start projection, the DC\nstart values, the two start modes and the ratio profile off, also when the configuration file\nhas `start_projection: true`. The page greys those controls (saved values\nstay) and the run log names the override. The current-iteration pre-solve\nand the APSLF start follow their own checkboxes.\n\nThree-winding star points start at the ratio of their stiffest winding on\nevery flat start; all other buses stay flat.\n\n**Flat start turned behind phase shifters**\n(`power_flow.start_mode.rotate_behind_pst`, off by default) starts a bus\nthat the slack reaches only across phase-shifting transformers at the slack\nangle plus the shifts of a path with the fewest shifters, on a flat start\nand on a stored start without angles. A bus that a path without shifter\nreaches keeps the slack angle. See\n[Start strategies by case](SPARLECTRADOCS/start_strategies/).\n\n**Ratio profile as a start candidate** (`power_flow.start_mode.ratio_profile`,\non by default) is a candidate of the start projection: the flat profile\nwith each voltage level scaled by the transformer ratios on its path from\nthe slack, applied to every PQ bus (not only to three-winding star points)\nwhen its mismatch is at least 10 percent lower. The flat start switches it\noff for the whole run, rescue and auto stages included. Without the flat\nstart it acts only where a projection starts from the flat profile: in the\nrescue ladder's alternate start, unless **Start angle mode** is `dc` (the\nDC angles keep precedence), and in the auto mode. The page greys the\ncheckbox in every other case: flat start on, or neither **Auto mode** nor\n**Rescue** with a start angle mode other than `dc`. A greyed checkbox is\nnot posted and the saved value stays.\n\nA CGMES run honours the flat start under **CGMES start values** = `auto`;\nan explicit `sv` on the Case page still starts from the delivery state\n([Power flow configuration](SPARLECTRADOCS/powerflow_configuration/#pf-solver-core)).", truncated = false),
  "webui_reference/#webui-form-options" => (title = "Form options", markdown = "The settings and run forms offer:\n\n- case name or local path, configuration template file, the read-only\n  output root (set only through `start_sparlectra_webui(; output_root)`),\n  tolerance (decimals or scientific notation such as `1e-8`; the spinner\n  steps the exponent and keeps the mantissa), maximum iterations,\n  autodamping with its minimum factor;\n- **Q-limit handling**: the `power_flow.qlimits.enabled` checkbox and the\n  enforcement-mode selector, which also offers **off**; **PV/PQ\n  switching** holds the hysteresis, the final check bound\n  (`final_q_accept_pu`, `auto` or a value in pu), the classic pass limit\n  (`classic_max_passes`), the first switching iteration (`start_iter`),\n  the switch cap per bus (`guard.max_switches`), freezing after repeated\n  switching and the guard switch (`guard.enabled`); **Advanced** holds the\n  rest of `power_flow.qlimits`\n  ([Q-limit options and guard](SPARLECTRADOCS/powerflow_configuration/#pf-qlimits)).\n  Per-unit values take scientific notation, bus lists comma-separated case\n  bus numbers. Controls a mode does not read are grayed: everything while\n  the handling is off, the start iteration and the guard rules in the\n  classic modes, the range rules without the guard;\n- **Solver**: one radio group `power_flow_solver` with `rectangular` (AC\n  Newton-Raphson), `apslf` (AnalyticLoadFlow) and `dc` (linear screening\n  model)\n  ([solver selection](SPARLECTRADOCS/powerflow_configuration/#pf-solver-selection),\n  [DC power flow](SPARLECTRADOCS/powerflow_configuration/));\n- wrong-branch detection mode, start angle and voltage modes;\n- **Advanced start values**: the current-iteration pre-solve fields\n  (`power_flow.start_current_iteration.*`,\n  [guarded pre-solve](SPARLECTRADOCS/powerflow_configuration/#pf-current-iteration-start));\n- **Merit-function line search**: `power_flow.merit.enabled`,\n  `power_flow.merit.armijo_c1`, `power_flow.merit.fallback_max_mismatch`\n  ([options](SPARLECTRADOCS/powerflow_configuration/#pf-merit)),\n  requires `power_flow.autodamp = true`;\n- **Non-convergence handling** (Advanced): `power_flow.rescue`,\n  `power_flow.auto_slack` and `power_flow.dc.fallback`\n  ([Power-Flow Configuration](SPARLECTRADOCS/powerflow_configuration/));\n- MATPOWER import conventions: auto-profile mode (`off`, `recommend`,\n  `apply`) plus transformer ratio, phase shift, bus shunt, PV voltage source\n  and comparison reference;\n- **Network model** (Case page, every format): the system frequency, 50 or\n  60 Hz (`model.nominal_frequency_hz`). The field is editable only for an\n  SCF or PGM case (or the base case of a time series) without `f_nom` and\n  with a line `c1` in farad. A file that states `f_nom` greys it at that\n  value, because the file wins over the key. A case without capacitance in\n  farad greys it as \"not used\": MATPOWER, DTF, CGMES and PowSyBl give line\n  charging as susceptance, and an SCF file in `pu` or with `c1 = 0` has\n  none (System frequency). For a greyed field the\n  save stores no value and removes one stored before;\n- logfile output mode, performance timing and post-run diagnostics.\n\nOnly keys in `GUI_EDITABLE_CONFIG_KEYS` are submitted, and each run writes\n`effective_config.yaml`. A **?** next to a control opens its help page:\nthe hint, the matching section of this documentation as shipped with the\nrunning version, and a link to the published site (`webui.docs_base_url`\npoints it at a local build or a pinned version). **Back** keeps the\nentered values. A field that does not apply to the selected solver or\nstep control is grayed in place, `disabled` and not submitted.", truncated = false),
  "webui_reference/#webui-import-case-files" => (title = "Import case files", markdown = "**Import case files** opens the native file picker and accepts several\nfiles at once: MATPOWER `.m`/`.M`, DTF `.dat`/`.DAT`, CGMES `.zip`\ndeliveries, CGMES profile files (`.xml`), PowSyBl IIDM files (`.xiidm`)\nand Sparlectra Case Format `.json` files (validated before they are\nstored). Several `.xml` files (the EQ, SSH, TP and SV profiles of one\ndelivery) are packed into one `<stem>_cgmes.zip`; the set must contain the\nEQ profile. A CGMES ZIP may hold nested ZIPs.\n\nImporting is copy-only: no run, no parsing of `.m` code; files land in\nthe case directory the form shows. Limits: 100 MiB per file, 250 MiB per\nrequest. An existing file is never overwritten (`already exists`, the\nother files still import); names outside the case directory are refused.\nEnter in **Case file** resolves a typed value the same way: a bare case\nname via `ensure_casefile`, `cgmes:<alias>` as below, or a full\nlocal path. Re-importing a saved set brings the `.config.yaml` sidecar (a\ncase-scope file, `scope: case`) along with the `.scf.json` and its\nmeasurement sets when all are selected together.", truncated = false),
  "webui_reference/#webui-output-modes" => (title = "Output modes", markdown = "- **Logfile output mode**: `classic` writes the result report plus a\n  compact timing and status summary (`solver_time`, `representative_time`,\n  iterations, final mismatch, outcome); `full` adds **Full run details**\n  with the effective typed configuration, artifact choices and status\n  diagnostics. MATPOWER `.m` runs also print the import-option and\n  auto-profile tables; DTF `.DAT` runs never do.\n- **Performance timing** (`off`, `compact`, `full`) writes\n  `performance.log` with the phases of one request (from request parsing to artifact\n  writing, solver and total time; `full` adds internal profile entries). A\n  run from the Web UI solves once; repeated timing is the benchmark mode\n  of `run_matpower_case` in a script\n  ([Performance Profiling](SPARLECTRADOCS/performance_profiling/#perf-benchmark)).\n- **Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP)** writes the case as\n  one re-importable delivery into the run's artifacts, for every case format\n  and also on non-converged runs; see [CGMES Export](SPARLECTRADOCS/cgmes_export/).\n- **Write bus/branch CSV files** (API default off, because large networks\n  produce large files) writes `bus_voltages_complex.csv` and\n  `branch_flows.csv` from the `ACPFlowReport` rows; columns on\n  [Local PowerFlow Service](SPARLECTRADOCS/powerflow_service/).\n- **CSV format** is the machine-scope key `output.csv_format` (**Save\n  settings** writes it to the configuration file, a per-case save leaves it\n  out) and applies to every CSV of every run type; `auto` (the default)\n  follows the regional settings of the machine. Values and delimiters:\n  [Configuration](SPARLECTRADOCS/configuration/). Excel may still auto-convert\n  identifiers like `1E5`; use **Data > From Text/CSV** with text types when\n  that matters.", truncated = false),
  "webui_reference/#webui_update" => (title = "Updates", markdown = "**Check for updates** in the **Info** panel asks GitHub for the latest\nrelease of `Welthulk/Sparlectra.jl` (the page `releases/latest`, which\nredirects to the tag of the latest release; not the REST API, whose\nanonymous limit of 60 requests per hour is shared by every machine behind\none network address) and compares it with the running version. The page\nsays up to date, names the newer release with a link to its release notes, or names\nwhy the check failed (no network, timeout, HTTP error, an address without\na release tag). The request has a timeout of 10 s and carries no data\nabout the installation. An update started here hands the tag to the\ninstall script, which does not ask GitHub again.\n\n`start_webui.jl` started from a terminal runs the same check before the\nserver starts (timeout 5 s) and, for a newer release on an installed copy,\nasks `Install <version> now? [y/N]`; only `y` or `yes` installs, through\nthe updater described below, and the new version starts when it is done.\nAny other answer, no answer within 60 s, a git checkout or another copy\n(one line on how to update), no network or a start without a terminal\nstarts the Web UI as before; `--no-update-check` or\n`SPARLECTRA_UPDATE_CHECK=0` skips the check.\n\nWhat happens with a newer release depends on how the copy was installed:\n\n- **Installed copy**: a folder named `Sparlectra` without `.git`, with\n  `start_webui.jl` and `tools/install_webui.sh` (`.bat` on Windows), the\n  layout the one-line install creates. **Install update**, after a\n  confirm, writes an updater and a copy of the install script to\n  `logs/update/` next to the operation log, starts the updater detached\n  and stops the Web UI. The updater waits until the Web UI process has\n  ended, runs the install script unattended (`SPARLECTRA_UPDATE=1`; a\n  sysimage is rebuilt when the copy has one, the desktop launcher is\n  written again when it exists) and starts the new version through\n  `start_webui.sh` or `start_webui.bat`. The previous copy stays as\n  `Sparlectra.old`; the log is `logs/update/update.log`. On Linux and\n  macOS the update and the new Web UI run without a terminal and write to\n  that log. On Windows the update opens a console window of its own and\n  waits until the console of the old Web UI is closed, because Windows\n  does not move a folder that a program still uses.\n- **Git checkout** (`.git` present): nothing is changed; the page shows\n  `git fetch --tags` and `git checkout` of the release tag.\n- **Anything else** (standalone app, registry installation, a renamed\n  download): the page shows the one-line install.\n\nThe install action is refused while a run or a sysimage build is active,\nand for a Web UI started from a REPL, whose process does not end with the\nWeb UI. It takes a POST from the update page only: the form carries a\nvalue that is new for every Web UI process, so another page in the browser\ncannot start it.", truncated = false),
)

# The Web UI user help (docs/src/webui.md) and the ids of its labelled headings.
const WEBUI_HELP_MANUAL = "# Web UI\n\nThe Web UI is a local browser interface for Sparlectra: choose a case,\nstart a calculation, read the result. It runs on your own machine, is\nreachable from that machine only and has no login. Every control, route\nand output mode: [Web UI Reference](/help/reference).\n\n## Start\n\nInstall and start in one line; Julia is installed if it is missing:\n\n```sh\ncurl -fsSL https://raw.githubusercontent.com/Welthulk/Sparlectra.jl/main/tools/install_webui.sh | sh\n```\n\n```powershell\niwr -useb https://raw.githubusercontent.com/Welthulk/Sparlectra.jl/main/tools/install_webui.bat -OutFile install_webui.bat; .\\install_webui.bat\n```\n\nFrom an installed copy or a checkout:\n\n```sh\njulia --project=. start_webui.jl\n```\n\n`start_webui.sh` and `start_webui.bat` do the same. The browser opens\n`http://127.0.0.1:8080/powerflow`. The first start prepares the\nenvironment once and offers to build a system image for fast later starts\n([Sysimage](SPARLECTRADOCS/sysimage/)). Installer questions, REPL start and\ndirectories: [reference](/help/reference#installation-and-start).\n\n## Case formats at a glance\n\n| Format | How the case gets in | Download | Good to know |\n|---|---|---|---|\n| MATPOWER (`.m`) | **Import case files**, or a name typed into **Case file** | Yes: a standard name such as `case14.m` is fetched once from the MATPOWER project | The first download needs an internet connection |\n| CGMES | **Import case files**: the delivery ZIP, or the profile files (EQ, SSH, TP, SV) selected together | Yes: `cgmes:<alias>` fetches the ENTSO-E test configurations once (about 22 MB); aliases under [CGMES test configurations](/help/reference#webui_cgmes_test_configurations) | Every uploaded delivery is checked for completeness |\n| PowSyBl IIDM (`.xiidm`) | **Import case files** | No | Unpack a compressed file first; see [PowSyBl IIDM files](/help/reference#webui_powsybl) |\n| Sparlectra Case Format, power-grid-model (`.json`) | **Import case files**, or **Export as SCF case file** from any selected case | No | Scenario files and the scenario editor need this format |\n| DTF (`.DAT`) | **Import case files** | No | Experimental, for diagnostics and validation |\n| Shipped demo cases | Already in the selector | Not needed | Work offline |\n\nNothing is downloaded without a name you typed. A selected or uploaded\nfile is used as it is.\n\n## Loading a case\n\nThe **Case** page holds the case selector, the import, the exports and\nthe import options of the selected format. **Case file** picks a case of\nthe case directory or a shipped demo case\n([Shipped Demo Cases](SPARLECTRADOCS/demo_cases/)); a typed name downloads, a typed\npath loads a local file. **Import case files** copies files into the\ncase directory and never overwrites one. **Case input format** stays on\n**Auto** unless the extension is ambiguous. **Save case as** keeps\nvariants of one network side by side. Details:\n[Case selector](/help/reference#webui-case-selector),\n[Import case files](/help/reference#webui-import-case-files),\n[Save case as](/help/reference#save-case-as).\n\n## Running\n\nThe **Runs** page starts the calculations for the selected case; every\nstart opens a status page that follows the run and can abort it. The\noptions of a run are on the **Settings** page.\n\n### Power flow\n\n**Start PowerFlow run** solves the network with Newton-Raphson, APSLF or\nthe linear DC model. Start values come from the case unless **Flat\nstart** is set; reactive limits follow **Q-limit handling**\n([Power-Flow Configuration](SPARLECTRADOCS/powerflow_configuration/)).\n\n### Diagnose\n\n**Diagnose** evaluates the mismatch at the operating point the case\nbrings along, without a corrective step, bus by bus. Run it first when a\ncase does not converge ([Diagnose](/help/reference#diagnose)).\n\n### N-1\n\nThe outage kind (branches or generators) selects the generated outage\nlist; a Sparlectra Case Format case can carry its own scenarios. The\nresult ranks the cases by severity, failures first\n([N-1 Contingency Analysis](SPARLECTRADOCS/contingency/)).\n\n### State estimation\n\nThe state-estimation section selects a measurement set or generates one\nfrom a solved power flow, checks the observability, estimates the state\nand reports suspicious measurements; the result page offers a power flow\nfrom the estimate ([State Estimation](SPARLECTRADOCS/state_estimation/)).\n\n### Short circuit\n\n**Short circuit** computes the balanced three-phase currents of every\nbus, maximum and minimum case, without a power-flow solve. The button is\noffered when the case carries source data; a run is `succeeded` only when\nevery source carries its data\n([Short-Circuit Analysis](SPARLECTRADOCS/short_circuit/)).\n\n### QSTS\n\n**QSTS** runs an SCF time series step by step, `sequential` (taps and\nbanks carried from step to step) or `snapshots`; the button is offered\nwhen the case is a series. The controllers come from\n`<series>.control.yaml` next to the series. The result page shows the\nswitching, the steps with violations and a time series chart\n([QSTS](/help/reference#webui_qsts)).\n\n## Results\n\nEvery finished run has a result page with status, iterations, final\nmismatch and its artifacts (CSV as a table, Markdown rendered,\n**Download all artifacts as ZIP**). **Run history** lists the runs and\ncompares two runs of one case. The **Operation Log** records what the\nWeb UI did; attach it to an error report. See [Results and artifacts](/help/reference#results-and-artifacts)\nand [Output modes](/help/reference#webui-output-modes).\n\n## Settings\n\nThe **Settings** page holds the options that do not belong to a single\nrun: solver, start, output. **Save settings** writes for the selected\ncase or into the configuration file; with a case selected, every page\nshows the values a run of that case will use (case settings before the\nconfiguration file before the defaults). The **Configuration Editor**\nedits the file as text and checks it before saving. See\n[Form options](/help/reference#webui-form-options) and\n[Configuration](/help/reference#webui-configuration).\n\n**Help** in the header opens this page inside the Web UI, **Search the\nhelp** searches this page, the reference and the help of the controls,\nand the **?** next to a control opens its help.\n\n## Limits\n\nOne user, the own machine, no login, no public-server mode, no topology\nview, no plotting apart from the QSTS chart. Technical limits: [reference](/help/reference#limits).\n"
const WEBUI_HELP_MANUAL_ANCHORS = Dict{String,String}(
  "Case formats at a glance" => "webui-case-formats",
)

# The Web UI reference (docs/src/webui_reference.md) and the ids of its labelled headings.
const WEBUI_HELP_REFERENCE = "# Web UI Reference\n\nOperation and details of the [Web UI](/help): installation,\ndirectories, every form option, the run kinds, artifacts, history and\nconfiguration.\n\nThe Web UI is presentation, form parsing and route handling on top of the\n[PowerFlow service](SPARLECTRADOCS/powerflow_service/); every calculation runs through\n`start_powerflow_run` and `run_sparlectra_api`. It binds to loopback\n(`127.0.0.1`, `localhost`, `::1`) and has no authentication; a wider\nbinding would expose the run directory and the configuration editor.\n\n## Installation and start\n\n### One-line install\n\nInstalls Julia if missing (via juliaup), downloads the latest tagged release\ninto `Sparlectra/` in the current directory and starts the Web UI:\n\n```sh\ncurl -fsSL https://raw.githubusercontent.com/Welthulk/Sparlectra.jl/main/tools/install_webui.sh | sh\n```\n\n```powershell\niwr -useb https://raw.githubusercontent.com/Welthulk/Sparlectra.jl/main/tools/install_webui.bat -OutFile install_webui.bat; .\\install_webui.bat\n```\n\nThe scripts (`tools/install_webui.sh`, `tools/install_webui.bat`) ask\nthree questions:\n\n- **Update** when an existing copy is older than the latest release; the old\n  copy is kept as `Sparlectra.old`.\n- **Sysimage**: built only with `SPARLECTRA_BUILD_SYSIMAGE=1`, otherwise\n  left to the Web UI start ([Sysimage](SPARLECTRADOCS/sysimage/)).\n- **Desktop shortcut**: Windows `Sparlectra Web UI.lnk`; Linux an\n  application-menu entry plus a `.desktop` file on the desktop (GNOME needs\n  a one-time right-click \"Allow Launching\"); macOS a desktop symlink.\n\nUnattended installs answer with `SPARLECTRA_UPDATE=1/0`,\n`SPARLECTRA_BUILD_SYSIMAGE=1/0` and `SPARLECTRA_CREATE_SHORTCUT=1/0`.\n`SPARLECTRA_INSTALL_DIR` names the folder for `Sparlectra/` instead of the\ncurrent one, `SPARLECTRA_START_WEBUI=0` ends the script without starting\nthe Web UI; the update from the Web UI uses both ([Updates](/help/reference#webui_update)).\n\n### Start script\n\nFrom a checkout or an installed copy:\n\n```sh\njulia --project=. start_webui.jl\n```\n\n`start_webui.sh` / `start_webui.bat` run the same script and point at the\ninstall script when Julia is missing; a Windows desktop shortcut is\nright-click `start_webui.bat`, *Send to > Desktop (create shortcut)*. The\nscript resolves, instantiates and compiles a missing dependency or\nmanifest once, for the library and for `app/` (`--env-only` does only\nthat), then looks for a usable sysimage and offers to build one\n([Sysimage](SPARLECTRADOCS/sysimage/)). The start scripts set `JULIA_NUM_THREADS=auto`\nunless it is set; a case with several islands then solves its large\nislands in parallel ([Parallel Execution](SPARLECTRADOCS/parallel_execution/)).\n\n### From the Julia REPL\n\n```julia\nusing Pkg\nPkg.activate(\"path/to/Sparlectra/app\")\nPkg.instantiate()   # first time only\nusing SparlectraApp\n\nserver = start_sparlectra_webui(open_browser = true)\nwait(server.task)\n```\n\nA REPL session runs without the sysimage ([Sysimage](SPARLECTRADOCS/sysimage/)). `start_sparlectra_webui` returns a\n`SparlectraWebUIServer` handle and serves as soon as the socket is bound.\n`open_browser = true` opens an app-style window (Microsoft Edge, Google\nChrome, Chromium or Brave) with the size and position of\n`webui.window_*` ([Configuration](SPARLECTRADOCS/configuration/)); without one of\nthem the URL `http://127.0.0.1:8080/powerflow` is logged. If the port is occupied, stop\nthe old Julia process or pass another `port`.\n\n### Directories and files\n\nResults go to `%LOCALAPPDATA%\\Sparlectra\\WebUI\\runs` (Windows),\n`\$XDG_STATE_HOME/sparlectra/webui/runs`, default\n`~/.local/state/sparlectra/webui/runs` (Linux) or\n`~/Library/Application Support/Sparlectra/WebUI/runs` (macOS). The\noperation log is in the sibling `logs`, the browser profile of the app\nwindow in `browser`, downloaded and generated cases in\nthe sibling `data/mpower`, shared with `ensure_casefile` and the test\nsuite (`SPARLECTRA_LARGE_CASES_DIR` overrides it for all three). The\nbundled `warmup_case*.jl` workloads land there too, hidden from the\nselector.\n\nThe first start copies the package configuration template to the\nuser-writable `config/configuration.yaml` (`output_root = \"...\"` and\n`config_file = \"...\"` override the defaults; an explicit file is never\noverwritten). Next to it: `configuration.template.yaml` (a key still at\nan old template default follows a new default at start, reported, the\nprevious file kept as `configuration.yaml.template-follow.bak`),\n`configuration.yaml.user-keys.txt` (keys the Web UI itself saved, never\nfollowed) and `configuration.yaml.settings-save.bak` (backup of a\nsettings save). The browser cannot change the output root. The **Info**\npanel names the serving build (`sysimage, built ...` or `native session`),\nlinks to the Sysimage page and checks for updates.\n\n### Updates\n\n**Check for updates** in the **Info** panel asks GitHub for the latest\nrelease of `Welthulk/Sparlectra.jl` (the page `releases/latest`, which\nredirects to the tag of the latest release; not the REST API, whose\nanonymous limit of 60 requests per hour is shared by every machine behind\none network address) and compares it with the running version. The page\nsays up to date, names the newer release with a link to its release notes, or names\nwhy the check failed (no network, timeout, HTTP error, an address without\na release tag). The request has a timeout of 10 s and carries no data\nabout the installation. An update started here hands the tag to the\ninstall script, which does not ask GitHub again.\n\n`start_webui.jl` started from a terminal runs the same check before the\nserver starts (timeout 5 s) and, for a newer release on an installed copy,\nasks `Install <version> now? [y/N]`; only `y` or `yes` installs, through\nthe updater described below, and the new version starts when it is done.\nAny other answer, no answer within 60 s, a git checkout or another copy\n(one line on how to update), no network or a start without a terminal\nstarts the Web UI as before; `--no-update-check` or\n`SPARLECTRA_UPDATE_CHECK=0` skips the check.\n\nWhat happens with a newer release depends on how the copy was installed:\n\n- **Installed copy**: a folder named `Sparlectra` without `.git`, with\n  `start_webui.jl` and `tools/install_webui.sh` (`.bat` on Windows), the\n  layout the one-line install creates. **Install update**, after a\n  confirm, writes an updater and a copy of the install script to\n  `logs/update/` next to the operation log, starts the updater detached\n  and stops the Web UI. The updater waits until the Web UI process has\n  ended, runs the install script unattended (`SPARLECTRA_UPDATE=1`; a\n  sysimage is rebuilt when the copy has one, the desktop launcher is\n  written again when it exists) and starts the new version through\n  `start_webui.sh` or `start_webui.bat`. The previous copy stays as\n  `Sparlectra.old`; the log is `logs/update/update.log`. On Linux and\n  macOS the update and the new Web UI run without a terminal and write to\n  that log. On Windows the update opens a console window of its own and\n  waits until the console of the old Web UI is closed, because Windows\n  does not move a folder that a program still uses.\n- **Git checkout** (`.git` present): nothing is changed; the page shows\n  `git fetch --tags` and `git checkout` of the release tag.\n- **Anything else** (standalone app, registry installation, a renamed\n  download): the page shows the one-line install.\n\nThe install action is refused while a run or a sysimage build is active,\nand for a Web UI started from a REPL, whose process does not end with the\nWeb UI. It takes a POST from the update page only: the form carries a\nvalue that is new for every Web UI process, so another page in the browser\ncannot start it.\n\n## Importing cases\n\nThe **Case** page carries the case chooser, upload, export and the\nper-format import options.\n\n### Case selector\n\n**Case file** is one combobox. Its list holds the MATPOWER `.m` files and\nrunnable DTF `.DAT` candidates of the case directory, the shipped demo\ncases ([Shipped Demo Cases](SPARLECTRADOCS/demo_cases/)), the three CGMES deliveries\nunder `data/cgmes_demo` as `<case>_cgmes.zip`, and the PowSyBl IIDM files\n(`.xiidm`). Generated `.jl` cache files and `warmup_` files\nare hidden. FOR002-like `.DAT` files go into the optional **FOR002\nreference** field, for legacy reference comparison only.\n\nA shipped case is copied into the case directory on first use, together\nwith its configuration file and measurement sets. When a new release ships\na changed version, the Web UI replaces the copy at start, but only if the\ncopy still has the content of an earlier committed version of that file\n(`data/shipped_hashes.toml` lists them; CRLF and LF line ends count as\nequal, so a copy from a Windows checkout is recognized). The new file is\nwritten under a temporary name first, so an interrupted start never\nleaves a half-written file. The old copy stays next to the new one as\n`<name>.replaced-<date>`, the operation log gets an entry\n`shipped_case_file_replaced` with the file name and the old and new\nSHA-256, and the start output names the file. A copy you changed is never\nreplaced.\n\nA typed value overrides the list: a bare name such as `case14.m` or\n`case9241pegase.m` is downloaded into the case directory, an existing\n`.m`/`.jl` path is used as given; path-like missing inputs and URLs are\nrejected. A generated `.jl` cache file resolves back to its `.m` source\nand is rejected without one.\n\n**Case input format** defaults to **Auto** (MATPOWER, CGMES folders and\nZIPs, PowSyBl IIDM, and native DTF where the reader takes the file as a\nnetwork). **CGMES (ENTSO-E, folder or ZIP)** is preselected for a `.zip`\nor a directory, **PowSyBl (IIDM file)** for `.xiidm` (it shows the\nPowSyBl import options, [PowSyBl IIDM files](/help/reference#webui_powsybl));\n**Sparlectra Case Format (.scf.json)** and **power-grid-model JSON\n(input.json)** name the same reader, which Auto already uses for every\n`.json`. The native DTF path is experimental; **Selected DTF outage\nlabels/indices** takes one label or index at a time.\n\nThe format-bound options of the Basic set render directly, the rest and\nthe DTF diagnostics fold into **Advanced**. A page renders only the options\nthe format of the selected case reads (MATPOWER import options for MATPOWER\ncases, the CGMES, PowSyBl and DTF options for their formats, the QSTS mode\nfor an SCF time series); a section that\nleaves options out says how many, and their saved values stay in the case\nconfiguration file. The system frequency is shown for every format and is\ngreyed where the format does not read it. Deleting a case removes its\ncompanion files (configuration, weights, measurement CSVs). A collapsible\nMATPOWER acknowledgement names the citations the cases ask for.\n\n### Import case files\n\n**Import case files** opens the native file picker and accepts several\nfiles at once: MATPOWER `.m`/`.M`, DTF `.dat`/`.DAT`, CGMES `.zip`\ndeliveries, CGMES profile files (`.xml`), PowSyBl IIDM files (`.xiidm`)\nand Sparlectra Case Format `.json` files (validated before they are\nstored). Several `.xml` files (the EQ, SSH, TP and SV profiles of one\ndelivery) are packed into one `<stem>_cgmes.zip`; the set must contain the\nEQ profile. A CGMES ZIP may hold nested ZIPs.\n\nImporting is copy-only: no run, no parsing of `.m` code; files land in\nthe case directory the form shows. Limits: 100 MiB per file, 250 MiB per\nrequest. An existing file is never overwritten (`already exists`, the\nother files still import); names outside the case directory are refused.\nEnter in **Case file** resolves a typed value the same way: a bare case\nname via `ensure_casefile`, `cgmes:<alias>` as below, or a full\nlocal path. Re-importing a saved set brings the `.config.yaml` sidecar (a\ncase-scope file, `scope: case`) along with the `.scf.json` and its\nmeasurement sets when all are selected together.\n\n### Export and download\n\nThe export row writes the open case as `.scf.json` or plain PGM\n`.pgm.json`, replacing a format suffix the case already carries\n(`case14.scf.json` as PGM gives `case14.pgm.json`); both appear in the\nselector as runnable cases. **Download selected case** serves what the\nselector shows, after an export also the file just written: only plain\nfiles inside the case directory, compared by real path (the state\ndirectory can sit behind a symlink); anything outside, and a CGMES\ndelivery directory, is refused.\n\n### Save case as\n\n**Save case as**, next to the export buttons, saves the current case under\na new name: one network with several variants, one file per variant. It\nwrites into the case directory:\n\n- `<name>.scf.json` via `exportSCF`, with `meta.case_name = <name>`\n  and `meta.source_reference` naming the source; a MATPOWER or DTF source\n  is saved as SCF, the original file is never touched;\n- `<name>.config.yaml`: the source case's saved settings merged with\n  unsaved changes on the page;\n- `<name>.measurements.csv` for each measurement set bound to the source\n  case, with its `# case:` header rewritten; a second bound set becomes\n  `<name>_<original stem>.measurements.csv`.\n\nAn existing `<name>.scf.json` is refused unless \"overwrite\" is ticked.\n\"Start from the solved state\" solves the case once with the effective\nsettings and writes the solved voltages as the copy's\n`sparlectra.start_state`. Installation-scope settings (`output.*`,\n`benchmark.*`, `runtime.*`) are never written into the case configuration\nfile. File layout: [Sparlectra Case Format](SPARLECTRADOCS/scf/).\n\n### PowSyBl IIDM files\n\nIIDM is the network format of the PowSyBl framework; its XML form has the\nextension `.xiidm` and is read as it is.\n\n| You have | Do this |\n|---|---|\n| no file yet | pick one of the four shipped networks: `ieee14.xiidm`, `four_substations.xiidm`, `micro_grid_be.xiidm`, `ieee14_sc.xiidm` |\n| a `.xiidm` file | **Import case files**; it appears in the selector |\n| a compressed file (`.xiidm.bz2`, `.gz`) | unpack it first, then import the `.xiidm` |\n\nEvery run kind and export works on a PowSyBl case; scenarios need an SCF\nexport of it. With a PowSyBl case selected, **Input format** shows five\noptions; the defaults fit most files.\n\n| Option | Default | Change it when |\n|---|---|---|\n| System base MVA | 100 | you compare per-unit values with a tool on another base |\n| HVDC converters | fixed injections | never for now: the paired controller is not available for PowSyBl files |\n| Remote voltage regulation | hold the target at the unit's own bus | a generator regulates another bus that shall be held exactly: choose the outer-loop control |\n| One slack per synchronous component | on | only the first component shall be solved |\n| Slack generator ids | empty | another unit than the chosen one shall carry the reference; several ids are separated by semicolons |\n\nEvery power-flow run on a PowSyBl case writes `powsybl_import.log`:\nelements read and built per type, skipped elements with their reason, the\nreference generator of each synchronous component, and whether the solve\nstarted from the file's voltages or flat. Short circuit uses the connected\ngenerators with the reactance of the extension `generatorShortCircuit`; a\ngenerator without it enters with a default reactance and the rows it feeds\nare marked; without any extension or rated power the **Short circuit**\nbutton is not offered (of the shipped networks only `ieee14_sc.xiidm`\ncarries complete data, `micro_grid_be.xiidm` runs on defaults). Not read: compressed files, time\nseries, the regulation data of tap changers. There is no IIDM export.\nConventions: [PowSyBl Import](SPARLECTRADOCS/powsybl_import/).\n\n### CGMES test configurations\n\n`cgmes:<alias>` typed into **Case file** downloads the official ENTSO-E\ntest-configuration package once (about 22 MB) into the CGMES cache\n(`data/CGMES`, overridable with `SPARLECTRA_CGMES_CACHE`) and packs the\nrequested configuration with its boundary set into `cgmes_<alias>.zip` in\nthe case directory. Aliases: `microgrid_be`, `microgrid_nl`,\n`microgrid_assembled`, `smallgrid`, `smallgrid_nb`, `fullgrid`,\n`fullgrid_nb`, `realgrid`. The alias alone works as well, in any case,\nwith or without a `cgmes` prefix and `.zip` (`smallgrid`,\n`CGMES SmallGrid.zip`); a name that matches nothing gets a message with\nthe accepted forms. Repeated requests reuse the ZIP. If the download\nfails, the message names the path where the package can be placed by hand.\n\n### Import analysis on upload\n\nEvery uploaded CGMES delivery is checked at once. A complete one reports\n\"ready to compute\"; an incomplete one gets the import analysis: the\nmessage names the missing declared `md:Model.DependentOn` dependencies by\nmodel id (typically the boundary set), and the report is written next to\nthe case as `<case>.import_analysis.txt`. The same analysis is appended to\nthe run's CGMES import report `cgmes_import_report.md` whenever its CGMES\nimport aborts. Scripted: the run mode\n`import_analysis_mode` of `start_powerflow_run` (a non-importable delivery\nends as a failed run with reason `import_analysis_not_importable`) or\n`analyzeCGMES`. **Require boundary set** (CGMES section, saved per case)\nsubmits `cgmes_import.require_boundary`; unchecked, an incomplete delivery\nimports where possible, but buses without a resolvable `BaseVoltage` still\nabort. **Equivalent injections as source** (CGMES section, saved per case,\ndefault off) submits `cgmes_import.equivalent_injection_as_source`: an\n`EquivalentInjection` on the SV angle reference or a boundary node becomes\na voltage-regulating source at the SV voltage of its node, the one on the\nSV angle reference is the slack\n([CGMES import configuration](SPARLECTRADOCS/cgmes_import/#cgmes-import-config)).\n\n### Long actions on a case\n\nGenerating a measurement set or adding noise runs inside the request and\ncan take a while on a large case (with **critical measurements** the\ngenerator re-reads the criticality after every removed row). Meanwhile the\ncase is busy: a second generator action or a run is refused with a\nmessage, and a queued or running run blocks the generator the same way.\n\n## Starting a run\n\nRun-independent options live on the **Settings** page and reach a run\nthrough the configuration precedence (`resolve_config`): saving with\ntarget \"this case\" writes case-scope keys into the case's configuration\nfile, target \"configuration file\" merges into the general YAML (backup\n`.settings-save.bak`). A save writes only the values that differ from what\nthe case inherits. The save that creates the case configuration file\n(also the measurement generator on a case without one) takes over the\ncase-scope keys in which the general YAML differs from the packaged\ndefaults, because from then on the case no longer reads them\nthere; the message gives their number. The **Runs** page keeps the run parameters (modes,\nN-1 kind, N-1 list, screening, DTF outage fields), the\nstate-estimation section (submitted with `se_mode`) and the N-1 editors\nas tabs. The measurement generator's\nfields are the generator options of\n[State Estimation Measurements](SPARLECTRADOCS/state_estimation_measurements/#se-generator-v2).\n\n### Form options\n\nThe settings and run forms offer:\n\n- case name or local path, configuration template file, the read-only\n  output root (set only through `start_sparlectra_webui(; output_root)`),\n  tolerance (decimals or scientific notation such as `1e-8`; the spinner\n  steps the exponent and keeps the mantissa), maximum iterations,\n  autodamping with its minimum factor;\n- **Q-limit handling**: the `power_flow.qlimits.enabled` checkbox and the\n  enforcement-mode selector, which also offers **off**; **PV/PQ\n  switching** holds the hysteresis, the final check bound\n  (`final_q_accept_pu`, `auto` or a value in pu), the classic pass limit\n  (`classic_max_passes`), the first switching iteration (`start_iter`),\n  the switch cap per bus (`guard.max_switches`), freezing after repeated\n  switching and the guard switch (`guard.enabled`); **Advanced** holds the\n  rest of `power_flow.qlimits`\n  ([Q-limit options and guard](SPARLECTRADOCS/powerflow_configuration/#pf-qlimits)).\n  Per-unit values take scientific notation, bus lists comma-separated case\n  bus numbers. Controls a mode does not read are grayed: everything while\n  the handling is off, the start iteration and the guard rules in the\n  classic modes, the range rules without the guard;\n- **Solver**: one radio group `power_flow_solver` with `rectangular` (AC\n  Newton-Raphson), `apslf` (AnalyticLoadFlow) and `dc` (linear screening\n  model)\n  ([solver selection](SPARLECTRADOCS/powerflow_configuration/#pf-solver-selection),\n  [DC power flow](SPARLECTRADOCS/powerflow_configuration/));\n- wrong-branch detection mode, start angle and voltage modes;\n- **Advanced start values**: the current-iteration pre-solve fields\n  (`power_flow.start_current_iteration.*`,\n  [guarded pre-solve](SPARLECTRADOCS/powerflow_configuration/#pf-current-iteration-start));\n- **Merit-function line search**: `power_flow.merit.enabled`,\n  `power_flow.merit.armijo_c1`, `power_flow.merit.fallback_max_mismatch`\n  ([options](SPARLECTRADOCS/powerflow_configuration/#pf-merit)),\n  requires `power_flow.autodamp = true`;\n- **Non-convergence handling** (Advanced): `power_flow.rescue`,\n  `power_flow.auto_slack` and `power_flow.dc.fallback`\n  ([Power-Flow Configuration](SPARLECTRADOCS/powerflow_configuration/));\n- MATPOWER import conventions: auto-profile mode (`off`, `recommend`,\n  `apply`) plus transformer ratio, phase shift, bus shunt, PV voltage source\n  and comparison reference;\n- **Network model** (Case page, every format): the system frequency, 50 or\n  60 Hz (`model.nominal_frequency_hz`). The field is editable only for an\n  SCF or PGM case (or the base case of a time series) without `f_nom` and\n  with a line `c1` in farad. A file that states `f_nom` greys it at that\n  value, because the file wins over the key. A case without capacitance in\n  farad greys it as \"not used\": MATPOWER, DTF, CGMES and PowSyBl give line\n  charging as susceptance, and an SCF file in `pu` or with `c1 = 0` has\n  none (System frequency). For a greyed field the\n  save stores no value and removes one stored before;\n- logfile output mode, performance timing and post-run diagnostics.\n\nOnly keys in `GUI_EDITABLE_CONFIG_KEYS` are submitted, and each run writes\n`effective_config.yaml`. A **?** next to a control opens its help page:\nthe hint, the matching section of this documentation as shipped with the\nrunning version, and a link to the published site (`webui.docs_base_url`\npoints it at a local build or a pinned version). **Back** keeps the\nentered values. A field that does not apply to the selected solver or\nstep control is grayed in place, `disabled` and not submitted.\n\n### AC, APSLF and DC\n\n`AC (Newton-Raphson, rectangular)` reveals the start-value block (**Flat\nstart**, **Use APSLF start values** with its order field, **Use DC start\nvalues**) and every AC-only option. By default\n(`power_flow.start_mode.angle_mode = dc`) Newton-Raphson seeds its start\nangles from an internal DC pre-solve (**Start angle mode**), unrelated to\nthe standalone `DC` solver.\n\n`APSLF (AnalyticLoadFlow)` reveals the **APSLF solver options** (highest\ncoefficient (order), convergence radius, NR polish). **Use APSLF start\nvalues** in the Newton-Raphson block seeds the rectangular solver instead\nand is mutually exclusive with the APSLF solver (the configuration rejects\nboth). An unchecked checkbox (APSLF, Q-limit, current-iteration) submits\n`false` rather than omitting the key.\n\n`DC` replaces Newton-Raphson with the linear model\n([DC power flow](SPARLECTRADOCS/powerflow_configuration/))\nand grays every AC-only option. The result page marks a DC run with a **DC\nsolution** badge next to **Solver** and the history column shows `dc`, so\nthe implicit `Vm = 1.0 pu` and lossless flows are never taken for an AC\nresult; `iterations` is `1`.\n\nThe **Solver** column names the method that ran: the power-flow solver for\na plain power flow, one started from an estimate and every contingency\ncase; `wls` for a state estimation; `iec60909` for a short circuit; empty\nfor an import analysis.\n\n#### Flat start\n\n`power_flow.flatstart` starts the Newton-Raphson solve at 1.0 pu and the\nslack angle on every bus and ignores the imported start voltages (MATPOWER\n`VM`/`VA`, CGMES `SvVoltage`, SCF `start_state`). Off, the imported values\nseed the solve; a delivery is built around its own operating point, so\nthat is the default.\n\nWhile the flat start is on, the run switches the start projection, the DC\nstart values, the two start modes and the ratio profile off, also when the configuration file\nhas `start_projection: true`. The page greys those controls (saved values\nstay) and the run log names the override. The current-iteration pre-solve\nand the APSLF start follow their own checkboxes.\n\nThree-winding star points start at the ratio of their stiffest winding on\nevery flat start; all other buses stay flat.\n\n**Flat start turned behind phase shifters**\n(`power_flow.start_mode.rotate_behind_pst`, off by default) starts a bus\nthat the slack reaches only across phase-shifting transformers at the slack\nangle plus the shifts of a path with the fewest shifters, on a flat start\nand on a stored start without angles. A bus that a path without shifter\nreaches keeps the slack angle. See\n[Start strategies by case](SPARLECTRADOCS/start_strategies/).\n\n**Ratio profile as a start candidate** (`power_flow.start_mode.ratio_profile`,\non by default) is a candidate of the start projection: the flat profile\nwith each voltage level scaled by the transformer ratios on its path from\nthe slack, applied to every PQ bus (not only to three-winding star points)\nwhen its mismatch is at least 10 percent lower. The flat start switches it\noff for the whole run, rescue and auto stages included. Without the flat\nstart it acts only where a projection starts from the flat profile: in the\nrescue ladder's alternate start, unless **Start angle mode** is `dc` (the\nDC angles keep precedence), and in the auto mode. The page greys the\ncheckbox in every other case: flat start on, or neither **Auto mode** nor\n**Rescue** with a start angle mode other than `dc`. A greyed checkbox is\nnot posted and the saved value stays.\n\nA CGMES run honours the flat start under **CGMES start values** = `auto`;\nan explicit `sv` on the Case page still starts from the delivery state\n([Power flow configuration](SPARLECTRADOCS/powerflow_configuration/#pf-solver-core)).\n\n### Case-specific settings\n\nA successful result page offers **Save settings for this case**: the form\noptions of that run plus traceability metadata go into a sanitized YAML\nprofile below the output root. A non-converged run shows **Save these\nsettings anyway**; nothing is saved automatically. Reopening the case\nprefills the form from the profile with a notice; a manual edit wins for\nthe submitted run.\n\nWith a case selected, every page shows the values a run of that case will\nuse: case settings over the configuration file over the defaults; without\na case, the configuration file. **Show the configuration file's values**\n(`?config_view=1`) switches the Settings page to the file alone, **Show\nthe case settings** back. A save to the configuration file says how many\nof the saved keys the selected case overrides. Between configuration file\nand saved profile the last edit wins: a newer YAML file takes precedence\nfor the keys it sets on the next page load, and the notice says so.\n\nWith a Sparlectra Case Format file selected, the form is seeded from the\ncase file (the page says which settings came from it); a saved profile\nfor the case wins over the file, and an edited control wins over both.\n\n### Scenarios and N-1\n\nThe action row of the run form carries the N-1 controls: outage kind\n(branch/generator), **N-1 list** (the outage kind, or all branches,\nbranches or generators), **screening mode** (configured / off / flag /\nonly) with a **margin** field (empty means the configured\n`contingency.screening.margin_pct`), and links to the weights editor and,\nfor SCF cases, the scenario editor. **Contingency (N-1)** runs the list;\nwith `contingency.events.enabled` an SCF case adds its correlated events\nto a branch list (Correlated events). A case\nwhose file carries a scenarios block also shows **Scenarios**: it runs the\nscenarios of the block (and the event classes the block asks for) and\nnothing else. The run summary names the screened count and the case-list\nsource; the result page tabulates the cases\nranked by severity with failures first, capped at 100 rows (the linked\nCSV keeps the complete list in input order). A screened row shows its\none-step estimate, a flagged row the estimate next to the full-run\nvalues, a failed case its error text. Screening, weights and the warm\nstart themselves: [N-1 Contingency Analysis](SPARLECTRADOCS/contingency/).\n\n**Weights.** \"edit N-1 weights\" next to the outage-kind selector opens a\nper-case editor. Weights live next to the case as\n`<case-stem>.contingency-weights.csv` (the two-column format of\n`readContingencyWeightsCSV`), hidden from the case list and deleted with\nthe case. The editor seeds a table with the case's element names and\noffers a raw-CSV text area and a file upload; a malformed CSV is rejected\nwith the line number, rows left at `1.0` are omitted on save. A run picks\nthe weights up whenever the file exists; names that match no element are\nreported in `run.log`. The file applies to case-list runs (the outage-kind\nselector and the N-1 lists); a **Scenarios** run or an external scenario\nJSON uses the per-scenario `weight`.\n\nScenarios need an SCF case; for other formats the form says so next to the\nexport action. The **scenario editor** lists the open case's scenarios\n(edit, duplicate, delete, new) and edits one as op rows (status, set or\nscale on a component chosen by class).\nValidation is server side; errors name the scenario and op index, and a\ntap patch on a regulated transformer is rejected with the controller\nnamed. **Save into case file** writes the scenarios block through the SCF\nwriter.\n\n### Diagnose\n\n**Diagnose** next to **Start PowerFlow run** evaluates the mismatch at the\ncase's stored operating point (MATPOWER `VM`/`VA`, the `SvVoltage` state\nof a CGMES delivery) without a corrective Newton step. Every start-value\nmachine is forced off (`flatstart = false`, `start_projection = false`,\n`dc_seed_unconditional = false`, `start_current_iteration.enabled = false`,\n`apslf_start.enabled = false`, plus `max_iter = 1` and\n`qlimits.enabled = false`), so the residual reflects the imported model;\nthe forced settings outrank the form and the case configuration file. The\nrun uses the normal pipeline and adds `self_check.log` (forced settings,\nstart residual, for CGMES the count of buses without a usable\n`SvVoltage`, started at the voltage of a neighbour with one or at\n`1.0 pu / 0°`, and the tap changers whose `SvPowerFlow` fits another step\nclearly better than their `SvTapStep`), `self_check_residuals.csv`\n(per-bus P/Q residuals) and `diagnose_self_check_config.yaml`. Programmatically:\n`run_fixed_reference_self_check`.\n\nOne step practically never converges; the residual is the measurement, so\nhistory and result page label the run **diagnosed** on a neutral badge\n(raw status in the tooltip). A diagnose run that could not run at all\nkeeps the failure vocabulary.\n\n### Short circuit\n\n**Short circuit** next to Diagnose evaluates the balanced three-phase\ncurrents (IEC 60909-0, `runShortCircuit!`) for every bus, maximum\nand minimum case in one run, without a power-flow solve. The button is\nenabled only when the case carries short-circuit source data; otherwise\nit is disabled with a tooltip. The run writes `short_circuit_max.csv` and\n`short_circuit_min.csv` (per-bus `Ik''`, `Sk''`, `κ`, `i_p`, safety flag\nand reasons, `lower_bound`) and a `run.log` with the data coverage\nreport. The result page and the view of each table start with the head\nline of the table: run status, flagged rows, rows whose `Ik''max` is a\nlower bound (a skipped source); both counts also show as warning badges. A MATPOWER or DTF case carries no source data and fails\nwith `short_circuit_requires_cgmes`. Which data counts as a source in each\nformat: Short-Circuit Analysis.\n\n### State estimation\n\nThe state-estimation section of the Runs page\n(`/powerflow#state-estimation`; `/stateestimation` redirects there) uses\nthe shared case selection, selects a measurement set and runs\nobservability (traffic light, structural-island note), the WLS solve and\nthe diagnostics of [State Estimation](SPARLECTRADOCS/state_estimation/). The\ngenerator, \"add noise\" and every set Sparlectra ships write the\n[measurement table](SPARLECTRADOCS/state_estimation_measurement_table/) (version line\n`# sparlectra-measurement-table v1` plus header); the run needs\n`state_estimation.measurement_table` on (the default). Uploaded `.csv`\nfiles are offered when they are a measurement table or carry the version\ncomment of the measurement CSV v1; a CSV v1 set shows a notice at the\nfile: its reader was removed in 0.50.0, a run and \"add noise\" on it stop\nwith an error naming `convertMeasurementsV1`, and the SCF export and\n**Save case as** leave it out and say so. The text and value editors work\non both.\n\nThe set list offers only the sets of the selected case: a set whose\n`# case:` line names the case (or the case an SCF file was exported from);\nfor a CGMES case a set without that line whose `# cgmes_model:` line names\nthe EQ model of the case (see\nBinding a table to its case); and a set without\neither line whose file name starts with the case name\nwithout its extension, followed by a dot (`sp_case14.measurements.csv`\nfor `sp_case14.scf.json`). An uploaded set that matches none of these is\noffered for no case. **assign to <case>** next to the upload binds the\nuploaded file to the selected case: its `# case:` line is set to that\ncase, whatever the file says, a measurement file of the same name is\nreplaced, and the file is armed for the next run. Rows the case cannot\nresolve are counted in the import report of the run. Each entry names its\ncase. Without a matching\nset the section says so and points to the generator. The run still\nrefuses a set bound to another case. A case file with its own\nmeasurements offers those first; otherwise `<case>.measurements.csv` is\npreselected (cases with a bound set are starred).\n\nEvery generation and every \"add noise\" writes a new time-stamped file\n(`<case>.measurements.<yyyymmdd-HHMMSS>.csv`, `<case>.noisy.<stamp>.csv`)\nand arms it for the next run; later the newest set bound to the case is\narmed. **Delete measurement file** removes the armed set (never a case\nfile). The set tab offers download, re-upload and an inline editor (the\nfile keeps its format: a table its version line and header, a CSV v1 its\nversion comment) and renders the\n`sparlectra-taps v1` tap table of a generated file. **Add noise to this\nset** perturbs each value with the sigma its own row declares. **Reset\nsaved settings** under the generator deletes the per-case settings\nsidecar. **estimate taps** (`state_estimation.tap_estimation.enabled` of\nthe case, on by default)\nreleases every declared tap changer, ratio and phase, of every in-service\ntransformer (a transformer that only carries a ratio has none); off, every changer keeps its transferred step. A changer whose\nstep the measurements do not determine is not estimated and keeps its\ntransferred step (status `not_estimated` with the reason), see\nObservability per changer. Which\ntransformers are estimated is set per transformer on the Case page\n(section **State estimation: tap estimation per transformer**): one\n\"estimate\" checkbox per transformer with a tap changer, machine\ntransformers unchecked by default. **Save case options** writes the\nunchecked ones into `state_estimation.tap_estimation.exclude` of the case\nconfiguration and sets `include_machine_transformers` when a machine\ntransformer is checked; every SE run of the case reads both. A machine\ntransformer already named in `exclude` stays there on a save. An excluded\ntransformer keeps its transferred step (reason `excluded`). A machine\ntransformer is calculated after the estimation (status `calculated`) when\nQ is measured on every bus of its machine node; otherwise it keeps its\nstep (reason `q_not_measured_in_group`), see\nTap estimation per transformer. The result page\nshows one row per\ntap changer (transferred step, estimated step and its raw value before\nrounding, Delta U, ratio, angle,\ndeviation, status with its reason) and the J change of the fixation.\n**tap fallback** (`state_estimation.tap_estimation.fallback`, on) runs once\nmore without tap estimation when the run with it does not converge or its\nfixed steps fit worse than the staged pre-solve (`worse_fit`); the result\npage then shows one line above the tap table, see\nTap estimation switch and fallback.\n**tap impedance per step** (`auto`, `off`) is\n`state_estimation.tap_estimation.impedance_correction` of the case, see\nTransformer tap estimation.\n**zero-injection sigma** is `state_estimation.zero_injection_sigma_mva` of\nthe case, the sigma of one zero-injection row under `zero_injection = on`,\nsee Zero injections and coupler balances. The\nform warns when `k_suppress < k_eliminate`, because suppressed rows then\nrarely reach the elimination.\n\nArtifacts (`measurements.csv`, `measurements_verdict.csv`,\n`se_diagnostics.md`, `se_view.md`, `se_state.csv`, `shunt_estimates.csv`,\n`se_tap_estimates.csv`, `se_deltas.csv`, `se_link_flows.csv`, and under\n`zero_injection = constraint` `se_zero_injection_multipliers.csv`) land in\nthe run history with kind `se`. `measurements.csv` is the estimated set as a measurement table and\ncan be picked as the measurement set of a new run; the verdict per row\n(residual, normalized residual, eliminated, reason) is in\n`measurements_verdict.csv`, one click away on the result page (see\nrun artifacts). The result page offers\n**Run power flow from this estimate** and the topology hypothesis test\nbehind a button (`topology_hypotheses.md`), which reads the run's\n`measurements.csv` without the rows `measurements_verdict.csv` marks as\neliminated, so it starts from the `J` of the run. A run from before 0.50.0 still shows; its\n`measurements.csv` is a CSV v1, and the test asks for a new run. The\nsummary shows `J`, `E[J] = dof` and the Wilson-Hilferty band verdict for\nthe state after the elimination, with the suspicious and eliminated\ncounts of the verdict file; suppressed rows stay in `J` and surface\nas `J_active`.\n\n### QSTS\n\nThe case chooser offers every SCF time series (a zip with `series.json`,\n`base.scf.json` and `delta.csv`), recognized by its content; the shipped\nexample is `sp_case14_day.qsts.zip` (under `data/qsts`). **QSTS** next to **Contingency (N-1)**\nruns the series step by step (`runQsts`); it is enabled only when\nthe selected case is a series. **QSTS mode**, shown for a series only,\nchooses `sequential` (taps\nand banks carried from step to step) or `snapshots` (every step on its\nown). The run sets `qsts.mode` for itself; the configuration keeps its\nvalue. **Start PowerFlow run** on a series solves its base case.\n\nThe controllers come from the companion file `<series>.control.yaml` next\nto the series (for the example `sp_case14_day.control.yaml`, staged with\nit). Its `control` section replaces the one of the run configuration, for\nQSTS runs only; `run.log` names the file. Without it the controllers of\nthe case file run alone. A `snapshots` run uses controllers only with\n`qsts.snapshot_controls = true`; otherwise the result page and `run.log`\nsay that they are not used. The status page counts the finished steps, and\n**Abort run** stops the run before the next step.\n\nThe result page shows solved and failed steps, switches and hunting\npatterns per controller (sequential only), the steps with a voltage\noutside `qsts.vm_min_pu` to `qsts.vm_max_pu` or a loading above\n`qsts.loading_max_pct`, the loss energy and the notes of the run. The time\nseries chart opens with the position of the first controller and the\nvoltage of its regulated bus with the band dashed; **Element** and\n**Quantity** choose another series, each point carries its value as a\ntooltip. The CSV files open in the CSV view. Artifacts: the files of\n`writeQstsResults`, `qsts_view.json` (the element view behind the\nchart), one SVG per element with its main quantity under `qsts_plots/`\n(bus `vm_pu`, branch `loading_pct`, controller `position`) and\n`qsts_overview.html`. Mode, files and metrics: [QSTS](SPARLECTRADOCS/qsts/).\n\n## Running jobs\n\nA submission starts a background worker and redirects to the status page\n(elapsed time, case paths, start time, a manual refresh link). Queued, running and aborting pages\nrefresh every two seconds (`autorefresh=1` requests are not logged as\nuser actions); terminal pages stop. The start page and the run history\nshow a banner with **Open status** and **Abort** while a job is queued or\nrunning; such a run cannot be deleted.\n\nAn N-1 or scenario run shows how far its batch is: **Outages done** reads\n`N-1: 37 / 186 outages` (a scenario set reads **Scenarios done**,\n`Scenarios: 3 / 10 scenarios`). The counter appears once the first outage\nhas finished, after the import and the base-case solve; screened outages\ncount as done. For large cases, the result page, `run.log`, `result.json`\nand `performance.log` show time per phase (reader, network builder,\nsolver, artifacts).\n\n### Abort\n\nA queued or running job can be aborted from its status page or from the\nbanner. Abort is cooperative: an operation that cannot be interrupted,\nsuch as a sparse factorization, finishes first; the status page shows the\ncurrent phase. An aborted run keeps its run directory and is never\nreported as success. If a run stays in `aborting` for more than 60 s, the\nstatus page offers **Hard reset Web UI**: it marks the run invalid and\nstops the server. Restart with `julia --project=. start_webui.jl`.\n\n### Feedback\n\nOne-off messages (validation errors, import summary) open as a dismissible\npopup; recent errors stay listed on the **Last errors** page.\n\n## Results and artifacts\n\nEvery finished run gets a result page: run ID, schema version, status,\nconvergence and solution flags, iterations, final mismatch, reason and\nmessage, input paths, output directory and a **Solver** entry. **System\nfrequency** names the frequency with its source, or `not used` when no\ncapacitance in farad entered the model (System frequency). A CSV artifact opens as a table\n(delimiter taken from the header line), a Markdown report rendered;\n**Raw text** shows the file as written. The CGMES import report of a run\nis the Markdown artifact `cgmes_import_report.md`; a delivery with a DY profile gets a section **Dynamic data\n(DY profile)** there, with the counts of `cgmes_import.read_dynamics` or\none line saying that the profile was not read\n(Dynamic data). **Read dynamic data (DY profile)**\nin the CGMES section of the Case page switches the key per case (default\noff); unchecking it again removes the key from the case file, so the\ndefault applies.\n\nAbove a CSV table, **Significant digits** (default 5) rounds every decimal\ncell, and **Power columns** (W, kW or MW) shows power columns in whole\nunits of that resolution, the unit then in the column header; 1.98e-16 MW\nshows as 0 at any resolution. A power column is one whose header name holds\nthe token `mw`, `mvar` or `mva` (case-insensitive, tokens split at every\ncharacter that is not a letter or digit: `p_mw`, `q_mvar`, `s_mva`,\n`P [MW]`); other columns, such as `vm_pu`, get the significant digits only.\nInteger cells (bus numbers, counts) stay as written unless they sit in a\npower column with a resolution; a cell that is no number of the file's own\nformat always does. Values below 1e-4 show with an exponent. The decimal separator\nfollows the file: a semicolon file reads and shows with the decimal comma.\nThe choice is part of the address (`?digits=4&power=kW`) and carries over\nthrough the links to the other CSV files of the run. It changes the display\nonly; **Raw text** and the download keep the file as written.\n\nA column header is a link that sorts the rows by that column: a column with\nnumbers largest first, a text column A to Z (ignoring case); a second click\nturns the order (`?sort=p_mw`, `&order=asc`). All rows the view reads (a\nlarge file is cut to the preview size, the page says so) are sorted before\nthe table is cut to its first rows, so the largest value is on top; cells\nwithout a number, or empty text cells, go to the end. The sort column stays\nwith **Apply** but not on the links to the other CSV files of the run. The\nheader of a column whose cells are mostly numbers is right-aligned like its\nnumbers, and the header row stays visible while the rows scroll.\n\nColumns are hidden with the button in the header or the **Columns** list;\nthey are part of the address (`&hide=2,5`, column numbers of the file) and\nstay hidden through sorting and **Apply**. Rows are hidden with their\ncheckbox and **Hide selected rows** or with the filter field (rows that\ncontain a text in any cell); both stay in the browser tab until\n**Show all rows**.\n\nOther text artifacts (JSON, YAML,\nlogs) open as escaped text with a download. An HTML report (the QSTS\noverview) opens as a page of its own with its charts; the server sends it\nwith a policy that allows no script. SVG charts show in the browser, other\nfiles download. **Download all artifacts as ZIP** packs\nthe exposed artifacts into `sparlectra_run_<run_id>_artifacts.zip`.\n\n### Output modes\n\n- **Logfile output mode**: `classic` writes the result report plus a\n  compact timing and status summary (`solver_time`, `representative_time`,\n  iterations, final mismatch, outcome); `full` adds **Full run details**\n  with the effective typed configuration, artifact choices and status\n  diagnostics. MATPOWER `.m` runs also print the import-option and\n  auto-profile tables; DTF `.DAT` runs never do.\n- **Performance timing** (`off`, `compact`, `full`) writes\n  `performance.log` with the phases of one request (from request parsing to artifact\n  writing, solver and total time; `full` adds internal profile entries). A\n  run from the Web UI solves once; repeated timing is the benchmark mode\n  of `run_matpower_case` in a script\n  ([Performance Profiling](SPARLECTRADOCS/performance_profiling/#perf-benchmark)).\n- **Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP)** writes the case as\n  one re-importable delivery into the run's artifacts, for every case format\n  and also on non-converged runs; see [CGMES Export](SPARLECTRADOCS/cgmes_export/).\n- **Write bus/branch CSV files** (API default off, because large networks\n  produce large files) writes `bus_voltages_complex.csv` and\n  `branch_flows.csv` from the `ACPFlowReport` rows; columns on\n  [Local PowerFlow Service](SPARLECTRADOCS/powerflow_service/).\n- **CSV format** is the machine-scope key `output.csv_format` (**Save\n  settings** writes it to the configuration file, a per-case save leaves it\n  out) and applies to every CSV of every run type; `auto` (the default)\n  follows the regional settings of the machine. Values and delimiters:\n  [Configuration](SPARLECTRADOCS/configuration/). Excel may still auto-convert\n  identifiers like `1E5`; use **Data > From Text/CSV** with text types when\n  that matters.\n\n### Diagnostic artifacts\n\n`diagnose.log` is written by **Diagnose** or with `run_diagnostics = true`,\nnever by a normal run. On a non-converged run it names the worst-mismatch\nbus and equation, classifies the mismatch trend (monotonic, oscillatory,\nstagnant, diverging to non-finite) and the autodamp health, scans the\nbranches at the worst bus for zero impedance, off-nominal taps, large\nphase shifts or an outlying reactance, and closes with recommendations. A\ndiagnostic exception stays in the file without changing a successful\nresult. A run that attempts the current-iteration pre-solve may add\n`current_iteration_start.log`: whether the candidate was attempted,\naccepted, or rejected (by a guard, or with the original start restored).\n\n### Comparing two runs\n\nTick **Compare** on two history rows (two runs of the same case under\ndifferent settings) and press **Compare selected runs**; the page shows\nside by side: case file, status, converged flag, iterations and final\nmismatch with a link to each result page; the configuration keys the runs\ndisagree on (from `effective_config.yaml`); the buses each run clamped\n(from `q_limit_events.csv`) and which only one of them clamped; total\nlosses (from `branch_flows.csv`) with the difference; the largest voltage\ndeviation and the ten buses that differ most, when both runs wrote\n`bus_voltages_complex.csv`. Everything comes from what the runs wrote, so\nearlier sessions compare as well; exactly two runs are required. The box\nappears only on finished power-flow runs (plain, diagnose, or started\nfrom an estimate) whose result is still on disk; the page says so when\nthe runs share no bus.\n\n## Run history and operation log\n\n`start_sparlectra_webui` refreshes `powerflow_runs_index.json` under the\noutput root before serving, so runs of an earlier process appear at once;\n**Refresh registry** reloads by hand, and missing, corrupt or unsafe entries\nare skipped without hiding the valid ones. History is newest first: local\ndate and time, run ID, status text and badge, solver summary fields and\nactions. **Case file** and **Config file** show the file name,\nthe full path in the tooltip. **Delete** removes one run, **Delete all\nruns** every registered run under the configured root; both delete only\nvalidated run directories.\n\nThe **Operation Log** page shows and downloads `logs/webui_operations.jsonl`,\na JSON Lines support log independent of the run directories: page opens,\nsubmissions, validation failures, run lifecycle changes, artifact views\nand downloads, aborts, history refreshes, deletions and shutdown requests\n(not static CSS or image requests), each with route, method, status, run,\ncase, artifact, message and timing fields where available,\n`sparlectra_version` and a UTC timestamp, never file contents or\nconfiguration bodies. Logging cannot fail a request; per-iteration\ntimings belong to `performance.log`.\n\nEvery start drops entries older than `webui.operation_log_retention_days`\n(default 10, `0` keeps only the current session);\n`SPARLECTRA_WEBUI_OPERATION_LOG_RETENTION_DAYS` overrides the key for\nheadless runs. On append, a log above 1 MiB is compacted and more than\n5,000 valid entries are cut to the newest 1,000. The page states its size\nand offers **Clear operation log**, which empties the file and writes one\nentry recording that. A large log is a matter of entry count, not age; a\nretention of two or three days is the lasting remedy.\n\n## Configuration\n\n**Check configuration** and **Refresh configuration** bring a local file up\nto a template that gained options. Check is a dry run against\n`src/config/configuration.yaml.example` (missing keys, deprecated\naliases, duplicate YAML keys, a preview of the refreshed YAML), nothing\nwritten. Refresh keeps existing values, adds missing keys with template\ndefaults and may normalize deprecated aliases; it never runs at startup,\nwrites a timestamped backup first, refuses on duplicate keys, and offers\nuploaded or pasted YAML as a download instead of rewriting it.\n\nThe **Configuration Editor** opens the active YAML in a textarea, validates\nit with the same parser and duplicate-key checks, writes only after\nvalidation with a timestamped backup, and warns when a case configuration\nfile still overrides the global YAML. After a save the server reloads the\nfile. The search box above the text finds plain text (**Next** / **Previous**,\nEnter / Shift+Enter) or jumps to a dotted key such as\n`power_flow.qlimits.guard.enabled`.\n\nForm values override the YAML configuration; the order is described in\n[Configuration](SPARLECTRADOCS/configuration/). Each run writes `effective_config.yaml`.\n**Ignore Web UI settings and use configuration defaults** runs with the YAML\nvalues only. `model.auto_profile: apply` may still adjust MATPOWER import\nconventions after form and API values are assembled;\n`effective_config.yaml` records that.\n\n**Help** in the header opens the help ([Web UI](/help)) inside the Web\nUI, as shipped with the running version; **Project Docs** opens the\npublished documentation (`webui.docs_base_url`). The help pages behind\nthe **?** icons carry a section of the help or of this reference in full,\nor the lead paragraph of a library section with the link to it.\n\n### Search the help\n\nThe search field stands at the top of the help, of this reference and in\nthe header of every page and looks through the help, the reference and\nthe help pages of the controls. Every word entered must occur (a part of\na word is enough, case does not matter); hits appear while you type, hits\nin a heading first, each with a marked line of text. `/` focuses the\nfield, Enter opens the first hit, Esc closes the list. Without a hit the\npage links to the published documentation. The index ships with the\napplication; with scripts switched off the field is a plain form.\n\n## Shutdown\n\nThe server stops with **Stop Web UI**, `close(server)` or `Ctrl+C`. With\n`auto_shutdown_on_browser_close = true` it also stops when the browser has\nbeen gone for `browser_heartbeat_timeout_seconds` (best effort).\n\n**Stop Web UI** also saves the size and position of the app window into\nthe configuration file (`webui.window_width`, `webui.window_height`,\n`webui.window_x`, `webui.window_y`), and the next start opens the window\nthere. A minimized window is not saved; `Ctrl+C` and `close(server)` save\nnothing. The app window runs in its own browser profile (`browser` next to\n`runs`), because a browser that is already open ignores size and position\nof a new window. Under Linux with Wayland it runs through X11 (XWayland):\nWayland windows can neither read nor set their screen position. The operation log records the save as `webui_window_geometry`.\n\n## Limits\n\nLoopback only, no authentication, no public-server mode, no database.\nNo push channel: a running job reports its phase through the page\nrefresh. No topology view, no plotting apart from the QSTS chart.\n"
const WEBUI_HELP_REFERENCE_ANCHORS = Dict{String,String}(
  "Updates" => "webui_update",
  "Case selector" => "webui-case-selector",
  "Import case files" => "webui-import-case-files",
  "PowSyBl IIDM files" => "webui_powsybl",
  "CGMES test configurations" => "webui_cgmes_test_configurations",
  "Form options" => "webui-form-options",
  "Flat start" => "webui-flat-start",
  "QSTS" => "webui_qsts",
  "Output modes" => "webui-output-modes",
  "Configuration" => "webui-configuration",
  "Search the help" => "webui_help_search",
)

# The search index of the help: one entry per section of the two help
# pages and per help topic of a control, the text without markup.
const WEBUI_HELP_SEARCH_INDEX = NamedTuple{(:title, :url, :kind, :text),Tuple{String,String,String,String}}[
  (title = "Start", url = "/help#start", kind = "help", text = "Install and start in one line; Julia is installed if it is missing: From an installed copy or a checkout: start_webui.sh and start_webui.bat do the same. The browser opens http://127.0.0.1:8080/powerflow . The first start prepares the environment once and offers to build a system image for fast later starts (Sysimage). Installer questions, REPL start and directories: reference."),
  (title = "Case formats at a glance", url = "/help#webui-case-formats", kind = "help", text = "Format How the case gets in Download Good to know MATPOWER ( .m ) Import case files , or a name typed into Case file Yes: a standard name such as case14.m is fetched once from the MATPOWER project The first download needs an internet connection CGMES Import case files : the delivery ZIP, or the profile files (EQ, SSH, TP, SV) selected together Yes: cgmes:<alias fetches the ENTSO-E test configurations once (about 22 MB); aliases under CGMES test configurations Every uploaded delivery is checked for completeness PowSyBl IIDM ( .xiidm ) Import case files No Unpack a compressed file first; see PowSyBl IIDM files Sparlectra Case Format, power-grid-model ( .json ) Import case files , or Export as SCF case file from any selected case No Scenario files and the scenario editor need this format DTF ( .DAT ) Import case files No Experimental, for diagnostics and validation Shipped demo cases Already in the selector Not needed Work offline Nothing is downloaded without a name you typed. A selected or uploaded file is used as it is."),
  (title = "Loading a case", url = "/help#loading-a-case", kind = "help", text = "The Case page holds the case selector, the import, the exports and the import options of the selected format. Case file picks a case of the case directory or a shipped demo case (Shipped Demo Cases); a typed name downloads, a typed path loads a local file. Import case files copies files into the case directory and never overwrites one. Case input format stays on Auto unless the extension is ambiguous. Save case as keeps variants of one network side by side. Details: Case selector, Import case files, Save case as."),
  (title = "Running", url = "/help#running", kind = "help", text = "The Runs page starts the calculations for the selected case; every start opens a status page that follows the run and can abort it. The options of a run are on the Settings page."),
  (title = "Power flow", url = "/help#power-flow", kind = "help", text = "Start PowerFlow run solves the network with Newton-Raphson, APSLF or the linear DC model. Start values come from the case unless Flat start is set; reactive limits follow Q-limit handling (Power-Flow Configuration)."),
  (title = "Diagnose", url = "/help#diagnose", kind = "help", text = "Diagnose evaluates the mismatch at the operating point the case brings along, without a corrective step, bus by bus. Run it first when a case does not converge (Diagnose)."),
  (title = "N-1", url = "/help#n-1", kind = "help", text = "The outage kind (branches or generators) selects the generated outage list; a Sparlectra Case Format case can carry its own scenarios. The result ranks the cases by severity, failures first (N-1 Contingency Analysis)."),
  (title = "State estimation", url = "/help#state-estimation", kind = "help", text = "The state-estimation section selects a measurement set or generates one from a solved power flow, checks the observability, estimates the state and reports suspicious measurements; the result page offers a power flow from the estimate (State Estimation)."),
  (title = "Short circuit", url = "/help#short-circuit", kind = "help", text = "Short circuit computes the balanced three-phase currents of every bus, maximum and minimum case, without a power-flow solve. The button is offered when the case carries source data; a run is succeeded only when every source carries its data (Short-Circuit Analysis)."),
  (title = "QSTS", url = "/help#qsts", kind = "help", text = "QSTS runs an SCF time series step by step, sequential (taps and banks carried from step to step) or snapshots ; the button is offered when the case is a series. The controllers come from <series .control.yaml next to the series. The result page shows the switching, the steps with violations and a time series chart (QSTS)."),
  (title = "Results", url = "/help#results", kind = "help", text = "Every finished run has a result page with status, iterations, final mismatch and its artifacts (CSV as a table, Markdown rendered, Download all artifacts as ZIP ). Run history lists the runs and compares two runs of one case. The Operation Log records what the Web UI did; attach it to an error report. See Results and artifacts and Output modes."),
  (title = "Settings", url = "/help#settings", kind = "help", text = "The Settings page holds the options that do not belong to a single run: solver, start, output. Save settings writes for the selected case or into the configuration file; with a case selected, every page shows the values a run of that case will use (case settings before the configuration file before the defaults). The Configuration Editor edits the file as text and checks it before saving. See Form options and Configuration. Help in the header opens this page inside the Web UI, Search the help searches this page, the reference and the help of the controls, and the ? next to a control opens its help."),
  (title = "Limits", url = "/help#limits", kind = "help", text = "One user, the own machine, no login, no public-server mode, no topology view, no plotting apart from the QSTS chart. Technical limits: reference."),
  (title = "Installation and start", url = "/help/reference#installation-and-start", kind = "reference", text = ""),
  (title = "One-line install", url = "/help/reference#one-line-install", kind = "reference", text = "Installs Julia if missing (via juliaup), downloads the latest tagged release into Sparlectra/ in the current directory and starts the Web UI: The scripts ( tools/install_webui.sh , tools/install_webui.bat ) ask three questions: - Update when an existing copy is older than the latest release; the old copy is kept as Sparlectra.old . - Sysimage : built only with SPARLECTRA_BUILD_SYSIMAGE=1 , otherwise left to the Web UI start (Sysimage). - Desktop shortcut : Windows Sparlectra Web UI.lnk ; Linux an application-menu entry plus a .desktop file on the desktop (GNOME needs a one-time right-click \"Allow Launching\"); macOS a desktop symlink. Unattended installs answer with SPARLECTRA_UPDATE=1/0 , SPARLECTRA_BUILD_SYSIMAGE=1/0 and SPARLECTRA_CREATE_SHORTCUT=1/0 . SPARLECTRA_INSTALL_DIR names the folder for Sparlectra/ instead of the current one, SPARLECTRA_START_WEBUI=0 ends the script without starting the Web UI; the update from the Web UI uses both (Updates)."),
  (title = "Start script", url = "/help/reference#start-script", kind = "reference", text = "From a checkout or an installed copy: start_webui.sh / start_webui.bat run the same script and point at the install script when Julia is missing; a Windows desktop shortcut is right-click start_webui.bat , Send to Desktop (create shortcut) . The script resolves, instantiates and compiles a missing dependency or manifest once, for the library and for app/ ( --env-only does only that), then looks for a usable sysimage and offers to build one (Sysimage). The start scripts set JULIA_NUM_THREADS=auto unless it is set; a case with several islands then solves its large islands in parallel (Parallel Execution)."),
  (title = "From the Julia REPL", url = "/help/reference#from-the-julia-repl", kind = "reference", text = "A REPL session runs without the sysimage (Sysimage). start_sparlectra_webui returns a SparlectraWebUIServer handle and serves as soon as the socket is bound. open_browser = true opens an app-style window (Microsoft Edge, Google Chrome, Chromium or Brave) with the size and position of webui.window_ (Configuration); without one of them the URL http://127.0.0.1:8080/powerflow is logged. If the port is occupied, stop the old Julia process or pass another port ."),
  (title = "Directories and files", url = "/help/reference#directories-and-files", kind = "reference", text = "Results go to %LOCALAPPDATA%\\Sparlectra\\WebUI\\runs (Windows), \$XDG_STATE_HOME/sparlectra/webui/runs , default ~/.local/state/sparlectra/webui/runs (Linux) or ~/Library/Application Support/Sparlectra/WebUI/runs (macOS). The operation log is in the sibling logs , the browser profile of the app window in browser , downloaded and generated cases in the sibling data/mpower , shared with ensure_casefile and the test suite ( SPARLECTRA_LARGE_CASES_DIR overrides it for all three). The bundled warmup_case .jl workloads land there too, hidden from the selector. The first start copies the package configuration template to the user-writable config/configuration.yaml ( output_root = \"...\" and config_file = \"...\" override the defaults; an explicit file is never overwritten). Next to it: configuration.template.yaml (a key still at an old template default follows a new default at start, reported, the previous file kept as configuration.yaml.template-follow.bak ), configuration.yaml.user-keys.txt (keys the Web UI itself saved, never followed) and configuration.yaml.settings-save.bak (backup of a settings save). The browser cannot change the output root. The Info panel names the serving build ( sysimage, built ... or native session ), links to the Sysimage page and checks for updates."),
  (title = "Updates", url = "/help/reference#webui_update", kind = "reference", text = "Check for updates in the Info panel asks GitHub for the latest release of Welthulk/Sparlectra.jl (the page releases/latest , which redirects to the tag of the latest release; not the REST API, whose anonymous limit of 60 requests per hour is shared by every machine behind one network address) and compares it with the running version. The page says up to date, names the newer release with a link to its release notes, or names why the check failed (no network, timeout, HTTP error, an address without a release tag). The request has a timeout of 10 s and carries no data about the installation. An update started here hands the tag to the install script, which does not ask GitHub again. start_webui.jl started from a terminal runs the same check before the server starts (timeout 5 s) and, for a newer release on an installed copy, asks Install <version now? [y/N] ; only y or yes installs, through the updater described below, and the new version starts when it is done. Any other answer, no answer within 60 s, a git checkout or another copy (one line on how to update), no network or a start without a terminal starts the Web UI as before; --no-update-check or SPARLECTRA_UPDATE_CHECK=0 skips the check. What happens with a newer release depends on how the copy was installed: - Installed copy : a folder named Sparlectra without .git , with start_webui.jl and tools/install_webui.sh ( .bat on Windows), the layout the one-line install creates. Install update , after a confirm, writes an updater and a copy of the install script to logs/update/ next to the operation log, starts the updater detached and stops the Web UI. The updater waits until the Web UI process has ended, runs the install script unattended ( SPARLECTRA_UPDATE=1 ; a sysimage is rebuilt when the copy has one, the desktop launcher is written again when it exists) and starts the new version through start_webui.sh or start_webui.bat . The previous copy stays as Sparlectra.old ; the log is logs/update/update.log . On Linux and macOS the update and the new Web UI run without a terminal and write to that log. On Windows the update opens a console window of its own and waits until the console of the old Web UI is closed, because Windows does not move a folder that a program still uses. - Git checkout ( .git present): nothing is changed; the page shows git fetch --tags and git checkout of the release tag. - Anything else (standalone app, registry installation, a renamed download): the page shows the one-line install. The install action is refused while a run or a sysimage build is active, and for a Web UI started from a REPL, whose process does not end with the Web UI. It takes a POST from the update page only: the form carries a value that is new for every Web UI process, so another page in the browser cannot start it."),
  (title = "Importing cases", url = "/help/reference#importing-cases", kind = "reference", text = "The Case page carries the case chooser, upload, export and the per-format import options."),
  (title = "Case selector", url = "/help/reference#webui-case-selector", kind = "reference", text = "Case file is one combobox. Its list holds the MATPOWER .m files and runnable DTF .DAT candidates of the case directory, the shipped demo cases (Shipped Demo Cases), the three CGMES deliveries under data/cgmes_demo as <case _cgmes.zip , and the PowSyBl IIDM files ( .xiidm ). Generated .jl cache files and warmup_ files are hidden. FOR002-like .DAT files go into the optional FOR002 reference field, for legacy reference comparison only. A shipped case is copied into the case directory on first use, together with its configuration file and measurement sets. When a new release ships a changed version, the Web UI replaces the copy at start, but only if the copy still has the content of an earlier committed version of that file ( data/shipped_hashes.toml lists them; CRLF and LF line ends count as equal, so a copy from a Windows checkout is recognized). The new file is written under a temporary name first, so an interrupted start never leaves a half-written file. The old copy stays next to the new one as <name .replaced-<date , the operation log gets an entry shipped_case_file_replaced with the file name and the old and new SHA-256, and the start output names the file. A copy you changed is never replaced. A typed value overrides the list: a bare name such as case14.m or case9241pegase.m is downloaded into the case directory, an existing .m / .jl path is used as given; path-like missing inputs and URLs are rejected. A generated .jl cache file resolves back to its .m source and is rejected without one. Case input format defaults to Auto (MATPOWER, CGMES folders and ZIPs, PowSyBl IIDM, and native DTF where the reader takes the file as a network). CGMES (ENTSO-E, folder or ZIP) is preselected for a .zip or a directory, PowSyBl (IIDM file) for .xiidm (it shows the PowSyBl import options, PowSyBl IIDM files); Sparlectra Case Format (.scf.json) and power-grid-model JSON (input.json) name the same reader, which Auto already uses for every .json . The native DTF path is experimental; Selected DTF outage labels/indices takes one label or index at a time. The format-bound options of the Basic set render directly, the rest and the DTF diagnostics fold into Advanced . A page renders only the options the format of the selected case reads (MATPOWER import options for MATPOWER cases, the CGMES, PowSyBl and DTF options for their formats, the QSTS mode for an SCF time series); a section that leaves options out says how many, and their saved values stay in the case configuration file. The system frequency is shown for every format and is greyed where the format does not read it. Deleting a case removes its companion files (configuration, weights, measurement CSVs). A collapsible MATPOWER acknowledgement names the citations the cases ask for."),
  (title = "Import case files", url = "/help/reference#webui-import-case-files", kind = "reference", text = "Import case files opens the native file picker and accepts several files at once: MATPOWER .m / .M , DTF .dat / .DAT , CGMES .zip deliveries, CGMES profile files ( .xml ), PowSyBl IIDM files ( .xiidm ) and Sparlectra Case Format .json files (validated before they are stored). Several .xml files (the EQ, SSH, TP and SV profiles of one delivery) are packed into one <stem _cgmes.zip ; the set must contain the EQ profile. A CGMES ZIP may hold nested ZIPs. Importing is copy-only: no run, no parsing of .m code; files land in the case directory the form shows. Limits: 100 MiB per file, 250 MiB per request. An existing file is never overwritten ( already exists , the other files still import); names outside the case directory are refused. Enter in Case file resolves a typed value the same way: a bare case name via ensure_casefile , cgmes:<alias as below, or a full local path. Re-importing a saved set brings the .config.yaml sidecar (a case-scope file, scope: case ) along with the .scf.json and its measurement sets when all are selected together."),
  (title = "Export and download", url = "/help/reference#export-and-download", kind = "reference", text = "The export row writes the open case as .scf.json or plain PGM .pgm.json , replacing a format suffix the case already carries ( case14.scf.json as PGM gives case14.pgm.json ); both appear in the selector as runnable cases. Download selected case serves what the selector shows, after an export also the file just written: only plain files inside the case directory, compared by real path (the state directory can sit behind a symlink); anything outside, and a CGMES delivery directory, is refused."),
  (title = "Save case as", url = "/help/reference#save-case-as", kind = "reference", text = "Save case as , next to the export buttons, saves the current case under a new name: one network with several variants, one file per variant. It writes into the case directory: - <name .scf.json via exportSCF , with meta.case_name = <name and meta.source_reference naming the source; a MATPOWER or DTF source is saved as SCF, the original file is never touched; - <name .config.yaml : the source case's saved settings merged with unsaved changes on the page; - <name .measurements.csv for each measurement set bound to the source case, with its case: header rewritten; a second bound set becomes <name _<original stem .measurements.csv . An existing <name .scf.json is refused unless \"overwrite\" is ticked. \"Start from the solved state\" solves the case once with the effective settings and writes the solved voltages as the copy's sparlectra.start_state . Installation-scope settings ( output. , benchmark. , runtime. ) are never written into the case configuration file. File layout: Sparlectra Case Format."),
  (title = "PowSyBl IIDM files", url = "/help/reference#webui_powsybl", kind = "reference", text = "IIDM is the network format of the PowSyBl framework; its XML form has the extension .xiidm and is read as it is. You have Do this no file yet pick one of the four shipped networks: ieee14.xiidm , four_substations.xiidm , micro_grid_be.xiidm , ieee14_sc.xiidm a .xiidm file Import case files ; it appears in the selector a compressed file ( .xiidm.bz2 , .gz ) unpack it first, then import the .xiidm Every run kind and export works on a PowSyBl case; scenarios need an SCF export of it. With a PowSyBl case selected, Input format shows five options; the defaults fit most files. Option Default Change it when System base MVA 100 you compare per-unit values with a tool on another base HVDC converters fixed injections never for now: the paired controller is not available for PowSyBl files Remote voltage regulation hold the target at the unit's own bus a generator regulates another bus that shall be held exactly: choose the outer-loop control One slack per synchronous component on only the first component shall be solved Slack generator ids empty another unit than the chosen one shall carry the reference; several ids are separated by semicolons Every power-flow run on a PowSyBl case writes powsybl_import.log : elements read and built per type, skipped elements with their reason, the reference generator of each synchronous component, and whether the solve started from the file's voltages or flat. Short circuit uses the connected generators with the reactance of the extension generatorShortCircuit ; a generator without it enters with a default reactance and the rows it feeds are marked; without any extension or rated power the Short circuit button is not offered (of the shipped networks only ieee14_sc.xiidm carries complete data, micro_grid_be.xiidm runs on defaults). Not read: compressed files, time series, the regulation data of tap changers. There is no IIDM export. Conventions: PowSyBl Import."),
  (title = "CGMES test configurations", url = "/help/reference#webui_cgmes_test_configurations", kind = "reference", text = "cgmes:<alias typed into Case file downloads the official ENTSO-E test-configuration package once (about 22 MB) into the CGMES cache ( data/CGMES , overridable with SPARLECTRA_CGMES_CACHE ) and packs the requested configuration with its boundary set into cgmes_<alias .zip in the case directory. Aliases: microgrid_be , microgrid_nl , microgrid_assembled , smallgrid , smallgrid_nb , fullgrid , fullgrid_nb , realgrid . The alias alone works as well, in any case, with or without a cgmes prefix and .zip ( smallgrid , CGMES SmallGrid.zip ); a name that matches nothing gets a message with the accepted forms. Repeated requests reuse the ZIP. If the download fails, the message names the path where the package can be placed by hand."),
  (title = "Import analysis on upload", url = "/help/reference#import-analysis-on-upload", kind = "reference", text = "Every uploaded CGMES delivery is checked at once. A complete one reports \"ready to compute\"; an incomplete one gets the import analysis: the message names the missing declared md:Model.DependentOn dependencies by model id (typically the boundary set), and the report is written next to the case as <case .import_analysis.txt . The same analysis is appended to the run's CGMES import report cgmes_import_report.md whenever its CGMES import aborts. Scripted: the run mode import_analysis_mode of start_powerflow_run (a non-importable delivery ends as a failed run with reason import_analysis_not_importable ) or analyzeCGMES . Require boundary set (CGMES section, saved per case) submits cgmes_import.require_boundary ; unchecked, an incomplete delivery imports where possible, but buses without a resolvable BaseVoltage still abort. Equivalent injections as source (CGMES section, saved per case, default off) submits cgmes_import.equivalent_injection_as_source : an EquivalentInjection on the SV angle reference or a boundary node becomes a voltage-regulating source at the SV voltage of its node, the one on the SV angle reference is the slack (CGMES import configuration)."),
  (title = "Long actions on a case", url = "/help/reference#long-actions-on-a-case", kind = "reference", text = "Generating a measurement set or adding noise runs inside the request and can take a while on a large case (with critical measurements the generator re-reads the criticality after every removed row). Meanwhile the case is busy: a second generator action or a run is refused with a message, and a queued or running run blocks the generator the same way."),
  (title = "Starting a run", url = "/help/reference#starting-a-run", kind = "reference", text = "Run-independent options live on the Settings page and reach a run through the configuration precedence ( resolve_config ): saving with target \"this case\" writes case-scope keys into the case's configuration file, target \"configuration file\" merges into the general YAML (backup .settings-save.bak ). A save writes only the values that differ from what the case inherits. The save that creates the case configuration file (also the measurement generator on a case without one) takes over the case-scope keys in which the general YAML differs from the packaged defaults, because from then on the case no longer reads them there; the message gives their number. The Runs page keeps the run parameters (modes, N-1 kind, N-1 list, screening, DTF outage fields), the state-estimation section (submitted with se_mode ) and the N-1 editors as tabs. The measurement generator's fields are the generator options of State Estimation Measurements."),
  (title = "Form options", url = "/help/reference#webui-form-options", kind = "reference", text = "The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ), tolerance (decimals or scientific notation such as 1e-8 ; the spinner steps the exponent and keeps the mantissa), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector, which also offers off ; PV/PQ switching holds the hysteresis, the final check bound ( final_q_accept_pu , auto or a value in pu), the classic pass limit ( classic_max_passes ), the first switching iteration ( start_iter ), the switch cap per bus ( guard.max_switches ), freezing after repeated switching and the guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits (Q-limit options and guard). Per-unit values take scientific notation, bus lists comma-separated case bus numbers. Controls a mode does not read are grayed: everything while the handling is off, the start iteration and the guard rules in the classic modes, the range rules without the guard; - Solver : one radio group power_flow_solver with rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model) (solver selection, DC power flow); - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve); - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; - Non-convergence handling (Advanced): power_flow.rescue , power_flow.auto_slack and power_flow.dc.fallback (Power-Flow Configuration); - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - Network model (Case page, every format): the system frequency, 50 or 60 Hz ( model.nominal_frequency_hz ). The field is editable only for an SCF or PGM case (or the base case of a time series) without f_nom and with a line c1 in farad. A file that states f_nom greys it at that value, because the file wins over the key. A case without capacitance in farad greys it as \"not used\": MATPOWER, DTF, CGMES and PowSyBl give line charging as susceptance, and an SCF file in pu or with c1 = 0 has none (System frequency). For a greyed field the save stores no value and removes one stored before; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, and each run writes effective_config.yaml . A ? next to a control opens its help page: the hint, the matching section of this documentation as shipped with the running version, and a link to the published site ( webui.docs_base_url points it at a local build or a pinned version). Back keeps the entered values. A field that does not apply to the selected solver or step control is grayed in place, disabled and not submitted."),
  (title = "AC, APSLF and DC", url = "/help/reference#ac-apslf-and-dc", kind = "reference", text = "AC (Newton-Raphson, rectangular) reveals the start-value block ( Flat start , Use APSLF start values with its order field, Use DC start values ) and every AC-only option. By default ( power_flow.start_mode.angle_mode = dc ) Newton-Raphson seeds its start angles from an internal DC pre-solve ( Start angle mode ), unrelated to the standalone DC solver. APSLF (AnalyticLoadFlow) reveals the APSLF solver options (highest coefficient (order), convergence radius, NR polish). Use APSLF start values in the Newton-Raphson block seeds the rectangular solver instead and is mutually exclusive with the APSLF solver (the configuration rejects both). An unchecked checkbox (APSLF, Q-limit, current-iteration) submits false rather than omitting the key. DC replaces Newton-Raphson with the linear model (DC power flow) and grays every AC-only option. The result page marks a DC run with a DC solution badge next to Solver and the history column shows dc , so the implicit Vm = 1.0 pu and lossless flows are never taken for an AC result; iterations is 1 . The Solver column names the method that ran: the power-flow solver for a plain power flow, one started from an estimate and every contingency case; wls for a state estimation; iec60909 for a short circuit; empty for an import analysis."),
  (title = "Flat start", url = "/help/reference#webui-flat-start", kind = "reference", text = "power_flow.flatstart starts the Newton-Raphson solve at 1.0 pu and the slack angle on every bus and ignores the imported start voltages (MATPOWER VM / VA , CGMES SvVoltage , SCF start_state ). Off, the imported values seed the solve; a delivery is built around its own operating point, so that is the default. While the flat start is on, the run switches the start projection, the DC start values, the two start modes and the ratio profile off, also when the configuration file has start_projection: true . The page greys those controls (saved values stay) and the run log names the override. The current-iteration pre-solve and the APSLF start follow their own checkboxes. Three-winding star points start at the ratio of their stiffest winding on every flat start; all other buses stay flat. Flat start turned behind phase shifters ( power_flow.start_mode.rotate_behind_pst , off by default) starts a bus that the slack reaches only across phase-shifting transformers at the slack angle plus the shifts of a path with the fewest shifters, on a flat start and on a stored start without angles. A bus that a path without shifter reaches keeps the slack angle. See Start strategies by case. Ratio profile as a start candidate ( power_flow.start_mode.ratio_profile , on by default) is a candidate of the start projection: the flat profile with each voltage level scaled by the transformer ratios on its path from the slack, applied to every PQ bus (not only to three-winding star points) when its mismatch is at least 10 percent lower. The flat start switches it off for the whole run, rescue and auto stages included. Without the flat start it acts only where a projection starts from the flat profile: in the rescue ladder's alternate start, unless Start angle mode is dc (the DC angles keep precedence), and in the auto mode. The page greys the checkbox in every other case: flat start on, or neither Auto mode nor Rescue with a start angle mode other than dc . A greyed checkbox is not posted and the saved value stays. A CGMES run honours the flat start under CGMES start values = auto ; an explicit sv on the Case page still starts from the delivery state (Power flow configuration)."),
  (title = "Case-specific settings", url = "/help/reference#case-specific-settings", kind = "reference", text = "A successful result page offers Save settings for this case : the form options of that run plus traceability metadata go into a sanitized YAML profile below the output root. A non-converged run shows Save these settings anyway ; nothing is saved automatically. Reopening the case prefills the form from the profile with a notice; a manual edit wins for the submitted run. With a case selected, every page shows the values a run of that case will use: case settings over the configuration file over the defaults; without a case, the configuration file. Show the configuration file's values ( ?config_view=1 ) switches the Settings page to the file alone, Show the case settings back. A save to the configuration file says how many of the saved keys the selected case overrides. Between configuration file and saved profile the last edit wins: a newer YAML file takes precedence for the keys it sets on the next page load, and the notice says so. With a Sparlectra Case Format file selected, the form is seeded from the case file (the page says which settings came from it); a saved profile for the case wins over the file, and an edited control wins over both."),
  (title = "Scenarios and N-1", url = "/help/reference#scenarios-and-n-1", kind = "reference", text = "The action row of the run form carries the N-1 controls: outage kind (branch/generator), N-1 list (the outage kind, or all branches, branches or generators), screening mode (configured / off / flag / only) with a margin field (empty means the configured contingency.screening.margin_pct ), and links to the weights editor and, for SCF cases, the scenario editor. Contingency (N-1) runs the list; with contingency.events.enabled an SCF case adds its correlated events to a branch list (Correlated events). A case whose file carries a scenarios block also shows Scenarios : it runs the scenarios of the block (and the event classes the block asks for) and nothing else. The run summary names the screened count and the case-list source; the result page tabulates the cases ranked by severity with failures first, capped at 100 rows (the linked CSV keeps the complete list in input order). A screened row shows its one-step estimate, a flagged row the estimate next to the full-run values, a failed case its error text. Screening, weights and the warm start themselves: N-1 Contingency Analysis. Weights. \"edit N-1 weights\" next to the outage-kind selector opens a per-case editor. Weights live next to the case as <case-stem .contingency-weights.csv (the two-column format of readContingencyWeightsCSV ), hidden from the case list and deleted with the case. The editor seeds a table with the case's element names and offers a raw-CSV text area and a file upload; a malformed CSV is rejected with the line number, rows left at 1.0 are omitted on save. A run picks the weights up whenever the file exists; names that match no element are reported in run.log . The file applies to case-list runs (the outage-kind selector and the N-1 lists); a Scenarios run or an external scenario JSON uses the per-scenario weight . Scenarios need an SCF case; for other formats the form says so next to the export action. The scenario editor lists the open case's scenarios (edit, duplicate, delete, new) and edits one as op rows (status, set or scale on a component chosen by class). Validation is server side; errors name the scenario and op index, and a tap patch on a regulated transformer is rejected with the controller named. Save into case file writes the scenarios block through the SCF writer."),
  (title = "Diagnose", url = "/help/reference#diagnose", kind = "reference", text = "Diagnose next to Start PowerFlow run evaluates the mismatch at the case's stored operating point (MATPOWER VM / VA , the SvVoltage state of a CGMES delivery) without a corrective Newton step. Every start-value machine is forced off ( flatstart = false , start_projection = false , dc_seed_unconditional = false , start_current_iteration.enabled = false , apslf_start.enabled = false , plus max_iter = 1 and qlimits.enabled = false ), so the residual reflects the imported model; the forced settings outrank the form and the case configuration file. The run uses the normal pipeline and adds self_check.log (forced settings, start residual, for CGMES the count of buses without a usable SvVoltage , started at the voltage of a neighbour with one or at 1.0 pu / 0° , and the tap changers whose SvPowerFlow fits another step clearly better than their SvTapStep ), self_check_residuals.csv (per-bus P/Q residuals) and diagnose_self_check_config.yaml . Programmatically: run_fixed_reference_self_check . One step practically never converges; the residual is the measurement, so history and result page label the run diagnosed on a neutral badge (raw status in the tooltip). A diagnose run that could not run at all keeps the failure vocabulary."),
  (title = "Short circuit", url = "/help/reference#short-circuit", kind = "reference", text = "Short circuit next to Diagnose evaluates the balanced three-phase currents (IEC 60909-0, runShortCircuit! ) for every bus, maximum and minimum case in one run, without a power-flow solve. The button is enabled only when the case carries short-circuit source data; otherwise it is disabled with a tooltip. The run writes short_circuit_max.csv and short_circuit_min.csv (per-bus Ik'' , Sk'' , κ , i_p , safety flag and reasons, lower_bound ) and a run.log with the data coverage report. The result page and the view of each table start with the head line of the table: run status, flagged rows, rows whose Ik''max is a lower bound (a skipped source); both counts also show as warning badges. A MATPOWER or DTF case carries no source data and fails with short_circuit_requires_cgmes . Which data counts as a source in each format: Short-Circuit Analysis."),
  (title = "State estimation", url = "/help/reference#state-estimation", kind = "reference", text = "The state-estimation section of the Runs page ( /powerflow state-estimation ; /stateestimation redirects there) uses the shared case selection, selects a measurement set and runs observability (traffic light, structural-island note), the WLS solve and the diagnostics of State Estimation. The generator, \"add noise\" and every set Sparlectra ships write the measurement table (version line sparlectra-measurement-table v1 plus header); the run needs state_estimation.measurement_table on (the default). Uploaded .csv files are offered when they are a measurement table or carry the version comment of the measurement CSV v1; a CSV v1 set shows a notice at the file: its reader was removed in 0.50.0, a run and \"add noise\" on it stop with an error naming convertMeasurementsV1 , and the SCF export and Save case as leave it out and say so. The text and value editors work on both. The set list offers only the sets of the selected case: a set whose case: line names the case (or the case an SCF file was exported from); for a CGMES case a set without that line whose cgmes_model: line names the EQ model of the case (see Binding a table to its case); and a set without either line whose file name starts with the case name without its extension, followed by a dot ( sp_case14.measurements.csv for sp_case14.scf.json ). An uploaded set that matches none of these is offered for no case. assign to <case next to the upload binds the uploaded file to the selected case: its case: line is set to that case, whatever the file says, a measurement file of the same name is replaced, and the file is armed for the next run. Rows the case cannot resolve are counted in the import report of the run. Each entry names its case. Without a matching set the section says so and points to the generator. The run still refuses a set bound to another case. A case file with its own measurements offers those first; otherwise <case .measurements.csv is preselected (cases with a bound set are starred). Every generation and every \"add noise\" writes a new time-stamped file ( <case .measurements.<yyyymmdd-HHMMSS .csv , <case .noisy.<stamp .csv ) and arms it for the next run; later the newest set bound to the case is armed. Delete measurement file removes the armed set (never a case file). The set tab offers download, re-upload and an inline editor (the file keeps its format: a table its version line and header, a CSV v1 its version comment) and renders the sparlectra-taps v1 tap table of a generated file. Add noise to this set perturbs each value with the sigma its own row declares. Reset saved settings under the generator deletes the per-case settings sidecar. estimate taps ( state_estimation.tap_estimation.enabled of the case, on by default) releases every declared tap changer, ratio and phase, of every in-service transformer (a transformer that only carries a ratio has none); off, every changer keeps its transferred step. A changer whose step the measurements do not determine is not estimated and keeps its transferred step (status not_estimated with the reason), see Observability per changer. Which transformers are estimated is set per transformer on the Case page (section State estimation: tap estimation per transformer ): one \"estimate\" checkbox per transformer with a tap changer, machine transformers unchecked by default. Save case options writes the unchecked ones into state_estimation.tap_estimation.exclude of the case configuration and sets include_machine_transformers when a machine transformer is checked; every SE run of the case reads both. A machine transformer already named in exclude stays there on a save. An excluded transformer keeps its transferred step (reason excluded ). A machine transformer is calculated after the estimation (status calculated ) when Q is measured on every bus of its machine node; otherwise it keeps its step (reason q_not_measured_in_group ), see Tap estimation per transformer. The result page shows one row per tap changer (transferred step, estimated step and its raw value before rounding, Delta U, ratio, angle, deviation, status with its reason) and the J change of the fixation. tap fallback ( state_estimation.tap_estimation.fallback , on) runs once more without tap estimation when the run with it does not converge or its fixed steps fit worse than the staged pre-solve ( worse_fit ); the result page then shows one line above the tap table, see Tap estimation switch and fallback. tap impedance per step ( auto , off ) is state_estimation.tap_estimation.impedance_correction of the case, see Transformer tap estimation. zero-injection sigma is state_estimation.zero_injection_sigma_mva of the case, the sigma of one zero-injection row under zero_injection = on , see Zero injections and coupler balances. The form warns when k_suppress < k_eliminate , because suppressed rows then rarely reach the elimination. Artifacts ( measurements.csv , measurements_verdict.csv , se_diagnostics.md , se_view.md , se_state.csv , shunt_estimates.csv , se_tap_estimates.csv , se_deltas.csv , se_link_flows.csv , and under zero_injection = constraint se_zero_injection_multipliers.csv ) land in the run history with kind se . measurements.csv is the estimated set as a measurement table and can be picked as the measurement set of a new run; the verdict per row (residual, normalized residual, eliminated, reason) is in measurements_verdict.csv , one click away on the result page (see run artifacts). The result page offers Run power flow from this estimate and the topology hypothesis test behind a button ( topology_hypotheses.md ), which reads the run's measurements.csv without the rows measurements_verdict.csv marks as eliminated, so it starts from the J of the run. A run from before 0.50.0 still shows; its measurements.csv is a CSV v1, and the test asks for a new run. The summary shows J , E[J] = dof and the Wilson-Hilferty band verdict for the state after the elimination, with the suspicious and eliminated counts of the verdict file; suppressed rows stay in J and surface as J_active ."),
  (title = "QSTS", url = "/help/reference#webui_qsts", kind = "reference", text = "The case chooser offers every SCF time series (a zip with series.json , base.scf.json and delta.csv ), recognized by its content; the shipped example is sp_case14_day.qsts.zip (under data/qsts ). QSTS next to Contingency (N-1) runs the series step by step ( runQsts ); it is enabled only when the selected case is a series. QSTS mode , shown for a series only, chooses sequential (taps and banks carried from step to step) or snapshots (every step on its own). The run sets qsts.mode for itself; the configuration keeps its value. Start PowerFlow run on a series solves its base case. The controllers come from the companion file <series .control.yaml next to the series (for the example sp_case14_day.control.yaml , staged with it). Its control section replaces the one of the run configuration, for QSTS runs only; run.log names the file. Without it the controllers of the case file run alone. A snapshots run uses controllers only with qsts.snapshot_controls = true ; otherwise the result page and run.log say that they are not used. The status page counts the finished steps, and Abort run stops the run before the next step. The result page shows solved and failed steps, switches and hunting patterns per controller (sequential only), the steps with a voltage outside qsts.vm_min_pu to qsts.vm_max_pu or a loading above qsts.loading_max_pct , the loss energy and the notes of the run. The time series chart opens with the position of the first controller and the voltage of its regulated bus with the band dashed; Element and Quantity choose another series, each point carries its value as a tooltip. The CSV files open in the CSV view. Artifacts: the files of writeQstsResults , qsts_view.json (the element view behind the chart), one SVG per element with its main quantity under qsts_plots/ (bus vm_pu , branch loading_pct , controller position ) and qsts_overview.html . Mode, files and metrics: QSTS."),
  (title = "Running jobs", url = "/help/reference#running-jobs", kind = "reference", text = "A submission starts a background worker and redirects to the status page (elapsed time, case paths, start time, a manual refresh link). Queued, running and aborting pages refresh every two seconds ( autorefresh=1 requests are not logged as user actions); terminal pages stop. The start page and the run history show a banner with Open status and Abort while a job is queued or running; such a run cannot be deleted. An N-1 or scenario run shows how far its batch is: Outages done reads N-1: 37 / 186 outages (a scenario set reads Scenarios done , Scenarios: 3 / 10 scenarios ). The counter appears once the first outage has finished, after the import and the base-case solve; screened outages count as done. For large cases, the result page, run.log , result.json and performance.log show time per phase (reader, network builder, solver, artifacts)."),
  (title = "Abort", url = "/help/reference#abort", kind = "reference", text = "A queued or running job can be aborted from its status page or from the banner. Abort is cooperative: an operation that cannot be interrupted, such as a sparse factorization, finishes first; the status page shows the current phase. An aborted run keeps its run directory and is never reported as success. If a run stays in aborting for more than 60 s, the status page offers Hard reset Web UI : it marks the run invalid and stops the server. Restart with julia --project=. start_webui.jl ."),
  (title = "Feedback", url = "/help/reference#feedback", kind = "reference", text = "One-off messages (validation errors, import summary) open as a dismissible popup; recent errors stay listed on the Last errors page."),
  (title = "Results and artifacts", url = "/help/reference#results-and-artifacts", kind = "reference", text = "Every finished run gets a result page: run ID, schema version, status, convergence and solution flags, iterations, final mismatch, reason and message, input paths, output directory and a Solver entry. System frequency names the frequency with its source, or not used when no capacitance in farad entered the model (System frequency). A CSV artifact opens as a table (delimiter taken from the header line), a Markdown report rendered; Raw text shows the file as written. The CGMES import report of a run is the Markdown artifact cgmes_import_report.md ; a delivery with a DY profile gets a section Dynamic data (DY profile) there, with the counts of cgmes_import.read_dynamics or one line saying that the profile was not read (Dynamic data). Read dynamic data (DY profile) in the CGMES section of the Case page switches the key per case (default off); unchecking it again removes the key from the case file, so the default applies. Above a CSV table, Significant digits (default 5) rounds every decimal cell, and Power columns (W, kW or MW) shows power columns in whole units of that resolution, the unit then in the column header; 1.98e-16 MW shows as 0 at any resolution. A power column is one whose header name holds the token mw , mvar or mva (case-insensitive, tokens split at every character that is not a letter or digit: p_mw , q_mvar , s_mva , P [MW] ); other columns, such as vm_pu , get the significant digits only. Integer cells (bus numbers, counts) stay as written unless they sit in a power column with a resolution; a cell that is no number of the file's own format always does. Values below 1e-4 show with an exponent. The decimal separator follows the file: a semicolon file reads and shows with the decimal comma. The choice is part of the address ( ?digits=4&power=kW ) and carries over through the links to the other CSV files of the run. It changes the display only; Raw text and the download keep the file as written. A column header is a link that sorts the rows by that column: a column with numbers largest first, a text column A to Z (ignoring case); a second click turns the order ( ?sort=p_mw , &order=asc ). All rows the view reads (a large file is cut to the preview size, the page says so) are sorted before the table is cut to its first rows, so the largest value is on top; cells without a number, or empty text cells, go to the end. The sort column stays with Apply but not on the links to the other CSV files of the run. The header of a column whose cells are mostly numbers is right-aligned like its numbers, and the header row stays visible while the rows scroll. Columns are hidden with the button in the header or the Columns list; they are part of the address ( &hide=2,5 , column numbers of the file) and stay hidden through sorting and Apply . Rows are hidden with their checkbox and Hide selected rows or with the filter field (rows that contain a text in any cell); both stay in the browser tab until Show all rows . Other text artifacts (JSON, YAML, logs) open as escaped text with a download. An HTML report (the QSTS overview) opens as a page of its own with its charts; the server sends it with a policy that allows no script. SVG charts show in the browser, other files download. Download all artifacts as ZIP packs the exposed artifacts into sparlectra_run_<run_id _artifacts.zip ."),
  (title = "Output modes", url = "/help/reference#webui-output-modes", kind = "reference", text = "- Logfile output mode : classic writes the result report plus a compact timing and status summary ( solver_time , representative_time , iterations, final mismatch, outcome); full adds Full run details with the effective typed configuration, artifact choices and status diagnostics. MATPOWER .m runs also print the import-option and auto-profile tables; DTF .DAT runs never do. - Performance timing ( off , compact , full ) writes performance.log with the phases of one request (from request parsing to artifact writing, solver and total time; full adds internal profile entries). A run from the Web UI solves once; repeated timing is the benchmark mode of run_matpower_case in a script (Performance Profiling). - Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP) writes the case as one re-importable delivery into the run's artifacts, for every case format and also on non-converged runs; see CGMES Export. - Write bus/branch CSV files (API default off, because large networks produce large files) writes bus_voltages_complex.csv and branch_flows.csv from the ACPFlowReport rows; columns on Local PowerFlow Service. - CSV format is the machine-scope key output.csv_format ( Save settings writes it to the configuration file, a per-case save leaves it out) and applies to every CSV of every run type; auto (the default) follows the regional settings of the machine. Values and delimiters: Configuration. Excel may still auto-convert identifiers like 1E5 ; use Data From Text/CSV with text types when that matters."),
  (title = "Diagnostic artifacts", url = "/help/reference#diagnostic-artifacts", kind = "reference", text = "diagnose.log is written by Diagnose or with run_diagnostics = true , never by a normal run. On a non-converged run it names the worst-mismatch bus and equation, classifies the mismatch trend (monotonic, oscillatory, stagnant, diverging to non-finite) and the autodamp health, scans the branches at the worst bus for zero impedance, off-nominal taps, large phase shifts or an outlying reactance, and closes with recommendations. A diagnostic exception stays in the file without changing a successful result. A run that attempts the current-iteration pre-solve may add current_iteration_start.log : whether the candidate was attempted, accepted, or rejected (by a guard, or with the original start restored)."),
  (title = "Comparing two runs", url = "/help/reference#comparing-two-runs", kind = "reference", text = "Tick Compare on two history rows (two runs of the same case under different settings) and press Compare selected runs ; the page shows side by side: case file, status, converged flag, iterations and final mismatch with a link to each result page; the configuration keys the runs disagree on (from effective_config.yaml ); the buses each run clamped (from q_limit_events.csv ) and which only one of them clamped; total losses (from branch_flows.csv ) with the difference; the largest voltage deviation and the ten buses that differ most, when both runs wrote bus_voltages_complex.csv . Everything comes from what the runs wrote, so earlier sessions compare as well; exactly two runs are required. The box appears only on finished power-flow runs (plain, diagnose, or started from an estimate) whose result is still on disk; the page says so when the runs share no bus."),
  (title = "Run history and operation log", url = "/help/reference#run-history-and-operation-log", kind = "reference", text = "start_sparlectra_webui refreshes powerflow_runs_index.json under the output root before serving, so runs of an earlier process appear at once; Refresh registry reloads by hand, and missing, corrupt or unsafe entries are skipped without hiding the valid ones. History is newest first: local date and time, run ID, status text and badge, solver summary fields and actions. Case file and Config file show the file name, the full path in the tooltip. Delete removes one run, Delete all runs every registered run under the configured root; both delete only validated run directories. The Operation Log page shows and downloads logs/webui_operations.jsonl , a JSON Lines support log independent of the run directories: page opens, submissions, validation failures, run lifecycle changes, artifact views and downloads, aborts, history refreshes, deletions and shutdown requests (not static CSS or image requests), each with route, method, status, run, case, artifact, message and timing fields where available, sparlectra_version and a UTC timestamp, never file contents or configuration bodies. Logging cannot fail a request; per-iteration timings belong to performance.log . Every start drops entries older than webui.operation_log_retention_days (default 10, 0 keeps only the current session); SPARLECTRA_WEBUI_OPERATION_LOG_RETENTION_DAYS overrides the key for headless runs. On append, a log above 1 MiB is compacted and more than 5,000 valid entries are cut to the newest 1,000. The page states its size and offers Clear operation log , which empties the file and writes one entry recording that. A large log is a matter of entry count, not age; a retention of two or three days is the lasting remedy."),
  (title = "Configuration", url = "/help/reference#webui-configuration", kind = "reference", text = "Check configuration and Refresh configuration bring a local file up to a template that gained options. Check is a dry run against src/config/configuration.yaml.example (missing keys, deprecated aliases, duplicate YAML keys, a preview of the refreshed YAML), nothing written. Refresh keeps existing values, adds missing keys with template defaults and may normalize deprecated aliases; it never runs at startup, writes a timestamped backup first, refuses on duplicate keys, and offers uploaded or pasted YAML as a download instead of rewriting it. The Configuration Editor opens the active YAML in a textarea, validates it with the same parser and duplicate-key checks, writes only after validation with a timestamped backup, and warns when a case configuration file still overrides the global YAML. After a save the server reloads the file. The search box above the text finds plain text ( Next / Previous , Enter / Shift+Enter) or jumps to a dotted key such as power_flow.qlimits.guard.enabled . Form values override the YAML configuration; the order is described in Configuration. Each run writes effective_config.yaml . Ignore Web UI settings and use configuration defaults runs with the YAML values only. model.auto_profile: apply may still adjust MATPOWER import conventions after form and API values are assembled; effective_config.yaml records that. Help in the header opens the help (Web UI) inside the Web UI, as shipped with the running version; Project Docs opens the published documentation ( webui.docs_base_url ). The help pages behind the ? icons carry a section of the help or of this reference in full, or the lead paragraph of a library section with the link to it."),
  (title = "Search the help", url = "/help/reference#webui_help_search", kind = "reference", text = "The search field stands at the top of the help, of this reference and in the header of every page and looks through the help, the reference and the help pages of the controls. Every word entered must occur (a part of a word is enough, case does not matter); hits appear while you type, hits in a heading first, each with a marked line of text. / focuses the field, Enter opens the first hit, Esc closes the list. Without a hit the page links to the published documentation. The index ships with the application; with scripts switched off the field is a plain form."),
  (title = "Shutdown", url = "/help/reference#shutdown", kind = "reference", text = "The server stops with Stop Web UI , close(server) or Ctrl+C . With auto_shutdown_on_browser_close = true it also stops when the browser has been gone for browser_heartbeat_timeout_seconds (best effort). Stop Web UI also saves the size and position of the app window into the configuration file ( webui.window_width , webui.window_height , webui.window_x , webui.window_y ), and the next start opens the window there. A minimized window is not saved; Ctrl+C and close(server) save nothing. The app window runs in its own browser profile ( browser next to runs ), because a browser that is already open ignores size and position of a new window. Under Linux with Wayland it runs through X11 (XWayland): Wayland windows can neither read nor set their screen position. The operation log records the save as webui_window_geometry ."),
  (title = "Limits", url = "/help/reference#limits", kind = "reference", text = "Loopback only, no authentication, no public-server mode, no database. No push channel: a running job reports its phase through the page refresh. No topology view, no plotting apart from the QSTS chart."),
  (title = "Equivalent injections as source", url = "/help/cgmes_import.equivalent_injection_as_source", kind = "control", text = "An EquivalentInjection on the SV angle reference or a boundary node becomes a regulating source at its SV voltage; the one on the reference is the slack. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "HVDC converters", url = "/help/cgmes_import.hvdc_mode", kind = "control", text = "HVDC converter model: fixed injections reproduce the delivery snapshot; a paired controller couples both converters of a link and makes the transfer steerable. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "Infer missing base voltages", url = "/help/cgmes_import.infer_base_voltages", kind = "control", text = "Reconstruct missing nominal voltages from SV voltages and transformer ratings when the delivery has no BaseVoltage catalog. Pair with an unchecked boundary set. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "Read dynamic data (DY profile)", url = "/help/cgmes_import.read_dynamics", kind = "control", text = "Read the DY profile and give the machines their dynamic data (inertia, damping, rating, droop). No calculation reads it; off, the DY file is skipped. With read_dynamics = true the store reads the DY profile as well (profile tag DY ; without the switch the file is skipped, and one import notice says that a DY profile is present and not read) and the machines get their DynamicData (Dynamic Unit Data). No calculation reads it; the island slack choice reads the unit type. In the Web UI the switch is Read dynamic data (DY profile) in the CGMES section of the Case page, saved per case."),
  (title = "Require boundary set", url = "/help/cgmes_import.require_boundary", kind = "control", text = "Fail the CGMES import when topology references stay unresolved (boundary set missing). Uncheck to import an incomplete delivery anyway. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "CGMES start values", url = "/help/cgmes_import.start_values", kind = "control", text = "auto starts from the delivery's SvVoltage state when it carries one, else flat; sv always uses the imported state, flat always starts flat. The keys that steer a CGMES import: where the delivery is, the system base, whether unresolved boundary references fail the import, and the per-element handling described below. The Web UI carries the ones a delivery is usually adjusted with."),
  (title = "Busbar sections", url = "/help/contingency.events.busbars", kind = "control", text = "One busbar section out: its branches and its closed couplers; the other sections stay. Some elements trip together: two circuits on the same towers, every branch at a faulted busbar, a whole station. Such an event is one case with several elements, solved in one run on the same path as N-1. Five generators build them from the topology; each returns a list of ContingencyCase s:"),
  (title = "Double circuits", url = "/help/contingency.events.double_circuits", kind = "control", text = "Branches with the same two endpoints trip together. Some elements trip together: two circuits on the same towers, every branch at a faulted busbar, a whole station. Such an event is one case with several elements, solved in one run on the same path as N-1. Five generators build them from the topology; each returns a list of ContingencyCase s:"),
  (title = "Correlated events", url = "/help/contingency.events.enabled", kind = "control", text = "Add elements that trip together to a branch N-1 of an SCF case: the classes below, each as one case. Some elements trip together: two circuits on the same towers, every branch at a faulted busbar, a whole station. Such an event is one case with several elements, solved in one run on the same path as N-1. Five generators build them from the topology; each returns a list of ContingencyCase s:"),
  (title = "Couplers", url = "/help/contingency.events.links", kind = "control", text = "Each closed busbar coupler (bus link) opens alone. Some elements trip together: two circuits on the same towers, every branch at a faulted busbar, a whole station. Such an event is one case with several elements, solved in one run on the same path as N-1. Five generators build them from the topology; each returns a list of ContingencyCase s:"),
  (title = "Event size limit", url = "/help/contingency.events.max_members", kind = "control", text = "Events with more elements are skipped. Some elements trip together: two circuits on the same towers, every branch at a faulted busbar, a whole station. Such an event is one case with several elements, solved in one run on the same path as N-1. Five generators build them from the topology; each returns a list of ContingencyCase s:"),
  (title = "Name groups", url = "/help/contingency.events.name_groups", kind = "control", text = "Branches whose file names differ only in a circuit number, same voltage and same stations. Some elements trip together: two circuits on the same towers, every branch at a faulted busbar, a whole station. Such an event is one case with several elements, solved in one run on the same path as N-1. Five generators build them from the topology; each returns a list of ContingencyCase s:"),
  (title = "Whole stations", url = "/help/contingency.events.substations", kind = "control", text = "A whole station out: every branch at all its busbar sections. Some elements trip together: two circuits on the same towers, every branch at a faulted busbar, a whole station. Such an event is one case with several elements, solved in one run on the same path as N-1. Five generators build them from the topology; each returns a list of ContingencyCase s:"),
  (title = "Outage max iterations", url = "/help/contingency.max_iter", kind = "control", text = "Iteration cap of every N-1 outage and scenario solve; the base case keeps Maximum iterations. Lower keeps a large batch fast. The base case of a batch is solved with power_flow.max_iter , every outage and scenario with contingency.max_iter (default 30 ; keywords maxIte and base_maxIte of runContingencies! and runScenarios! ; Web UI: Outage max iterations in the N-1 contingency box of the Settings page). A lower outage limit keeps a large batch fast: an outage that needs more steps ends as not converged instead of iterating on."),
  (title = "N-2 pairs", url = "/help/contingency.pairs.enabled", kind = "control", text = "Add every pair of closed branches to a branch N-1 of an SCF case. The count grows with the square of the branches. generateBranchPairs lists every unordered pair of closed branches as a case of kind :pair , named P <a + <b . The count grows with the square of the branch count: 74 branches give 2701 pairs, 217 give 23436. More than max_pairs pairs (default 50000) throw before anything is solved; the run never truncates silently. In the service, contingency.pairs.enabled adds the pairs to a branch N-1 of an SCF case; a pair with the same member set as an event is listed once, as the event."),
  (title = "Pair limit", url = "/help/contingency.pairs.max_pairs", kind = "control", text = "A run with more pairs stops before solving, with the count in the message. generateBranchPairs lists every unordered pair of closed branches as a case of kind :pair , named P <a + <b . The count grows with the square of the branch count: 74 branches give 2701 pairs, 217 give 23436. More than max_pairs pairs (default 50000) throw before anything is solved; the run never truncates silently. In the service, contingency.pairs.enabled adds the pairs to a branch N-1 of an SCF case; a pair with the same member set as an event is listed once, as the event."),
  (title = "Pair rule", url = "/help/contingency.pairs.rule", kind = "control", text = "all: every unordered pair of closed branches. generateBranchPairs lists every unordered pair of closed branches as a case of kind :pair , named P <a + <b . The count grows with the square of the branch count: 74 branches give 2701 pairs, 217 give 23436. More than max_pairs pairs (default 50000) throw before anything is solved; the run never truncates silently. In the service, contingency.pairs.enabled adds the pairs to a branch N-1 of an SCF case; a pair with the same member set as an event is listed once, as the event."),
  (title = "Screening margin (percent)", url = "/help/contingency.screening.margin_pct", kind = "control", text = "Full solve when an estimate comes near a limit: voltage within this percent of the band, loading plus the outage's change (capped here) at 100 %. With screening_mode = :flag (keyword on runContingencies! and runScenarios! , or contingency.screening.mode for the service and the Web UI) every non-islanding single outage is first estimated with one Woodbury-corrected Newton step on the factorized base Jacobian; only cases whose estimate comes close to a limit get the full solve: a voltage within screening.margin_pct (default 10) percent of the band width, or a branch whose estimated loading plus the change the outage causes on it (at least 1 point, at most the margin) reaches 100 percent, because the error of the estimate grows with that change. Switch screening on only after checking, on your own network, the screening share and that the flagged margins carry the violations (the reported screened count and reason breakdown)."),
  (title = "N-1 screening", url = "/help/contingency.screening.mode", kind = "control", text = "off: every outage solved in full. flag: estimate each outage first, solve only those near a limit. only: estimates. Check the share once. With screening_mode = :flag (keyword on runContingencies! and runScenarios! , or contingency.screening.mode for the service and the Web UI) every non-islanding single outage is first estimated with one Woodbury-corrected Newton step on the factorized base Jacobian; only cases whose estimate comes close to a limit get the full solve: a voltage within screening.margin_pct (default 10) percent of the band width, or a branch whose estimated loading plus the change the outage causes on it (at least 1 point, at most the margin) reaches 100 percent, because the error of the estimate grows with that change. Switch screening on only after checking, on your own network, the screening share and that the flagged margins carry the violations (the reported screened count and reason breakdown)."),
  (title = "Warm active set", url = "/help/contingency.warm_active_set", kind = "control", text = "Outages start from the base case's PV/PQ state: about half the Newton steps. Outages near a limit are checked cold as well (margin below). The base case of an N-1 batch is solved with Q limits, and on a large network many machines end clamped. Without the warm start every outage starts from the base voltages but with the file's bus types and clamps the same machines again (a jump of the mismatch, about twice the Newton steps). The warm active set ( contingency.warm_active_set , default true ; keyword warm_active_set on runContingencies! and runScenarios! ; Web UI: the checkbox in the N-1 contingency box of the Settings page) starts every outage and scenario with the base case's clamped machines as PQ at their limit. The active set stays free: a machine whose voltage recovers goes back to PV, new clamps follow the normal rules."),
  (title = "Cold check of tight outages", url = "/help/contingency.warm_cold_check", kind = "control", text = "Solve a warm outage near the voltage limit, or with a violation, cold as well and report the less favourable result. Off by default: the warm result alone. The base case of an N-1 batch is solved with Q limits, and on a large network many machines end clamped. Without the warm start every outage starts from the base voltages but with the file's bus types and clamps the same machines again (a jump of the mismatch, about twice the Newton steps). The warm active set ( contingency.warm_active_set , default true ; keyword warm_active_set on runContingencies! and runScenarios! ; Web UI: the checkbox in the N-1 contingency box of the Settings page) starts every outage and scenario with the base case's clamped machines as PQ at their limit. The active set stays free: a machine whose voltage recovers goes back to PV, new clamps follow the normal rules."),
  (title = "Cold check margin (pu)", url = "/help/contingency.warm_cold_check_margin_pu", kind = "control", text = "A warm outage this close above the lower voltage limit, or with a violation, is solved cold as well; the less favourable result counts. The base case of an N-1 batch is solved with Q limits, and on a large network many machines end clamped. Without the warm start every outage starts from the base voltages but with the file's bus types and clamps the same machines again (a jump of the mismatch, about twice the Newton steps). The warm active set ( contingency.warm_active_set , default true ; keyword warm_active_set on runContingencies! and runScenarios! ; Web UI: the checkbox in the N-1 contingency box of the Settings page) starts every outage and scenario with the base case's clamped machines as PQ at their limit. The active set stays free: a machine whose voltage recovers goes back to PV, new clamps follow the normal rules."),
  (title = "Write solution into MATPOWER export", url = "/help/matpower_export.write_solution", kind = "control", text = "Write the solved bus VM/VA state and the branch flow columns into the MATPOWER export. Off exports a pure model file with flat voltages. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Apply bus names", url = "/help/matpower_import.apply_bus_names", kind = "control", text = "Use the case file's mpc.bus_name entries as bus names in results and logs instead of numeric BUS_I ids. Requires a bus_name block matching the bus count. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Voltage reference comparison", url = "/help/matpower_import.compare_voltage_reference", kind = "control", text = "Voltage reference used when results are compared with the case data: bus VM, generator VG, the imported setpoint, or hybrid when VM and VG disagree. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "DC-line mode", url = "/help/matpower_import.matpower_dcline_mode", kind = "control", text = "Model of active mpc.dcline rows: pf_injections adds two fixed terminal injections per row; paired_control also couples each pair as a steerable HVDC link. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "PV voltage source", url = "/help/matpower_import.pv_voltage_source", kind = "control", text = "Source of the PV voltage setpoint: the generator VG (standard MATPOWER) or the bus VM; auto and strict_check use VG and warn when VG and VM differ. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Transformer ratio convention", url = "/help/matpower_import.ratio", kind = "control", text = "Interpretation of the branch ratio column: normal is the standard MATPOWER convention, reciprocal inverts it. Change it only for a known alternate convention. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Phase-shift sign", url = "/help/matpower_import.shift_sign", kind = "control", text = "Sign convention of the phase-shift column, 1 or -1. Flip it only to align with another tool's convention. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Phase-shift unit", url = "/help/matpower_import.shift_unit", kind = "control", text = "Unit of the phase-shift column, degrees or radians. A wrong declaration shifts every phase shifter. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "MATPOWER auto-profile", url = "/help/model.auto_profile", kind = "control", text = "Experimental scan of the stored voltages, off by default: recommend logs convention recommendations, apply changes only safe conventions with clear evidence. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Bus-shunt model", url = "/help/model.bus_shunt_model", kind = "control", text = "Interpretation of bus shunts: constant admittance (default) or a voltage-dependent injection. Change it only with residual evidence. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "System frequency", url = "/help/model.nominal_frequency_hz", kind = "control", text = "Acts only where capacitance is used: lines from per-km capacitance, PGM/SCF c1. Short circuit is frequency independent; ohm, siemens or pu cases are unchanged. The system frequency is a property of the network: every Net carries it as net.nominal_frequency_hz . model.nominal_frequency_hz (default 50.0, 60 for a North American network, any positive value) sets it when the case states none:"),
  (title = "Tap-changer model", url = "/help/model.tap_changer_model", kind = "control", text = "Tap-changer model applied to all transformers after import: ideal, or impedance correction that scales R and X with the tap position. The keys of a MATPOWER run: the case selectors, the import profile that recommends or applies the conventions a case needs, the conversion switches (phase-shift unit and sign, tap ratio, PV voltage source, shunt and tap-changer model, generator controllers), the solution export and the network preallocation."),
  (title = "Logfile output mode", url = "/help/output.logfile_results", kind = "control", text = "Detail of the solved result tables in run.log: off, compact, classic (result report plus timing summary) or full (adds the effective configuration). What a run writes besides its result: the console summary and its diagnostics, the log files, and the detailed CSV export with its writer settings."),
  (title = "APSLF convergence radius", url = "/help/power_flow.apslf.convergence_radius", kind = "control", text = "Evaluate the APSLF convergence radius, the distance of the nearest Padé pole to the evaluation point. Costs about as much as the solve; shown with the result. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation ( rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver, a required dependency; see External Solvers."),
  (title = "APSLF NR polish", url = "/help/power_flow.apslf.nr_polish", kind = "control", text = "Run a Newton-Raphson polishing step on the APSLF series result. Default off: the series alone is a load-flow solution. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation ( rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver, a required dependency; see External Solvers."),
  (title = "APSLF highest coefficient (order)", url = "/help/power_flow.apslf.order", kind = "control", text = "Highest power-series coefficient computed by the APSLF solver. Higher orders help stressed cases but increase the solve cost. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation ( rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver, a required dependency; see External Solvers."),
  (title = "Use APSLF start values", url = "/help/power_flow.apslf_start.enabled", kind = "control", text = "APSLF solver as a guarded start-value generator ahead of Newton-Raphson: the candidate is kept only if it improves the mismatch. Not with solver APSLF. With power_flow.apslf_start.enabled the APSLF solver runs once before the rectangular Newton-Raphson solve, at the insertion point of the current-iteration pre-solve and with the same guard: the candidate is adopted only when it strictly improves the rectangular mismatch, otherwise the original start values are restored. The generator always runs without NR polish (the Newton solve that follows does the polishing) and without Q limits ( power_flow.qlimits. governs only the Newton solve); neither is configurable here. Requires AnalyticLoadFlow.jl; mutually exclusive with power_flow.solver = apslf and start_mode.dc_seed_unconditional . Diagnostic artifact: apslf_start.log ."),
  (title = "APSLF start highest coefficient (order)", url = "/help/power_flow.apslf_start.order", kind = "control", text = "Highest series coefficient of the APSLF start-value generator; higher orders cost more before the candidate is judged. No effect unless the generator is on. With power_flow.apslf_start.enabled the APSLF solver runs once before the rectangular Newton-Raphson solve, at the insertion point of the current-iteration pre-solve and with the same guard: the candidate is adopted only when it strictly improves the rectangular mismatch, otherwise the original start values are restored. The generator always runs without NR polish (the Newton solve that follows does the polishing) and without Q limits ( power_flow.qlimits. governs only the Newton solve); neither is configurable here. Requires AnalyticLoadFlow.jl; mutually exclusive with power_flow.solver = apslf and start_mode.dc_seed_unconditional . Diagnostic artifact: apslf_start.log ."),
  (title = "Auto slack: promote a reference when none is registered", url = "/help/power_flow.auto_slack", kind = "control", text = "Case without a slack bus: promote the strongest unit as reference (logged); off aborts such a run. Islands always pick their own reference, with or without it. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Autodamping enabled", url = "/help/power_flow.autodamp", kind = "control", text = "Adaptive damping of the Newton step. Helps difficult convergence at a small overhead; switch it off only for strict algorithm comparisons. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Autodamping minimum", url = "/help/power_flow.autodamp_min", kind = "control", text = "Minimum damping factor while autodamping is active. Lower values stabilize hard cases but can increase the iteration count. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Standalone-DC fallback", url = "/help/power_flow.dc.fallback", kind = "control", text = "When AC and the rescue ladder fail, keep a standalone DC result: angles and branch P flows at 1 pu, no reactive results. The AC status stays non-converged. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Distributed active-power slack enabled", url = "/help/power_flow.distributed_slack.enabled", kind = "control", text = "Spread the active-power imbalance over participating generators instead of the single slack bus. Off is bit-identical to the classical single-slack solver. power_flow.distributed_slack spreads the active-power imbalance of an island (load plus losses minus scheduled generation) over the participating generators instead of the reference bus. Theory, the augmented Newton system and the applicability rules: Solver Guide."),
  (title = "Distributed-slack weight mode", url = "/help/power_flow.distributed_slack.p_mode", kind = "control", text = "Weight source of the participation factors: scheduled Pg, maximum P, remaining headroom, the imported factors, or an explicit weights table from the YAML. power_flow.distributed_slack spreads the active-power imbalance of an island (load plus losses minus scheduled generation) over the participating generators instead of the reference bus. Theory, the augmented Newton system and the applicability rules: Solver Guide."),
  (title = "External grid source enabled", url = "/help/power_flow.external_grid.enabled", kind = "control", text = "Model the slack as a non-ideal source behind a feeder impedance, so its voltage droops under load. Off keeps the ideal slack; not with the distributed slack. power_flow.external_grid computes the marked slack bus as a non-ideal external-grid source: before the solve, convertSlackToExternalGrid! moves the reference voltage to a hidden internal bus <bus __extgrid_int behind the feeder impedance z = Un^2/Sk'' (split by the R/X ratio), and the former slack bus becomes a solved bus whose voltage droops under load. Theory, the stiff limit and the short-circuit effect: Slack Bus and External Grid Sources."),
  (title = "External grid R/X ratio", url = "/help/power_flow.external_grid.rx", kind = "control", text = "R/X ratio of the feeder impedance of the external grid source. power_flow.external_grid computes the marked slack bus as a non-ideal external-grid source: before the solve, convertSlackToExternalGrid! moves the reference voltage to a hidden internal bus <bus __extgrid_int behind the feeder impedance z = Un^2/Sk'' (split by the R/X ratio), and the former slack bus becomes a solved bus whose voltage droops under load. Theory, the stiff limit and the short-circuit effect: Slack Bus and External Grid Sources."),
  (title = "External grid short-circuit power Sk'' [MVA]", url = "/help/power_flow.external_grid.sk_MVA", kind = "control", text = "Initial symmetrical short-circuit power of the feeder in MVA. It sets the series impedance of the external grid source (z = baseMVA/Sk''). power_flow.external_grid computes the marked slack bus as a non-ideal external-grid source: before the solve, convertSlackToExternalGrid! moves the reference voltage to a hidden internal bus <bus __extgrid_int behind the feeder impedance z = Un^2/Sk'' (split by the R/X ratio), and the former slack bus becomes a solved bus whose voltage droops under load. Theory, the stiff limit and the short-circuit effect: Slack Bus and External Grid Sources."),
  (title = "External grid Sk''/R-X source", url = "/help/power_flow.external_grid.source", kind = "control", text = "Where Sk'' and R/X come from: auto prefers values the case declares on the slack bus, else the numbers below; config always uses the numbers below. power_flow.external_grid computes the marked slack bus as a non-ideal external-grid source: before the solve, convertSlackToExternalGrid! moves the reference voltage to a hidden internal bus <bus __extgrid_int behind the feeder impedance z = Un^2/Sk'' (split by the R/X ratio), and the former slack bus becomes a solved bus whose voltage droops under load. Theory, the stiff limit and the short-circuit effect: Slack Bus and External Grid Sources."),
  (title = "Flat start", url = "/help/power_flow.flatstart", kind = "control", text = "Every bus at 1.0 pu and the slack angle, stored voltages ignored, no projection or DC start. Star points start at their ratio. power_flow.flatstart starts the Newton-Raphson solve at 1.0 pu and the slack angle on every bus and ignores the imported start voltages (MATPOWER VM / VA , CGMES SvVoltage , SCF start_state ). Off, the imported values seed the solve; a delivery is built around its own operating point, so that is the default. While the flat start is on, the run switches the start projection, the DC start values, the two start modes and the ratio profile off, also when the configuration file has start_projection: true . The page greys those controls (saved values stay) and the run log names the override. The current-iteration pre-solve and the APSLF start follow their own checkboxes. Three-winding star points start at the ratio of their stiffest winding on every flat start; all other buses stay flat. Flat start turned behind phase shifters ( power_flow.start_mode.rotate_behind_pst , off by default) starts a bus that the slack reaches only across phase-shifting transformers at the slack angle plus the shifts of a path with the fewest shifters, on a flat start and on a stored start without angles. A bus that a path without shifter reaches keeps the slack angle. See Start strategies by case. Ratio profile as a start candidate ( power_flow.start_mode.ratio_profile , on by default) is a candidate of the start projection: the flat profile with each voltage level scaled by the transformer ratios on its path from the slack, applied to every PQ bus (not only to three-winding star points) when its mismatch is at least 10 percent lower. The flat start switches it off for the whole run, rescue and auto stages included. Without the flat start it acts only where a projection starts from the flat profile: in the rescue ladder's alternate start, unless Start angle mode is dc (the DC angles keep precedence), and in the auto mode. The page greys the checkbox in every other case: flat start on, or neither Auto mode nor Rescue with a start angle mode other than dc . A greyed checkbox is not posted and the saved value stays. A CGMES run honours the flat start under CGMES start values = auto ; an explicit sv on the Case page still starts from the delivery state (Power flow configuration)."),
  (title = "Dishonest Newton (reuse Jacobian factorisation)", url = "/help/power_flow.jacobian_reuse", kind = "control", text = "Reuses the previous LU while the mismatch falls fast; changes iteration counts, not the solution. For repeated solves of one large case, not for N-1. power_flow.jacobian_reuse: true (keyword jacobian_reuse = true ; Web UI: the checkbox \"Dishonest Newton\" under Solver backend, below power mode) keeps the Jacobian factorization for the next Newton step while the mismatch falls by at least jacobian_reuse_min_reduction (default 10) per step, at most jacobian_reuse_max_steps (default 3) steps in a row. Off by default; it changes the iteration count, not the solution, and works with and without power mode. The rules are on the Solver Guide."),
  (title = "Maximum reused steps in a row", url = "/help/power_flow.jacobian_reuse_max_steps", kind = "control", text = "Reused steps in a row before a forced refactorisation (default 3). power_flow.jacobian_reuse: true (keyword jacobian_reuse = true ; Web UI: the checkbox \"Dishonest Newton\" under Solver backend, below power mode) keeps the Jacobian factorization for the next Newton step while the mismatch falls by at least jacobian_reuse_min_reduction (default 10) per step, at most jacobian_reuse_max_steps (default 3) steps in a row. Off by default; it changes the iteration count, not the solution, and works with and without power mode. The rules are on the Solver Guide."),
  (title = "Minimum mismatch reduction per step", url = "/help/power_flow.jacobian_reuse_min_reduction", kind = "control", text = "Factor by which a step must cut the maximum mismatch so that the next step reuses the factorisation (default 10, above 1). power_flow.jacobian_reuse: true (keyword jacobian_reuse = true ; Web UI: the checkbox \"Dishonest Newton\" under Solver backend, below power mode) keeps the Jacobian factorization for the next Newton step while the mismatch falls by at least jacobian_reuse_min_reduction (default 10) per step, at most jacobian_reuse_max_steps (default 3) steps in a row. Off by default; it changes the iteration count, not the solution, and works with and without power mode. The rules are on the Solver Guide."),
  (title = "Linear solver backend", url = "/help/power_flow.linear_solver", kind = "control", text = "Sparse backend of the Newton step. umfpack_reuse keeps the symbolic analysis across iterations, faster on large cases; umfpack analyzes every iteration anew. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Maximum iterations", url = "/help/power_flow.max_iter", kind = "control", text = "Iteration cap of the Newton-Raphson solve; a run that reaches it ends as non-converged. Very low values cut off hard cases. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Armijo sufficient-decrease constant", url = "/help/power_flow.merit.armijo_c1", kind = "control", text = "Sufficient-decrease constant of the Armijo condition. Larger values reject more trial steps and increase the backtracking. power_flow.merit adds an Armijo sufficient-decrease test to the autodamp backtracking loop of the rectangular solver; it replaces neither Newton-Raphson nor autodamp. Off by default, which leaves the max-mismatch autodamp unchanged. Requires power_flow.autodamp = true (validation error otherwise). Theory: Merit-Function Line Search."),
  (title = "Enable Armijo merit-function line search", url = "/help/power_flow.merit.enabled", kind = "control", text = "Armijo merit-function line search for step acceptance on difficult flat-start cases. Requires autodamping; adds one residual-norm evaluation per trial. power_flow.merit adds an Armijo sufficient-decrease test to the autodamp backtracking loop of the rectangular solver; it replaces neither Newton-Raphson nor autodamp. Off by default, which leaves the max-mismatch autodamp unchanged. Requires power_flow.autodamp = true (validation error otherwise). Theory: Merit-Function Line Search."),
  (title = "Merit fallback behavior", url = "/help/power_flow.merit.fallback_max_mismatch", kind = "control", text = "When no trial satisfies the Armijo condition, fall back to the max-mismatch criterion (first improving trial). Off takes the most conservative finite trial. power_flow.merit adds an Armijo sufficient-decrease test to the autodamp backtracking loop of the rectangular solver; it replaces neither Newton-Raphson nor autodamp. Off by default, which leaves the max-mismatch autodamp unchanged. Requires power_flow.autodamp = true (validation error otherwise). Theory: Merit-Function Line Search."),
  (title = "Newton update", url = "/help/power_flow.newton_update", kind = "control", text = "How a Newton step is applied: polar (default) as magnitude and angle, MATPOWER's update, safer on flat starts; rectangular adds it to the complex voltage. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Power mode for repeated solves", url = "/help/power_flow.power_mode", kind = "control", text = "Keeps Ybus, LU analysis and work arrays on the network between solves and skips the ranked mismatch diagnostics. Same solution; off for a single run. Power mode is for the cases where one network is solved many times: a benchmark on a persistent model, the scenario engine, N-1 contingency sweeps, Monte Carlo, outer control loops. It is off by default; a single run gains nothing from it."),
  (title = "Power-mode LU", url = "/help/power_flow.power_mode_lu", kind = "control", text = "auto chooses once per network from KLU's symbolic flop estimate (UMFPACK above 5e7 flops); klu or umfpack fix it. Greyed while power mode is off. KLU's numeric refactorization is 6 to 20 times faster than UMFPACK's on power-flow Jacobians of 5k to 60k unknowns. On very large Jacobians it is the other way round: KLU's partial pivoting takes thousands of off-diagonal pivots there, its factor grows well beyond the estimate of its analysis, and on the 82000-bus case_SyntheticUSA a power-mode run with KLU took more than twice as long as one without power mode. Neither backend is right for every network, so auto chooses per network:"),
  (title = "Auto start threshold (pu)", url = "/help/power_flow.qlimits.auto_q_delta_pu", kind = "control", text = "Reactive-power change per iteration below which the auto start rule lets switching begin. Used by the start rules auto and iteration_or_auto. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Classic outer-loop passes", url = "/help/power_flow.qlimits.classic_max_passes", kind = "control", text = "Classic modes only: solves after the base solve, one per Q-limit update. Violations after the last one stop the loop (max_outer_iterations, not converged). How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Cooldown iterations", url = "/help/power_flow.qlimits.cooldown_iters", kind = "control", text = "Iterations a bus waits after a switch before it may switch again. Reduces back-and-forth on machines close to a limit. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Q-limit handling enabled", url = "/help/power_flow.qlimits.enabled", kind = "control", text = "Master switch for generator Q-limit enforcement (PV to PQ switching). Off gives an unconstrained power flow; on can add switching iterations. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Q-limit enforcement mode", url = "/help/power_flow.qlimits.enforcement_mode", kind = "control", text = "Selects active-set or classical Q-limit switching; the classical modes may need repeated solves. off disables the handling like the checkbox above. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Final check bound (pu)", url = "/help/power_flow.qlimits.final_q_accept_pu", kind = "control", text = "Bound of the final Q-limit check every mode ends with, the classic ones too: an overshoot up to it is accepted with a warning. auto: twice the hysteresis. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Accept bounded violations", url = "/help/power_flow.qlimits.guard.accept_bounded_violations", kind = "control", text = "Accept a converged run with up to the allowed number of remaining Q-limit violations instead of rejecting it. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Narrow-range guard enabled", url = "/help/power_flow.qlimits.guard.enabled", kind = "control", text = "Before the solve, run machines with a narrow or zero Q range as PQ (the range rules below). The switch cap, freezing and violation rule act without it. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Freeze after repeated switching", url = "/help/power_flow.qlimits.guard.freeze_after_repeated_switching", kind = "control", text = "Freeze a bus that reached the maximum switch count in its current type. The run then ends as max_switching_exceeded unless the Q check passes. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Guard log line", url = "/help/power_flow.qlimits.guard.log", kind = "control", text = "Print how many narrow-range machines the guard locked as PQ or keeps PV until a limit; appears with verbose console output. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Accepted remaining violations", url = "/help/power_flow.qlimits.guard.max_remaining_violations", kind = "control", text = "How many PV buses may still violate a Q limit at the end when bounded violations are accepted. 0 accepts none. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Maximum switches per bus", url = "/help/power_flow.qlimits.guard.max_switches", kind = "control", text = "Switches of one bus after which it counts as oscillating. With freezing on, a converged run that reaches it ends as max_switching_exceeded. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Narrow Q range (pu)", url = "/help/power_flow.qlimits.guard.min_q_range_pu", kind = "control", text = "A machine whose Q range (Qmax minus Qmin) lies below this counts as narrow and follows the narrow-range rule. Needs the guard. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Narrow-range rule", url = "/help/power_flow.qlimits.guard.narrow_range_mode", kind = "control", text = "lock_pq keeps a narrow-range machine PV inside its band and clamps it at the first limit it reaches; prefer_pq runs it as PQ at the band middle from the start. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Violation rule", url = "/help/power_flow.qlimits.guard.violation_mode", kind = "control", text = "lock_pq switches a machine once Q exceeds its limit by the violation threshold; delayed_switch waits until Q exceeds the limit by the hysteresis. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Violation threshold (pu)", url = "/help/power_flow.qlimits.guard.violation_threshold_pu", kind = "control", text = "Q overshoot beyond the limit from which the lock_pq violation rule switches a machine to PQ. Unused under delayed_switch. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Zero-range rule", url = "/help/power_flow.qlimits.guard.zero_range_mode", kind = "control", text = "A machine with Qmin equal to Qmax cannot hold a voltage; lock_pq runs it as PQ at that Q from the start. The only rule offered. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Q hysteresis (pu)", url = "/help/power_flow.qlimits.hysteresis_pu", kind = "control", text = "Q overshoot before a switch (classic modes, active_set with delayed_switch). active_set with lock_pq (default) switches at 1e-4 pu. Also the final-check margin. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Buses locked to PQ", url = "/help/power_flow.qlimits.lock_pv_to_pq_buses", kind = "control", text = "Comma-separated buses run as PQ from the start: case bus numbers for a MATPOWER file, otherwise internal positions (1 = first bus of the network). How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Release voltage margin (pu)", url = "/help/power_flow.qlimits.reenable_v_hyst_pu", kind = "control", text = "Voltage margin for releasing a clamped machine back to PV: at Qmax when Vm exceeds Vset by it, at Qmin when Vm falls below Vset by it. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "First switching iteration", url = "/help/power_flow.qlimits.start_iter", kind = "control", text = "Newton iteration from which PV to PQ switching may run. Later values let the solve settle first; the classic modes switch between solves and ignore it. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Switching start rule", url = "/help/power_flow.qlimits.start_mode", kind = "control", text = "iteration starts at the first switching iteration, auto once the Q change falls below the auto threshold, iteration_or_auto at whichever comes first. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Traced buses", url = "/help/power_flow.qlimits.trace_buses", kind = "control", text = "Comma-separated bus numbers of the case file whose switching events are written in detail to the Q-limit trace. Empty traces nothing. How the reactive-power limits of PV machines are enforced: master switch, enforcement mode, when switching starts, hysteresis and release, the final check every mode ends with, and the guard for narrow ranges and remaining violations. Algorithm: Q-limits and Q-limit Switching Strategy. In the Web UI these keys form the Q-limit block of the power-flow form (Form options)."),
  (title = "Rescue ladder for failed AC solves", url = "/help/power_flow.rescue", kind = "control", text = "After a non-converged AC solve, retry from the original start through a fixed ladder: alternate start, autodamp, DC seed, settled Q-limits. First success wins. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Solver", url = "/help/power_flow.solver", kind = "control", text = "Selects the executing solver: AC Newton-Raphson, the APSLF power series (needs AnalyticLoadFlow.jl), or a DC linear model without voltages and reactive results. power_flow.solver selects the executing solver; power_flow.method fixes the AC formulation ( rectangular ). apslf routes the run through the external-solver bridge ( buildPfModel , solvePf(ApslfSolver(...)) , applyPfSolution! ) to AnalyticLoadFlow.jl's analytic power-series solver, a required dependency; see External Solvers."),
  (title = "Accept only if improved", url = "/help/power_flow.start_current_iteration.accept_only_if_improved", kind = "control", text = "Accept the pre-solve candidate only when it improves the mismatch; otherwise the original start values are restored. Keep it on outside expert experiments."),
  (title = "Current-iteration damping", url = "/help/power_flow.start_current_iteration.damping", kind = "control", text = "Damping factor of the pre-solve voltage update; 1.0 applies the full update. Lower it if the candidate is rejected by the voltage or angle guards."),
  (title = "Enable current-iteration pre-solve", url = "/help/power_flow.start_current_iteration.enabled", kind = "control", text = "Guarded current-iteration pre-solve improving the start profile before Newton-Raphson; the result is kept only if it passes the guards and lowers the mismatch."),
  (title = "Maximum angle-step guard [deg]", url = "/help/power_flow.start_current_iteration.max_angle_step_deg", kind = "control", text = "Largest allowed angle change of one pre-solve update; a larger jump rejects the candidate. Lower it for a more conservative pre-solve."),
  (title = "Current-iteration max iterations", url = "/help/power_flow.start_current_iteration.max_iter", kind = "control", text = "Maximum number of pre-solve steps before Newton-Raphson starts. Keep it small; raise it only when the mismatch keeps improving but the pre-solve stops early."),
  (title = "Minimum improvement factor", url = "/help/power_flow.start_current_iteration.min_improvement_factor", kind = "control", text = "Required improvement ratio of the candidate mismatch; 0.98 means at least about 2 percent better. Smaller values demand a stronger improvement."),
  (title = "Only for large cases", url = "/help/power_flow.start_current_iteration.only_for_large_cases", kind = "control", text = "Run the pre-solve only for cases classified as large. Small cases keep their normal start values."),
  (title = "Current-iteration tolerance", url = "/help/power_flow.start_current_iteration.tol", kind = "control", text = "Stopping tolerance of the pre-solve, not the final Newton-Raphson tolerance. A loose value is enough; the goal is a better start, not a solved power flow."),
  (title = "Maximum voltage guard [pu]", url = "/help/power_flow.start_current_iteration.vm_max_pu", kind = "control", text = "Upper voltage guard: a candidate with any bus voltage above it is rejected and the original start values are restored."),
  (title = "Minimum voltage guard [pu]", url = "/help/power_flow.start_current_iteration.vm_min_pu", kind = "control", text = "Lower voltage guard: a candidate with any bus voltage below it is rejected and the original start values are restored."),
  (title = "Start angle mode", url = "/help/power_flow.start_mode.angle_mode", kind = "control", text = "Source of the start angles: classic zero angles, a DC pre-pass (default), or the imported angles. Ignored while the flat start is on. Where the Newton-Raphson iteration starts: the angle and voltage modes, the profile a start is taken from, and the start projection with its DC, blend and ratio-profile candidates. A flat start ( power_flow.flatstart ) switches the projection, the DC seed and the two modes off for the run; only the three-winding star points start at a ratio. Mechanism: Solver Guide; recipes per case: Start strategies."),
  (title = "DC start values", url = "/help/power_flow.start_mode.dc_seed_unconditional", kind = "control", text = "Always run a full DC power flow first and seed the Newton-Raphson start angles from it, bypassing the start angle mode and its quality gate. Where the Newton-Raphson iteration starts: the angle and voltage modes, the profile a start is taken from, and the start projection with its DC, blend and ratio-profile candidates. A flat start ( power_flow.flatstart ) switches the projection, the DC seed and the two modes off for the run; only the three-winding star points start at a ratio. Mechanism: Solver Guide; recipes per case: Start strategies."),
  (title = "Ratio profile as a start candidate", url = "/help/power_flow.start_mode.ratio_profile", kind = "control", text = "PQ buses scaled by the transformer ratios as a start candidate. Off under a flat start; otherwise used only by the rescue alternate start and the auto mode. Where the Newton-Raphson iteration starts: the angle and voltage modes, the profile a start is taken from, and the start projection with its DC, blend and ratio-profile candidates. A flat start ( power_flow.flatstart ) switches the projection, the DC seed and the two modes off for the run; only the three-winding star points start at a ratio. Mechanism: Solver Guide; recipes per case: Start strategies."),
  (title = "Flat start turned behind phase shifters", url = "/help/power_flow.start_mode.rotate_behind_pst", kind = "control", text = "Flat start: a bus reached only across phase shifters starts at the slack angle plus their shifts; a bus a path without shifter reaches keeps the slack angle. Where the Newton-Raphson iteration starts: the angle and voltage modes, the profile a start is taken from, and the start projection with its DC, blend and ratio-profile candidates. A flat start ( power_flow.flatstart ) switches the projection, the DC seed and the two modes off for the run; only the three-winding star points start at a ratio. Mechanism: Solver Guide; recipes per case: Start strategies."),
  (title = "Start voltage mode", url = "/help/power_flow.start_mode.voltage_mode", kind = "control", text = "Source of the start voltage magnitudes: classic flat, generator or bus setpoints, or a blend of the imported profile. Ignored while the flat start is on. Where the Newton-Raphson iteration starts: the angle and voltage modes, the profile a start is taken from, and the start projection with its DC, blend and ratio-profile candidates. A flat start ( power_flow.flatstart ) switches the projection, the DC seed and the two modes off for the run; only the three-winding star points start at a ratio. Mechanism: Solver Guide; recipes per case: Start strategies."),
  (title = "PowerFlow tolerance", url = "/help/power_flow.tol", kind = "control", text = "Convergence bound for the largest single bus mismatch, active and reactive alike. 1e-8 pu equals 1 W at a 100 MVA base. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "PowerFlow tolerance in MW", url = "/help/power_flow.tol_MW", kind = "control", text = "Unit of the tolerance value. MW states the bound physically, converted with the case base at run time (1 MW at 100 MVA is 1e-2 pu); pu is the classic form. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Enable trust-region step control", url = "/help/power_flow.trust_region.enabled", kind = "control", text = "Scaled-Newton trust-region step control as an alternative to autodamping; enabling one disables the other. Suited to difficult flat-start cases. power_flow.trust_region is a scaled-Newton trust region, an alternative to power_flow.autodamp : it caps the Newton step norm at an adaptive radius and accepts or rejects trials by merit decrease. Off by default; requires power_flow.autodamp = false (both control the step length, enabling both is a configuration error). Theory and the dogleg mode: Trust-Region Step Control."),
  (title = "Trust-region acceptance ratio (eta)", url = "/help/power_flow.trust_region.eta_accept", kind = "control", text = "Minimum actual-to-predicted reduction ratio to accept a trial step. Higher values reject more trials and add shrink-and-retry iterations. power_flow.trust_region is a scaled-Newton trust region, an alternative to power_flow.autodamp : it caps the Newton step norm at an adaptive radius and accepts or rejects trials by merit decrease. Off by default; requires power_flow.autodamp = false (both control the step length, enabling both is a configuration error). Theory and the dogleg mode: Trust-Region Step Control."),
  (title = "Initial trust-region radius", url = "/help/power_flow.trust_region.initial_radius", kind = "control", text = "Starting trust-region radius in per-unit state-vector norm. Larger values risk more rejected or shrunk first steps on hard cases. power_flow.trust_region is a scaled-Newton trust region, an alternative to power_flow.autodamp : it caps the Newton step norm at an adaptive radius and accepts or rejects trials by merit decrease. Off by default; requires power_flow.autodamp = false (both control the step length, enabling both is a configuration error). Theory and the dogleg mode: Trust-Region Step Control."),
  (title = "Trust-region step mode", url = "/help/power_flow.trust_region.step_mode", kind = "control", text = "Trial-step construction: scaled rescales the full Newton direction to the radius; dogleg blends it with a steepest-descent step when the radius shrinks. power_flow.trust_region is a scaled-Newton trust region, an alternative to power_flow.autodamp : it caps the Newton step norm at an adaptive radius and accepts or rejects trials by merit decrease. Off by default; requires power_flow.autodamp = false (both control the step length, enabling both is a configuration error). Theory and the dogleg mode: Trust-Region Step Control."),
  (title = "Wrong-branch detection", url = "/help/power_flow.wrong_branch_detection", kind = "control", text = "Plausibility check of the converged solution on the highest voltage level: warn reports a suspicious result, fail treats it as non-converged, off skips it. power_flow.wrong_branch_detection is a heuristic plausibility check of every numerically converged AC result, with or without reactive limits; it proves nothing about the solution branch."),
  (title = "System base MVA (PowSyBl)", url = "/help/powsybl_import.base_mva", kind = "control", text = "Per-unit base of the built network; PowSyBl files carry no base, 100 MVA is the default. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "HVDC converters (PowSyBl)", url = "/help/powsybl_import.hvdc_mode", kind = "control", text = "HVDC converter model of a PowSyBl network: fixed injections reproduce the OpenLoadFlow snapshot; a paired controller is not implemented yet. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "One slack per synchronous component", url = "/help/powsybl_import.multi_slack", kind = "control", text = "Every synchronous component gets its own slack generator, the regulating unit with the largest max_p; unchecked, only the first component has a reference. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "Remote voltage regulation (PowSyBl)", url = "/help/powsybl_import.remote_regulation", kind = "control", text = "Generator regulating another bus: hold_local keeps it PV at its own bus, pq fixes P and Q, remote controls the regulated bus in the outer loop. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "Slack generator ids (PowSyBl)", url = "/help/powsybl_import.slack_ids", kind = "control", text = "Generator ids that become the slack of their component, separated by semicolons; empty lets the largest max_p decide. The powsybl_import scope (canonical section powsybl , alias powsybl_import ), see Configuration:"),
  (title = "Parallel execution of independent work items", url = "/help/runtime.parallel.enabled", kind = "control", text = "Use Julia threads for independent work items: island solves, short-circuit sweeps, contingency batches. Off forces every site onto the serial path. Process-level settings read once at startup: the thread report, the Julia and BLAS thread counts, and the parallel work split of the sweeps."),
  (title = "SE flat start", url = "/help/state_estimation.flatstart", kind = "control", text = "Start the estimator from a flat voltage profile instead of the model's current state. Uncheck when a trusted start state exists. The estimator reads every setting from the active configuration: runse!(net) , runse_diagnostics , validate_measurements and validate_topology take no settings. with_state_estimation_config(max_iter = 12) do runse!(net) end installs other values for one call and restores the previous configuration afterwards. The service and the Web UI install the effective configuration of the case (general file, case file, form values) the same way."),
  (title = "Elimination limit (normalized residual)", url = "/help/state_estimation.k_eliminate", kind = "control", text = "Normalized residual from which a measurement is removed from the estimate, not just down-weighted. Applies while the band test is high, within the budget. Both limits work on the normalized residual r_n,i = r_i / √Ω_ii, computed with the original sigmas; only the staged knees robust_k1 / robust_k2 stay on the raw ratio |r_i|/σ_i. Down-weighting and elimination read the same quantity, so their limits are directly comparable. Rule of thumb: suppression for online smoothing, elimination for identification."),
  (title = "SE maximum iterations", url = "/help/state_estimation.max_iter", kind = "control", text = "Iteration cap of the estimator, the same limit the service and the configuration use. A solve with released transformer taps can need close to 40 iterations. The estimator reads every setting from the active configuration: runse!(net) , runse_diagnostics , validate_measurements and validate_topology take no settings. with_state_estimation_config(max_iter = 12) do runse!(net) end installs other values for one call and restores the previous configuration afterwards. The service and the Web UI install the effective configuration of the case (general file, case file, form values) the same way."),
  (title = "Residual-correlation (K-matrix) report", url = "/help/state_estimation.report_residual_correlation", kind = "control", text = "Add residual-correlation columns to the bad-data report: rows correlated above 0.707 form a group where a gross error cannot be told apart. Reporting only. With the correlation report on, each ranking row carries the maximum"),
  (title = "Robust R modification", url = "/help/state_estimation.robust", kind = "control", text = "Deprecated alias for the down-weighting mode staged, read only while that mode is off. Set the down-weighting mode instead, never both. Both limits work on the normalized residual r_n,i = r_i / √Ω_ii, computed with the original sigmas; only the staged knees robust_k1 / robust_k2 stay on the raw ratio |r_i|/σ_i. Down-weighting and elimination read the same quantity, so their limits are directly comparable. Rule of thumb: suppression for online smoothing, elimination for identification."),
  (title = "Down-weighting (off / staged / replacement)", url = "/help/state_estimation.robust_mode", kind = "control", text = "Treatment of a large residual: off is plain WLS, staged down-weights the row gradually between two knees, replacement gives it a fixed large sigma. Both limits work on the normalized residual r_n,i = r_i / √Ω_ii, computed with the original sigmas; only the staged knees robust_k1 / robust_k2 stay on the raw ratio |r_i|/σ_i. Down-weighting and elimination read the same quantity, so their limits are directly comparable. Rule of thumb: suppression for online smoothing, elimination for identification."),
  (title = "Measurement sigma by voltage level", url = "/help/state_estimation.sigma_by_voltage_level", kind = "control", text = "Sigma per level in MW, MVAr, A and kV for rows without their own sigma; an empty cell keeps the default. Saved into the case configuration. measurementStdDevs gives one sigma per measurement type for the whole network. Instrument transformers and metering differ between voltage levels, so state_estimation.sigma_by_voltage_level sets the sigmas per level and measurement type in physical units. One row per level, keyed by the nominal voltage of the level in kV as in the network (bus Vn , matched to 1e-6 kV). The columns of a row:"),
  (title = "SE flat start turned behind phase shifters", url = "/help/state_estimation.start_mode.rotate_behind_pst", kind = "control", text = "SE flat start: a bus reached only across phase shifters starts at their shift sum, as in the power flow flat start. Off (default): every angle at 0. The estimator reads every setting from the active configuration: runse!(net) , runse_diagnostics , validate_measurements and validate_topology take no settings. with_state_estimation_config(max_iter = 12) do runse!(net) end installs other values for one call and restores the previous configuration afterwards. The service and the Web UI install the effective configuration of the case (general file, case file, form values) the same way."),
  (title = "Down-weight limit and replacement sigma", url = "/help/state_estimation.suppression", kind = "control", text = "Replacement mode: from this normalized residual a row is solved with the replacement sigma and loses its influence, but is not removed. Sigma in the row's unit. Both limits work on the normalized residual r_n,i = r_i / √Ω_ii, computed with the original sigmas; only the staged knees robust_k1 / robust_k2 stay on the raw ratio |r_i|/σ_i. Down-weighting and elimination read the same quantity, so their limits are directly comparable. Rule of thumb: suppression for online smoothing, elimination for identification."),
  (title = "Tap estimation per transformer", url = "/help/state_estimation.tap_estimation.exclude", kind = "control", text = "Unchecked transformers keep their transferred step (reason excluded). Machine transformers are unchecked by default; their step is calculated if Q is measured. Every single transformer can be kept out of the tap estimation. state_estimation.tap_estimation.exclude lists transformers by name or CGMES mRID. Such a transformer keeps its transferred step, its rows say status = not_estimated , reason = excluded , and its step is not calculated either. An entry that names no transformer of the net gives a warning naming it ( runse! , runse_diagnostics ; the SE service writes it to run.log) and has no effect."),
  (title = "Tap fallback", url = "/help/state_estimation.tap_estimation.fallback", kind = "control", text = "Without convergence, or a worse fit than the transferred steps (worse_fit), a run without tap estimation is the result. Off: the first run is shown as it is. state_estimation.tap_estimation.enabled (default true , Web UI \"estimate taps\") switches the tap estimation. Off, no changer becomes a state, even one released with setTapEstimation! : every changer keeps its transferred step (SSH profile or measurement file), and each row of tapEstimates and se_tap_estimates.csv says status = not_estimated , reason = disabled . The rows carry status ( estimated , out_of_range for an estimate too far outside the band, not_estimated , calculated for a machine transformer) and reason for every changer."),
  (title = "Tap impedance per step", url = "/help/state_estimation.tap_estimation.impedance_correction", kind = "control", text = "Tap tables and curves always follow the step. auto adds the analytic correction of typed models under tap_changer_model impedance_correction, off does not. A tap position that disagrees with the model (a stale SCADA position, a local operation) poisons the estimate around the transformer: the band test reports :high and the suspects cluster there although every telemetry row is healthy. Releasing the tap changers as estimation states resolves this. The estimator solves with one continuous step per tap changer, rounds each to the nearest physical step, and solves once more with the steps fixed; the reported result is that of the fixed run."),
  (title = "Estimate machine transformers", url = "/help/state_estimation.tap_estimation.include_machine_transformers", kind = "control", text = "Off (default): not estimated; the step is calculated after the run when Q is measured on every bus of the machine node, else it stays. On: estimated. Every single transformer can be kept out of the tap estimation. state_estimation.tap_estimation.exclude lists transformers by name or CGMES mRID. Such a transformer keeps its transferred step, its rows say status = not_estimated , reason = excluded , and its step is not calculated either. An entry that names no transformer of the net gives a warning naming it ( runse! , runse_diagnostics ; the SE service writes it to run.log) and has no effect."),
  (title = "SE convergence tolerance", url = "/help/state_estimation.tol", kind = "control", text = "WLS convergence tolerance on the state step. The default 1e-6 is the noise floor of the finite-difference Jacobian; a tighter value is raised with a log line. The estimator reads every setting from the active configuration: runse!(net) , runse_diagnostics , validate_measurements and validate_topology take no settings. with_state_estimation_config(max_iter = 12) do runse!(net) end installs other values for one call and restores the previous configuration afterwards. The service and the Web UI install the effective configuration of the case (general file, case file, form values) the same way."),
  (title = "Write estimated shunts back", url = "/help/state_estimation.update_shunts", kind = "control", text = "Write the estimated shunt susceptances back into the model after a converged run. Off keeps the model data authoritative. The estimator reads every setting from the active configuration: runse!(net) , runse_diagnostics , validate_measurements and validate_topology take no settings. with_state_estimation_config(max_iter = 12) do runse!(net) end installs other values for one call and restores the previous configuration afterwards. The service and the Web UI install the effective configuration of the case (general file, case file, form values) the same way."),
  (title = "Zero injection", url = "/help/state_estimation.zero_injection", kind = "control", text = "on: passive buses get zero-injection rows weighted by zero_injection_sigma_mva; constraint: same balances as equality constraints; off: no zero-injection rows. A passive bus (no load, generation or shunt) injects nothing, and so does the fused bus of a closed coupler cluster whose members are all passive (with load or generation the fused bus carries the sum of the member injection rows as a weighted LINKAGG row). A busbar joined to the network by closed couplers only (no branch of its own, typed Isolated by the import) is a member of its cluster and gets its zero-injection rows like any passive bus; without them the cluster would have no balance. With state_estimation.zero_injection = on (default, weighted) each balance is a pseudo-measurement with sigma state_estimation.zero_injection_sigma_mva in MVA (default 0.001 MVA, 1 kW). It counts in J and in the ranking, is never eliminated and leaves an injection of the order of the sigma. With constraint the balances are equality constraints c(x) = 0, solved in an extended system with Lagrange multipliers λ (KKT). The balance then holds exactly, and the rows leave J while the degrees of freedom stay m - n:"),
  (title = "Zero-injection sigma", url = "/help/state_estimation.zero_injection_sigma_mva", kind = "control", text = "Sigma of one zero-injection row in MVA (MW, Mvar) when the rows are weighted (zero_injection on). Smaller binds the balance harder and worsens the conditioning. A passive bus (no load, generation or shunt) injects nothing, and so does the fused bus of a closed coupler cluster whose members are all passive (with load or generation the fused bus carries the sum of the member injection rows as a weighted LINKAGG row). A busbar joined to the network by closed couplers only (no branch of its own, typed Isolated by the import) is a member of its cluster and gets its zero-injection rows like any passive bus; without them the cluster would have no balance. With state_estimation.zero_injection = on (default, weighted) each balance is a pseudo-measurement with sigma state_estimation.zero_injection_sigma_mva in MVA (default 0.001 MVA, 1 kW). It counts in J and in the ranking, is never eliminated and leaves an injection of the order of the sigma. With constraint the balances are equality constraints c(x) = 0, solved in an extended system with Lagrange multipliers λ (KKT). The balance then holds exactly, and the rows leave J while the degrees of freedom stay m - n:"),
  (title = "Case input format", url = "/help/webui.case_format", kind = "control", text = "Auto tells MATPOWER, CGMES, SCF/PGM JSON, PowSyBl and DTF apart from the file content. Pick a format only when the file does not say what it is. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ), tolerance (decimals or scientific notation such as 1e-8 ; the spinner steps the exponent and keeps the mantissa), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector, which also offers off ; PV/PQ switching holds the hysteresis, the final check bound ( final_q_accept_pu , auto or a value in pu), the classic pass limit ( classic_max_passes ), the first switching iteration ( start_iter ), the switch cap per bus ( guard.max_switches ), freezing after repeated switching and the guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits (Q-limit options and guard). Per-unit values take scientific notation, bus lists comma-separated case bus numbers. Controls a mode does not read are grayed: everything while the handling is off, the start iteration and the guard rules in the classic modes, the range rules without the guard; - Solver : one radio group power_flow_solver with rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model) (solver selection, DC power flow); - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve); - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; - Non-convergence handling (Advanced): power_flow.rescue , power_flow.auto_slack and power_flow.dc.fallback (Power-Flow Configuration); - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - Network model (Case page, every format): the system frequency, 50 or 60 Hz ( model.nominal_frequency_hz ). The field is editable only for an SCF or PGM case (or the base case of a time series) without f_nom and with a line c1 in farad. A file that states f_nom greys it at that value, because the file wins over the key. A case without capacitance in farad greys it as \"not used\": MATPOWER, DTF, CGMES and PowSyBl give line charging as susceptance, and an SCF file in pu or with c1 = 0 has none (System frequency). For a greyed field the save stores no value and removes one stored before; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, and each run writes effective_config.yaml . A ? next to a control opens its help page: the hint, the matching section of this documentation as shipped with the running version, and a link to the published site ( webui.docs_base_url points it at a local build or a pinned version). Back keeps the entered values. A field that does not apply to the selected solver or step control is grayed in place, disabled and not submitted."),
  (title = "MATPOWER case file", url = "/help/webui.casefile", kind = "control", text = "Choose a case from the list, or type a bare case name or a local path and press Enter to download or copy it into the case directory. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ), tolerance (decimals or scientific notation such as 1e-8 ; the spinner steps the exponent and keeps the mantissa), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector, which also offers off ; PV/PQ switching holds the hysteresis, the final check bound ( final_q_accept_pu , auto or a value in pu), the classic pass limit ( classic_max_passes ), the first switching iteration ( start_iter ), the switch cap per bus ( guard.max_switches ), freezing after repeated switching and the guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits (Q-limit options and guard). Per-unit values take scientific notation, bus lists comma-separated case bus numbers. Controls a mode does not read are grayed: everything while the handling is off, the start iteration and the guard rules in the classic modes, the range rules without the guard; - Solver : one radio group power_flow_solver with rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model) (solver selection, DC power flow); - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve); - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; - Non-convergence handling (Advanced): power_flow.rescue , power_flow.auto_slack and power_flow.dc.fallback (Power-Flow Configuration); - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - Network model (Case page, every format): the system frequency, 50 or 60 Hz ( model.nominal_frequency_hz ). The field is editable only for an SCF or PGM case (or the base case of a time series) without f_nom and with a line c1 in farad. A file that states f_nom greys it at that value, because the file wins over the key. A case without capacitance in farad greys it as \"not used\": MATPOWER, DTF, CGMES and PowSyBl give line charging as susceptance, and an SCF file in pu or with c1 = 0 has none (System frequency). For a greyed field the save stores no value and removes one stored before; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, and each run writes effective_config.yaml . A ? next to a control opens its help page: the hint, the matching section of this documentation as shipped with the running version, and a link to the published site ( webui.docs_base_url points it at a local build or a pinned version). Back keeps the entered values. A field that does not apply to the selected solver or step control is grayed in place, disabled and not submitted."),
  (title = "Configuration template file", url = "/help/webui.config_file", kind = "control", text = "Configuration YAML the run starts from. Form values become per-run overrides on top of it; the file itself stays unchanged. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ), tolerance (decimals or scientific notation such as 1e-8 ; the spinner steps the exponent and keeps the mantissa), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector, which also offers off ; PV/PQ switching holds the hysteresis, the final check bound ( final_q_accept_pu , auto or a value in pu), the classic pass limit ( classic_max_passes ), the first switching iteration ( start_iter ), the switch cap per bus ( guard.max_switches ), freezing after repeated switching and the guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits (Q-limit options and guard). Per-unit values take scientific notation, bus lists comma-separated case bus numbers. Controls a mode does not read are grayed: everything while the handling is off, the start iteration and the guard rules in the classic modes, the range rules without the guard; - Solver : one radio group power_flow_solver with rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model) (solver selection, DC power flow); - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve); - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; - Non-convergence handling (Advanced): power_flow.rescue , power_flow.auto_slack and power_flow.dc.fallback (Power-Flow Configuration); - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - Network model (Case page, every format): the system frequency, 50 or 60 Hz ( model.nominal_frequency_hz ). The field is editable only for an SCF or PGM case (or the base case of a time series) without f_nom and with a line c1 in farad. A file that states f_nom greys it at that value, because the file wins over the key. A case without capacitance in farad greys it as \"not used\": MATPOWER, DTF, CGMES and PowSyBl give line charging as susceptance, and an SCF file in pu or with c1 = 0 has none (System frequency). For a greyed field the save stores no value and removes one stored before; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, and each run writes effective_config.yaml . A ? next to a control opens its help page: the hint, the matching section of this documentation as shipped with the running version, and a link to the published site ( webui.docs_base_url points it at a local build or a pinned version). Back keeps the entered values. A field that does not apply to the selected solver or step control is grayed in place, disabled and not submitted."),
  (title = "Configuration maintenance", url = "/help/webui.config_maintenance", kind = "control", text = "Check compares the YAML with the template and previews the refresh without writing; Refresh adds missing keys after a backup; the Editor edits the file. Check configuration and Refresh configuration bring a local file up to a template that gained options. Check is a dry run against src/config/configuration.yaml.example (missing keys, deprecated aliases, duplicate YAML keys, a preview of the refreshed YAML), nothing written. Refresh keeps existing values, adds missing keys with template defaults and may normalize deprecated aliases; it never runs at startup, writes a timestamped backup first, refuses on duplicate keys, and offers uploaded or pasted YAML as a download instead of rewriting it. The Configuration Editor opens the active YAML in a textarea, validates it with the same parser and duplicate-key checks, writes only after validation with a timestamped backup, and warns when a case configuration file still overrides the global YAML. After a save the server reloads the file. The search box above the text finds plain text ( Next / Previous , Enter / Shift+Enter) or jumps to a dotted key such as power_flow.qlimits.guard.enabled . Form values override the YAML configuration; the order is described in Configuration. Each run writes effective_config.yaml . Ignore Web UI settings and use configuration defaults runs with the YAML values only. model.auto_profile: apply may still adjust MATPOWER import conventions after form and API values are assembled; effective_config.yaml records that. Help in the header opens the help (Web UI) inside the Web UI, as shipped with the running version; Project Docs opens the published documentation ( webui.docs_base_url ). The help pages behind the ? icons carry a section of the help or of this reference in full, or the lead paragraph of a library section with the link to it. Search the help The search field stands at the top of the help, of this reference and in the header of every page and looks through the help, the reference and the help pages of the controls. Every word entered must occur (a part of a word is enough, case does not matter); hits appear while you type, hits in a heading first, each with a marked line of text. / focuses the field, Enter opens the first hit, Esc closes the list. Without a hit the page links to the published documentation. The index ships with the application; with scripts switched off the field is a plain form."),
  (title = "Bus/branch CSV files", url = "/help/webui.detailed_result_csv", kind = "control", text = "Write bus_voltages_complex.csv and branch_flows.csv with per-bus voltages and per-branch flows. Off by default because large networks produce large files. - Logfile output mode : classic writes the result report plus a compact timing and status summary ( solver_time , representative_time , iterations, final mismatch, outcome); full adds Full run details with the effective typed configuration, artifact choices and status diagnostics. MATPOWER .m runs also print the import-option and auto-profile tables; DTF .DAT runs never do. - Performance timing ( off , compact , full ) writes performance.log with the phases of one request (from request parsing to artifact writing, solver and total time; full adds internal profile entries). A run from the Web UI solves once; repeated timing is the benchmark mode of run_matpower_case in a script (Performance Profiling). - Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP) writes the case as one re-importable delivery into the run's artifacts, for every case format and also on non-converged runs; see CGMES Export. - Write bus/branch CSV files (API default off, because large networks produce large files) writes bus_voltages_complex.csv and branch_flows.csv from the ACPFlowReport rows; columns on Local PowerFlow Service. - CSV format is the machine-scope key output.csv_format ( Save settings writes it to the configuration file, a per-case save leaves it out) and applies to every CSV of every run type; auto (the default) follows the regional settings of the machine. Values and delimiters: Configuration. Excel may still auto-convert identifiers like 1E5 ; use Data From Text/CSV with text types when that matters."),
  (title = "CSV format (every CSV file of a run)", url = "/help/webui.detailed_result_csv_format", kind = "control", text = "Delimiter and decimal separator of every CSV a run writes: auto (default, regional settings), technical, excel_de or excel_us. A machine-wide setting. - Logfile output mode : classic writes the result report plus a compact timing and status summary ( solver_time , representative_time , iterations, final mismatch, outcome); full adds Full run details with the effective typed configuration, artifact choices and status diagnostics. MATPOWER .m runs also print the import-option and auto-profile tables; DTF .DAT runs never do. - Performance timing ( off , compact , full ) writes performance.log with the phases of one request (from request parsing to artifact writing, solver and total time; full adds internal profile entries). A run from the Web UI solves once; repeated timing is the benchmark mode of run_matpower_case in a script (Performance Profiling). - Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP) writes the case as one re-importable delivery into the run's artifacts, for every case format and also on non-converged runs; see CGMES Export. - Write bus/branch CSV files (API default off, because large networks produce large files) writes bus_voltages_complex.csv and branch_flows.csv from the ACPFlowReport rows; columns on Local PowerFlow Service. - CSV format is the machine-scope key output.csv_format ( Save settings writes it to the configuration file, a per-case save leaves it out) and applies to every CSV of every run type; auto (the default) follows the regional settings of the machine. Values and delimiters: Configuration. Excel may still auto-convert identifiers like 1E5 ; use Data From Text/CSV with text types when that matters."),
  (title = "Selected DTF outage labels/indices", url = "/help/webui.dtf_outage_selection", kind = "control", text = "One outage label or index of the DTF case, used with the run mode selected. The result page shows a compact outage summary; the rows stay in the artifacts. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ), tolerance (decimals or scientific notation such as 1e-8 ; the spinner steps the exponent and keeps the mantissa), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector, which also offers off ; PV/PQ switching holds the hysteresis, the final check bound ( final_q_accept_pu , auto or a value in pu), the classic pass limit ( classic_max_passes ), the first switching iteration ( start_iter ), the switch cap per bus ( guard.max_switches ), freezing after repeated switching and the guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits (Q-limit options and guard). Per-unit values take scientific notation, bus lists comma-separated case bus numbers. Controls a mode does not read are grayed: everything while the handling is off, the start iteration and the guard rules in the classic modes, the range rules without the guard; - Solver : one radio group power_flow_solver with rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model) (solver selection, DC power flow); - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve); - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; - Non-convergence handling (Advanced): power_flow.rescue , power_flow.auto_slack and power_flow.dc.fallback (Power-Flow Configuration); - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - Network model (Case page, every format): the system frequency, 50 or 60 Hz ( model.nominal_frequency_hz ). The field is editable only for an SCF or PGM case (or the base case of a time series) without f_nom and with a line c1 in farad. A file that states f_nom greys it at that value, because the file wins over the key. A case without capacitance in farad greys it as \"not used\": MATPOWER, DTF, CGMES and PowSyBl give line charging as susceptance, and an SCF file in pu or with c1 = 0 has none (System frequency). For a greyed field the save stores no value and removes one stored before; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, and each run writes effective_config.yaml . A ? next to a control opens its help page: the hint, the matching section of this documentation as shipped with the running version, and a link to the published site ( webui.docs_base_url points it at a local build or a pinned version). Back keeps the entered values. A field that does not apply to the selected solver or step control is grayed in place, disabled and not submitted."),
  (title = "CGMES export artifact", url = "/help/webui.export_cgmes", kind = "control", text = "Write the case as one re-importable CGMES delivery (EQ, TP, SSH, SV in a ZIP) into the run's artifacts, for every case format and also on non-converged runs. The run option Write MATPOWER export artifact works the same way for every case format: the network of the run is written as a new file <case _calc_<YYYYMMDD .m next to the other artifacts, with a header that names the source case, the write time, the Sparlectra version and whether the bus and branch columns carry the calculated state. The input file is never written."),
  (title = "Optional FOR002 reference file", url = "/help/webui.for002_reference_file", kind = "control", text = "Optional FOR002 file for the legacy reference comparison of a DTF run: absolute path, path in the case cache, or an offered candidate. Not a primary case. The settings and run forms offer: - case name or local path, configuration template file, the read-only output root (set only through start_sparlectra_webui(; output_root) ), tolerance (decimals or scientific notation such as 1e-8 ; the spinner steps the exponent and keeps the mantissa), maximum iterations, autodamping with its minimum factor; - Q-limit handling : the power_flow.qlimits.enabled checkbox and the enforcement-mode selector, which also offers off ; PV/PQ switching holds the hysteresis, the final check bound ( final_q_accept_pu , auto or a value in pu), the classic pass limit ( classic_max_passes ), the first switching iteration ( start_iter ), the switch cap per bus ( guard.max_switches ), freezing after repeated switching and the guard switch ( guard.enabled ); Advanced holds the rest of power_flow.qlimits (Q-limit options and guard). Per-unit values take scientific notation, bus lists comma-separated case bus numbers. Controls a mode does not read are grayed: everything while the handling is off, the start iteration and the guard rules in the classic modes, the range rules without the guard; - Solver : one radio group power_flow_solver with rectangular (AC Newton-Raphson), apslf (AnalyticLoadFlow) and dc (linear screening model) (solver selection, DC power flow); - wrong-branch detection mode, start angle and voltage modes; - Advanced start values : the current-iteration pre-solve fields ( power_flow.start_current_iteration. , guarded pre-solve); - Merit-function line search : power_flow.merit.enabled , power_flow.merit.armijo_c1 , power_flow.merit.fallback_max_mismatch (options), requires power_flow.autodamp = true ; - Non-convergence handling (Advanced): power_flow.rescue , power_flow.auto_slack and power_flow.dc.fallback (Power-Flow Configuration); - MATPOWER import conventions: auto-profile mode ( off , recommend , apply ) plus transformer ratio, phase shift, bus shunt, PV voltage source and comparison reference; - Network model (Case page, every format): the system frequency, 50 or 60 Hz ( model.nominal_frequency_hz ). The field is editable only for an SCF or PGM case (or the base case of a time series) without f_nom and with a line c1 in farad. A file that states f_nom greys it at that value, because the file wins over the key. A case without capacitance in farad greys it as \"not used\": MATPOWER, DTF, CGMES and PowSyBl give line charging as susceptance, and an SCF file in pu or with c1 = 0 has none (System frequency). For a greyed field the save stores no value and removes one stored before; - logfile output mode, performance timing and post-run diagnostics. Only keys in GUI_EDITABLE_CONFIG_KEYS are submitted, and each run writes effective_config.yaml . A ? next to a control opens its help page: the hint, the matching section of this documentation as shipped with the running version, and a link to the published site ( webui.docs_base_url points it at a local build or a pinned version). Back keeps the entered values. A field that does not apply to the selected solver or step control is grayed in place, disabled and not submitted."),
  (title = "Ignore Web UI settings and use configuration defaults", url = "/help/webui.ignore_webui_settings", kind = "control", text = "Run with the configuration file's values only: the form values and the saved case settings are ignored for this run. Check configuration and Refresh configuration bring a local file up to a template that gained options. Check is a dry run against src/config/configuration.yaml.example (missing keys, deprecated aliases, duplicate YAML keys, a preview of the refreshed YAML), nothing written. Refresh keeps existing values, adds missing keys with template defaults and may normalize deprecated aliases; it never runs at startup, writes a timestamped backup first, refuses on duplicate keys, and offers uploaded or pasted YAML as a download instead of rewriting it. The Configuration Editor opens the active YAML in a textarea, validates it with the same parser and duplicate-key checks, writes only after validation with a timestamped backup, and warns when a case configuration file still overrides the global YAML. After a save the server reloads the file. The search box above the text finds plain text ( Next / Previous , Enter / Shift+Enter) or jumps to a dotted key such as power_flow.qlimits.guard.enabled . Form values override the YAML configuration; the order is described in Configuration. Each run writes effective_config.yaml . Ignore Web UI settings and use configuration defaults runs with the YAML values only. model.auto_profile: apply may still adjust MATPOWER import conventions after form and API values are assembled; effective_config.yaml records that. Help in the header opens the help (Web UI) inside the Web UI, as shipped with the running version; Project Docs opens the published documentation ( webui.docs_base_url ). The help pages behind the ? icons carry a section of the help or of this reference in full, or the lead paragraph of a library section with the link to it. Search the help The search field stands at the top of the help, of this reference and in the header of every page and looks through the help, the reference and the help pages of the controls. Every word entered must occur (a part of a word is enough, case does not matter); hits appear while you type, hits in a heading first, each with a marked line of text. / focuses the field, Enter opens the first hit, Esc closes the list. Without a hit the page links to the published documentation. The index ships with the application; with scripts switched off the field is a plain form."),
  (title = "Import case files", url = "/help/webui.import_case_files", kind = "control", text = "Copy MATPOWER, DTF, CGMES (ZIP or profile XML), SCF/PGM JSON or PowSyBl IIDM files into the case directory. Nothing is run; no existing file is overwritten. Import case files opens the native file picker and accepts several files at once: MATPOWER .m / .M , DTF .dat / .DAT , CGMES .zip deliveries, CGMES profile files ( .xml ), PowSyBl IIDM files ( .xiidm ) and Sparlectra Case Format .json files (validated before they are stored). Several .xml files (the EQ, SSH, TP and SV profiles of one delivery) are packed into one <stem _cgmes.zip ; the set must contain the EQ profile. A CGMES ZIP may hold nested ZIPs. Importing is copy-only: no run, no parsing of .m code; files land in the case directory the form shows. Limits: 100 MiB per file, 250 MiB per request. An existing file is never overwritten ( already exists , the other files still import); names outside the case directory are refused. Enter in Case file resolves a typed value the same way: a bare case name via ensure_casefile , cgmes:<alias as below, or a full local path. Re-importing a saved set brings the .config.yaml sidecar (a case-scope file, scope: case ) along with the .scf.json and its measurement sets when all are selected together."),
  (title = "Performance timing", url = "/help/webui.performance_timing", kind = "control", text = "Write performance.log with the phases of one request (parsing, case loading, solve, artifacts); full adds internal profile entries, off writes nothing. - Logfile output mode : classic writes the result report plus a compact timing and status summary ( solver_time , representative_time , iterations, final mismatch, outcome); full adds Full run details with the effective typed configuration, artifact choices and status diagnostics. MATPOWER .m runs also print the import-option and auto-profile tables; DTF .DAT runs never do. - Performance timing ( off , compact , full ) writes performance.log with the phases of one request (from request parsing to artifact writing, solver and total time; full adds internal profile entries). A run from the Web UI solves once; repeated timing is the benchmark mode of run_matpower_case in a script (Performance Profiling). - Export case as CGMES delivery (EQ+TP+SSH+SV, ZIP) writes the case as one re-importable delivery into the run's artifacts, for every case format and also on non-converged runs; see CGMES Export. - Write bus/branch CSV files (API default off, because large networks produce large files) writes bus_voltages_complex.csv and branch_flows.csv from the ACPFlowReport rows; columns on Local PowerFlow Service. - CSV format is the machine-scope key output.csv_format ( Save settings writes it to the configuration file, a per-case save leaves it out) and applies to every CSV of every run type; auto (the default) follows the regional settings of the machine. Values and delimiters: Configuration. Excel may still auto-convert identifiers like 1E5 ; use Data From Text/CSV with text types when that matters."),
  (title = "Auto mode", url = "/help/webui.power_flow_mode", kind = "control", text = "Pick start-value, step-control and Q-limit strategy from the network, retrying with stronger strategies on non-convergence. Explicit options below always win. The options every AC run reads. The Web UI form carries the ones a run is usually tuned with; the rest is YAML only."),
  (title = "Case export (SCF / plain PGM)", url = "/help/webui.scf_export", kind = "control", text = "Write the selected case into the case directory as an SCF file (.scf.json) or as a plain power-grid-model dataset (.pgm.json) without the sparlectra block. exportSCF writes a network as one JSON file that reads back machine-exact, with its source, the intended calculations and, on request, the solved start state; the Web UI offers the same export from the Case page."),
  (title = "Generator: flows per branch", url = "/help/webui.se_generator_flow_ends", kind = "control", text = "Flows per branch: both ends writes P and Q at from and to; one end keeps one flow group per branch, preferring the end whose bus has injection telemetry. Truth state, flow placement, passive-node handling and a target number of critical measurements are configurable in the Web UI form."),
  (title = "Generator: bad data rows", url = "/help/webui.se_generator_gross_count", kind = "control", text = "How many measurement rows get the gross error; the seed decides which rows. Used only when bad data k is above 0. Corrupts seed-randomly drawn telemetry rows by k times their sigma. 0 = off; 10 gives a clearly detectable bad measurement (a stuck transducer). Bad data rows says how many rows get the gross error; the seed decides which, protected ZI rows are never drawn, and the confirmation message names every corrupted row. The diagnostics should rank exactly these rows first, the sequential elimination remove them, the robust option suppress them without removal."),
  (title = "Generator: bad data (k·sigma)", url = "/help/webui.se_generator_gross_error", kind = "control", text = "Corrupt seed-randomly drawn measurements by k times their sigma. 0 is off; 10 gives clearly detectable bad data for the elimination and robust workflow. Corrupts seed-randomly drawn telemetry rows by k times their sigma. 0 = off; 10 gives a clearly detectable bad measurement (a stuck transducer). Bad data rows says how many rows get the gross error; the seed decides which, protected ZI rows are never drawn, and the confirmation message names every corrupted row. The diagnostics should rank exactly these rows first, the sequential elimination remove them, the robust option suppress them without removal."),
  (title = "Generator: seeded noise", url = "/help/webui.se_generator_noise", kind = "control", text = "Add seeded Gaussian noise at the sigmas below. Without noise the measurements match the model exactly and J lands near 0 instead of near dof. Adds Gaussian noise at the per-quantity sigmas to every generated value. The random generator is seeded, so regenerating with the same inputs reproduces the identical file."),
  (title = "Generator: passive nodes", url = "/help/webui.se_generator_passive", kind = "control", text = "Sigma of generated passive-bus rows. Box off: balance rows Pinj = Qinj = 0 at this sigma; on: zero-injection rows at max(this, zero_injection_sigma_mva). Truth state, flow placement, passive-node handling and a target number of critical measurements are configurable in the Web UI form."),
  (title = "Generator: measurement resolution (U, P, Q, I, angle)", url = "/help/webui.se_generator_resolution", kind = "control", text = "Round generated values after noise to the step an online system delivers (U kV, P MW, Q Mvar, I A, angle deg); 0 is off. The sigma stays. Rounds each generated value after noise and bad data to the step an online system delivers. Default off ( 0 , no rounding) for every quantity; steps in U kV, P MW, Q Mvar, I A and angles in degrees (form fields gen_resolution_u_kv , gen_resolution_p_mw , gen_resolution_q_mvar , gen_resolution_i_a , gen_resolution_angle_deg ; library keyword resolution of generateMeasurementsFromPF ). The written sigma stays the configured one: the rounding is part of the measurement error (standard deviation step / sqrt(12)), so a step coarser than about sigma times sqrt(12) adds visible error. A rounded set names the steps in a resolution: comment line; zero-injection and passive balance rows are not rounded."),
  (title = "Generator: measurement sigmas (U, I, P, Q)", url = "/help/webui.se_generator_sigmas", kind = "control", text = "Measurement accuracy per quantity in percent of the measured value, like a transducer class; written into the sigma column of every row and used for the noise. Measurement accuracy per quantity in percent of the measured value (like a transducer accuracy class), written into the sigma column of every generated row and used for the noise, when enabled:"),
  (title = "Generator: tap deviation transformers", url = "/help/webui.se_generator_tap_count", kind = "control", text = "At most this many transformers get the tap deviation; the seed picks them among transformers the tap estimation can absorb. Unused when the deviation is 0. Generates the measurements from a network state whose transformers run the given number of mechanical tap steps off the model position (0 = off; whole steps only); the model file stays untouched. Transformers (max) bounds how many transformers deviate; the seed picks them from the in-service, non-machine transformers with a tap changer the estimation can release, and the message names the affected branches. The generator does not read state_estimation.tap_estimation.exclude . When the set puts a deviation on a transformer the run keeps out, run.log names it. The deviation moves one changer per transformer, the first ratio changer, else the first phase changer. A machine transformer is used only when the case has nothing else. The tap estimation keeps machine transformers out by default ( state_estimation.tap_estimation.include_machine_transformers = false ) and calculates their step after the estimate, so a deviation there stays in the estimate as a model error ( J far above dof ). run.log warns in that case and names the key."),
  (title = "Generator: tap deviation", url = "/help/webui.se_generator_tap_error", kind = "control", text = "Generate from a state whose seed-selected transformers run this many mechanical tap steps off the model position; 0 is off. Needs truth state fresh solve. Generates the measurements from a network state whose transformers run the given number of mechanical tap steps off the model position (0 = off; whole steps only); the model file stays untouched. Transformers (max) bounds how many transformers deviate; the seed picks them from the in-service, non-machine transformers with a tap changer the estimation can release, and the message names the affected branches. The generator does not read state_estimation.tap_estimation.exclude . When the set puts a deviation on a transformer the run keeps out, run.log names it. The deviation moves one changer per transformer, the first ratio changer, else the first phase changer. A machine transformer is used only when the case has nothing else. The tap estimation keeps machine transformers out by default ( state_estimation.tap_estimation.include_machine_transformers = false ) and calculates their step after the estimate, so a deviation there stays in the estimate as a model error ( J far above dof ). run.log warns in that case and names the key."),
  (title = "Generator: truth state", url = "/help/webui.se_generator_truth", kind = "control", text = "Where the truth state comes from: fresh solve solves the case now, from run adopts the solved voltages of a successful run of this case without re-solving. Truth state, flow placement, passive-node handling and a target number of critical measurements are configurable in the Web UI form."),
  (title = "Sequential elimination budget", url = "/help/webui.se_max_eliminations", kind = "control", text = "Upper bound of the sequential bad-data elimination: the worst localizable row is removed and the estimation rerun, up to this many times. 0 disables it. Upper bound for the sequential bad-data elimination: while the chi-square band test fails and a suspicious measurement (normalized residual at or above 3) is localizable ( wii 0.3), the worst row is deactivated and the estimation reruns, up to this many times. 0 disables elimination (diagnostics only)."),
  (title = "Measurement set", url = "/help/webui.se_measurement_file", kind = "control", text = "Measurement set the estimation runs on. Only sets of the selected case are listed (by the # case: line, else by file name), each with its case. The measurement table (first line sparlectra-measurement-table v1 , one row per measured value, keyed by element name or CGMES mRID, values in MW, MVAr, A, kV and degrees) is the measurement format of Sparlectra. The Web UI generator and \"add noise\" write it, and the sets shipped with the demo cases are tables. readMeasurementTable!(net; file) reads one set into net.measurements ; writeMeasurementTable(file, rows) writes rows, for example from generateMeasurementTableFromPF . The measurement CSV v1 is no longer read (see Removed: measurement CSV v1)."),
  (title = "Noise seed", url = "/help/webui.se_noise_seed", kind = "control", text = "Seed of the noise draw. The same seed reproduces the same noisy set, a different seed draws a fresh realization. A Sparlectra Case Format case stores its measurement set inside the file. An estimation on such a case needs no separate CSV; the run still writes measurements.csv into its output directory for reproducibility. Naming a set explicitly takes precedence, and a set generated for the case replaces the one the file carries (the newer data). Every other format requires a measurement file."),
  (title = "Estimate transformer taps", url = "/help/webui.se_tap_estimation", kind = "control", text = "On: each observable tap changer not excluded is estimated and fixed to a step. Off: each keeps its transferred step. state_estimation.tap_estimation.enabled (default true , Web UI \"estimate taps\") switches the tap estimation. Off, no changer becomes a state, even one released with setTapEstimation! : every changer keeps its transferred step (SSH profile or measurement file), and each row of tapEstimates and se_tap_estimates.csv says status = not_estimated , reason = disabled . The rows carry status ( estimated , out_of_range for an estimate too far outside the band, not_estimated , calculated for a machine transformer) and reason for every changer."),
  (title = "Check for updates", url = "/help/webui.update_check", kind = "control", text = "Asks GitHub for the latest release, only on this click. An installed copy can install it after a confirm; a git checkout shows the commands. Check for updates in the Info panel asks GitHub for the latest release of Welthulk/Sparlectra.jl (the page releases/latest , which redirects to the tag of the latest release; not the REST API, whose anonymous limit of 60 requests per hour is shared by every machine behind one network address) and compares it with the running version. The page says up to date, names the newer release with a link to its release notes, or names why the check failed (no network, timeout, HTTP error, an address without a release tag). The request has a timeout of 10 s and carries no data about the installation. An update started here hands the tag to the install script, which does not ask GitHub again. start_webui.jl started from a terminal runs the same check before the server starts (timeout 5 s) and, for a newer release on an installed copy, asks Install <version now? [y/N] ; only y or yes installs, through the updater described below, and the new version starts when it is done. Any other answer, no answer within 60 s, a git checkout or another copy (one line on how to update), no network or a start without a terminal starts the Web UI as before; --no-update-check or SPARLECTRA_UPDATE_CHECK=0 skips the check. What happens with a newer release depends on how the copy was installed: - Installed copy : a folder named Sparlectra without .git , with start_webui.jl and tools/install_webui.sh ( .bat on Windows), the layout the one-line install creates. Install update , after a confirm, writes an updater and a copy of the install script to logs/update/ next to the operation log, starts the updater detached and stops the Web UI. The updater waits until the Web UI process has ended, runs the install script unattended ( SPARLECTRA_UPDATE=1 ; a sysimage is rebuilt when the copy has one, the desktop launcher is written again when it exists) and starts the new version through start_webui.sh or start_webui.bat . The previous copy stays as Sparlectra.old ; the log is logs/update/update.log . On Linux and macOS the update and the new Web UI run without a terminal and write to that log. On Windows the update opens a console window of its own and waits until the console of the old Web UI is closed, because Windows does not move a folder that a program still uses. - Git checkout ( .git present): nothing is changed; the page shows git fetch --tags and git checkout of the release tag. - Anything else (standalone app, registry installation, a renamed download): the page shows the one-line install. The install action is refused while a run or a sysimage build is active, and for a Web UI started from a REPL, whose process does not end with the Web UI. It takes a POST from the update page only: the form carries a value that is new for every Web UI process, so another page in the browser cannot start it."),
]
